def text_choice_pairs(key):
    """[(value, label)] of an enum setting. The thermal camera list changes with the camera scan, so it is computed."""
    kind, extra = TEXT_SPECS[key]
    if str(extra).startswith("mover_"):
        return mover_choice_pairs(extra)
    if extra == "net_modes":
        return [("auto", tr("Automatic: known networks (e.g. phone hotspot), otherwise own Wi-Fi")),
                ("hotspot", tr("Own Wi-Fi at boot")), ("client", tr("Only known networks"))]
    if extra in ("light_white_out", "light_ir_out"):
        return light_out_pairs(extra[6:-4])
    if extra == "email_events":
        return [("alarms", tr("only alarms (person, warm, noise, sabotage)")), ("all", tr("all messages"))]
    if extra == "patrol_modes":
        return [("pendulum", tr("back and forth (1-2-3-2-1)")), ("loop", tr("round trip (1-2-3-1-2-3)"))]
    if extra == "rec_marks":
        return [("thin", tr("thin corner marks (face stays free)")), ("none", tr("none (clean picture)")), ("full", tr("like the live picture (red boxes)"))]
    if extra == "sms_modes":
        return [("auto", tr("automatic")), ("mmcli", "ModemManager (mmcli)"), ("at", tr("AT commands (serial port)")), ("hilink", "Huawei HiLink (192.168.8.1)")]
    if extra == "deter_acts":
        return [("off", tr("nothing")), ("sound", tr("sound")), ("light", tr("light flashes")), ("both", tr("sound + light flashes"))]
    if extra == "backup_types":
        return [("off", tr("off")), ("webdav", tr("WebDAV (Nextcloud, NAS, cloud)")), ("folder", tr("Folder (USB stick / NAS)")),
                ("telegram", tr("Telegram (video, max. 50 MB)"))]
    if extra == "light_auto":
        return [("alarm_dark", tr("at an alarm, only at night")), ("alarm", tr("at an alarm, day and night")),
                ("dark", tr("the whole night (sunset to sunrise)"))]
    if extra == "ups_model":
        return [("auto", tr("automatic")), ("e", "UPS HAT (E) – 4 × 21700, I2C 0x2D"), ("ina", "UPS HAT (A / B / C) – INA219")]
    if extra == "species_model":
        cur = str(CFG.get("species_model") or "")
        ms = species_models() + ([cur] if cur and cur not in species_models() else [])
        return [("", "– " + tr("none") + " –")] + [(m, m) for m in ms]
    if extra == "species_norm":
        return [("imagenet", "ImageNet (mean / std)"), ("01", "0 … 1"), ("-11", "-1 … 1")]
    if extra == "gpsmod_port":
        ports = sorted(set(glob.glob("/dev/ttyACM*") + glob.glob("/dev/ttyUSB*") + [p for p in ("/dev/serial0", "/dev/ttyAMA0") if os.path.exists(p)]))
        cur = str(CFG.get("gpsmod_port") or "auto")
        if cur not in ("auto", "gpsd") and cur not in ports:
            ports.append(cur)
        return [("auto", tr("automatic")), ("gpsd", "gpsd")] + [(p, p) for p in ports]
    if extra == "wind_gpio":
        cur = str(CFG.get("wind_gpio") or "")
        gs = sens_free_gpios() + ([int(cur)] if cur.isdigit() else [])
        return [("", "– " + tr("none") + " –")] + [(str(g), f"GPIO {g}") for g in sorted(set(gs))]
    if extra == "cam_rotate":
        return [("0", tr("not turned")), ("90", tr("90° to the right")), ("180", tr("upside down (180°)")), ("270", tr("90° to the left"))]
    if extra == "picture_mode":
        return [("color", tr("colour")), ("night_grey", tr("grey at night (good with a NoIR camera)")), ("grey", tr("always grey"))]
    if extra == "servo_driver":
        return [("auto", tr("automatic: PCA9685 if found, otherwise GPIO 17 / 27")), ("pca9685", "PCA9685 (I2C)"),
                ("gpio", tr("directly on GPIO 17 / 27"))]
    if extra == "pca_address":
        return [(f"0x{a:02x}", f"0x{a:02x}") for a in range(0x40, 0x48)]
    if extra in ("audio_in", "audio_out"):
        return audio_choice_pairs(extra[6:])
    if extra == "sounds":
        return sound_choice_pairs()
    if extra == "clap_acts":
        return clap_act_pairs()
    if extra == "sneeze_replies":
        return sneeze_reply_pairs()
    if extra == "siren_on":
        return [("off", tr("off")), ("person", tr("person alarm")), ("alarm", tr("person, thermal and noise alarm")),
                ("all", tr("every alarm, also the pre-alarm (movement)"))]
    if extra == "thermal_choices":
        act = STATE["source_id"]
        return ([("", "– " + tr("none") + " –"), ("senxor:0", "Waveshare Thermal-90 / 44 (SPI)")]
                + [(i["id"], i["name"]) for i in list_sources() if i["id"] not in ("auto", act)])
    return [(c, tr(c)) for c in extra]


def _http_ok(u):
    if not (isinstance(u, str) and len(u) <= 500 and re.match(r"^https?://[^\s]+$", u, re.I) is not None):
        return False
    try:                                                 # 2.95.35: a real server name (ntfy..sh stopped the internet check)
        from urllib.parse import urlparse
        h = urlparse(u).hostname or ""
        if not h or ".." in h or h.startswith((".", "-")) or h.endswith("-"):
            return False
        h.encode("idna")
        urlparse(u).port
    except (ValueError, UnicodeError):
        return False
    return True


I2C_KEYS = {"pca_address": "servo board (PCA9685)", "solar_addr": "solar meter (INA219)", "mover_addr": "motor driver (mover)",
            "ups_addr": "UPS HAT"}


def _i2c_active(key, cfg=None):
    c = cfg or CFG
    pca_on = c.get("servo_driver") == "pca9685" or (c.get("servo_driver") == "auto" and str(STATE.get("servo_backend", "")).startswith("pca9685"))
    return {"pca_address": pca_on, "solar_addr": bool(c.get("solar_on")),
            "mover_addr": c.get("mover_mode") != "off", "ups_addr": bool(c.get("ups_on"))}.get(key, False)


def i2c_conflicts(cfg=None):
    """2.95.35: two devices that are switched on with the same I2C address read each other's registers (wrong values)"""
    c = cfg or CFG; seen = {}; out = []
    for k in I2C_KEYS:
        if not _i2c_active(k, c):
            continue
        a = str(c.get(k, "")).lower()
        if a in seen:
            out.append((seen[a], k, a))
        else:
            seen[a] = k
    return out


def text_value(key):
    v = CFG[key]
    return ", ".join(v) if isinstance(v, list) else v


def set_text(key, value):
    spec = TEXT_SPECS.get(key)
    if spec is None:
        return False, "unknown setting"
    kind, extra = spec
    if kind == "enum":
        if value not in [c for c, _l in text_choice_pairs(key)]:
            return False, "invalid value"
        if key in I2C_KEYS or key in ("servo_driver", "mover_mode"):
            cf = i2c_conflicts(dict(CFG, **{key: value}))
            if cf:
                a_, b_, ad = cf[0]
                return False, trf("I2C address {a} is already used by the {x} - choose another address", a=ad, x=tr(I2C_KEYS[a_ if a_ != key else b_]))
        CFG[key] = value
        if key == "net_mode":
            NETAUTO["paused"] = False
            log_event("sys", f"Network mode: {value}")
        if key in ("servo_driver", "pca_address"):
            HW_REINIT["want"] = True                     # the servo driver is opened again (no restart needed)
        if key == "thermal_source" and value.startswith("senxor") and float(CFG["thermal_zoom"]) >= 99.9:
            CFG["thermal_zoom"] = 65                     # Thermal-90 (90 degrees) next to the Camera Module 3 (66 degrees)
        if key in ("audio_in", "audio_out"):
            log_event("sys", ("Microphone: " if key == "audio_in" else "Loudspeaker: ") + (dict(text_choice_pairs(key)).get(value) or "-"))
            if key == "audio_out" and not value:
                sound_stop()
    elif kind == "float":
        try:
            v = float(value)
        except (TypeError, ValueError):
            return False, "not a number"
        if not math.isfinite(v) or not extra[0] <= v <= extra[1]:
            return False, "out of range"
        CFG[key] = round(v, 4)
    elif kind == "hosts":
        hosts = [h for h in re.split(r"[,; ]+", str(value or "")) if h]
        if len(hosts) > 8 or not all(_HOST_RE.match(h) for h in hosts):
            return False, "invalid device name or address"
        CFG[key] = hosts
    else:
        v = str(value or "").strip()
        if v:
            if key == "mqtt_host" and not re.fullmatch(r"[A-Za-z0-9.\-:\[\]]{1,120}", v):
                return False, "invalid device name or address"
            if key == "sms_numbers" and not all(_PHONE_RE.match(n) for n in re.split(r"[,; ]+", v) if n):
                return False, "phone numbers like +41791234567"
            if key == "sms_port" and not re.fullmatch(r"/dev/[A-Za-z0-9_\-/]{2,40}", v):
                return False, "a port like /dev/ttyUSB2"
            if key == "sms_hilink" and not re.fullmatch(r"[A-Za-z0-9.\-]{3,60}(:\d{1,5})?", v):
                return False, "invalid device name or address"
            if key == "mqtt_port" and not (v.isdigit() and 1 <= int(v) <= 65535):
                return False, "port 1-65535"
            if key == "mqtt_prefix" and not re.fullmatch(r"[A-Za-z0-9_\-/]{1,60}", v):
                return False, "only letters, digits, - _ /"
            if key == "mqtt_user" and (len(v) > 120 or any(ord(c) < 32 for c in v)):
                return False, "text too long or with control characters"
            if key == "backup_url" and not re.match(r"^https?://[^\s]{4,500}$", v):
                return False, "invalid URL (http:// or https:// expected)"
            if key == "backup_folder" and not (v.startswith("/") and len(v) < 300 and ".." not in v):
                return False, "a folder like /media/... expected"
            if key == "backup_user" and (len(v) > 120 or any(ord(c) < 32 for c in v)):
                return False, "text too long or with control characters"
            if key == "sim_url" and not re.fullmatch(r"https?://[A-Za-z0-9.\-\[\]:]{1,120}/?", v):
                return False, "invalid URL (http:// or https:// expected)"
            if key in ("notify_url", "public_url") and not _http_ok(v):
                return False, "invalid URL (http:// or https:// expected)"
            if key == "msg_keyword_prefix" and not re.fullmatch(r"[A-Za-z0-9]{1,12}", v):
                return False, "1 to 12 letters or digits"
            if key == "email_to" and not _EMAIL_RE.fullmatch(v):
                return False, "invalid e-mail address"
            if key == "email_host" and not re.fullmatch(r"[A-Za-z0-9.\-]{3,120}", v):
                return False, "invalid device name or address"
            if key == "email_port" and v not in ("25", "465", "587", "2525"):
                return False, "port 587 or 465"
            if key == "email_user" and (len(v) > 120 or any(ord(c) < 32 for c in v)):
                return False, "text too long or with control characters"
            if key in ("pushover_user", "pushover_token") and not re.fullmatch(r"[A-Za-z0-9]{30}", v):
                return False, "30 letters and digits expected (from pushover.net)"
            if key == "telegram_token" and not re.fullmatch(r"\d{5,12}:[A-Za-z0-9_\-]{20,60}", v):
                return False, "invalid Telegram bot token"
            if key == "update_token" and not re.fullmatch(r"[A-Za-z0-9_]{20,255}", v):
                return False, "invalid GitHub key (it starts with github_pat_ or ghp_)"
            if key == "telegram_chat" and not re.fullmatch(r"-?\d{1,20}|@[A-Za-z0-9_]{3,64}", v):
                return False, "invalid Telegram chat id"
        if (key.startswith("msg_") or key == "device_name") and (len(v) > (40 if key == "device_name" else 300) or any(ord(c) < 32 for c in v)):
            return False, "text too long or with control characters"
        if key == "sneeze_texts" and (len(v) > 200 or any(ord(c) < 32 for c in v)):
            return False, "text too long or with control characters"
        if key == "update_url" and not _upd_source_ok(v):
            return False, "https://... address or a folder (/media/...) expected"
        if key == "hotspot_ssid" and (not v or len(v.encode()) > 32 or any(ord(c) < 32 for c in v)):
            return False, "invalid network name"
        if key == "hotspot_password" and not (8 <= len(v) <= 63 and all(32 <= ord(c) < 127 for c in v)):
            return False, "the password must have 8 to 63 characters"
        CFG[key] = v
    save_settings()
    return True, ""


def web_texts(lang=None):
    """Schema + current values for the web page (secrets are never sent, only whether they are set)."""
    out = []
    for sec, key, label, kind, extra in TEXTS:
        v = text_value(key)
        ph = ""
        m_ = re.fullmatch(r"msg_(person|prealarm|warm|noise)_(title|text)", key)
        if m_:
            ph = msg_defaults(lang)[m_.group(1)][0 if m_.group(2) == "title" else 1]
        elif key == "device_name":
            ph = "Motion Watch"
        elif key == "backup_url":
            ph = "https://cloud.example.ch/remote.php/dav/files/USER/MotionWatch/"
        out.append({"section": sec, "key": key, "label": tr(label, lang), "placeholder": ph,
                    "kind": kind, "choices": [c for c, _l in text_choice_pairs(key)] if kind == "enum" else None,
                    "labels": {c: l for c, l in text_choice_pairs(key)} if kind == "enum" else None,
                    "value": "" if kind == "secret" else v, "set": bool(v)})
    return out


# ----------------------------------------------------------------------------
# Schedules (time plans): switch features on / off at certain times
#   A schedule = name + weekdays + start/end time + a list of "feature -> ON / OFF".
#   While a schedule is active its features are forced; when it ends they go back to the value
#   the user had set.  Changing a forced switch by hand wins until the schedule changes.
#   Windows may cross midnight (22:00 -> 06:00 belongs to the day it starts on).
# ----------------------------------------------------------------------------
MAX_SCHEDULES = 12
MAX_EXTRA = 3
SCHEDULES = []          # [{"name", "enabled", "days": [0=Mon .. 6=Sun], "start": "HH:MM", "end": "HH:MM", "actions": {key: bool}}]
SCHED = {"base": {}, "manual": set(), "last": {}, "active": []}
SCHED_FEATURES = [      # (config key, label) - everything a schedule may switch
    ("detection_on", "Detection"), ("record", "Recording"), ("snapshot_on_person", "Snapshots"),
    ("track_person", "Person tracking"), ("patrol", "Patrol"), ("ai_enabled", "AI detection"),
    ("relays_on", "Auto relays"), ("notify_on", "Notifications"), ("timelapse_on", "Timelapse"), ("thermal_on", "Thermal overlay"),
    ("notify_prealarm", "Pre-alarm push"), ("browser_alarm", "Alarm sound in the browser"),
    ("armed", "Armed (alarms)"), ("thermal_alarm", "Thermal alarm"), ("noise_alarm", "Noise alarm"), ("eco_on", "Power saving"),
]
SCHED_KEYS = [k for k, _ in SCHED_FEATURES]
SCHED_NOTE = ("While a schedule is active, the listed features are forced ON or OFF. Afterwards they return to your own setting. "
              "Switching one by hand overrides the schedule until its next change.")
_TIME_RE = re.compile(r"^([01]\d|2[0-3]):([0-5]\d)$")


def _clean_time(v, default):
    return v if isinstance(v, str) and _TIME_RE.match(v) else default


def _day_ok(d):
    return isinstance(d, (int, float)) and not isinstance(d, bool) and math.isfinite(d) and 0 <= d <= 6


def _clean_schedule(s, i):
    """Validate / normalise one schedule dict (from the settings file, web page or desktop dialog)."""
    if not isinstance(s, dict):
        return None
    name = str(s.get("name") or "").strip()[:40] or f"Schedule {i + 1}"
    days = s.get("days", list(range(7)))
    days = sorted({int(d) for d in days if _day_ok(d)}) if isinstance(days, list) else list(range(7))
    acts = s.get("actions") if isinstance(s.get("actions"), dict) else {}
    off = s.get("sun_offset", 0)
    off = 0 if isinstance(off, bool) or not isinstance(off, (int, float)) or not math.isfinite(off) else int(max(-180, min(180, off)))
    return {"name": name, "enabled": bool(s.get("enabled", True)), "days": days,
            "start": _clean_time(s.get("start"), "22:00"), "end": _clean_time(s.get("end"), "06:00"),
            "sun": s.get("sun") if s.get("sun") in ("dark", "light") else "",        # "dark" = sunset..sunrise, "light" = sunrise..sunset
            "sun_offset": off,                                                       # minutes added to sunrise and sunset
            "presence": s.get("presence") if s.get("presence") in ("away", "home") else "",
            "skip": re.sub(r"[^0-9.,; \-]", "", str(s.get("skip") or ""))[:200].strip(),   # dates on which the schedule does not run
            "actions": {k: acts[k] for k in SCHED_KEYS if isinstance(acts.get(k), bool)}}


def _mins(hhmm):
    h, m = hhmm.split(":")
    return int(h) * 60 + int(m)


def sun_times(d, lat, lon):
    """Sunrise / sunset as minutes after local midnight (NOAA formula, about +-2 min). 'dark' / 'light' for polar night / day."""
    n = d.timetuple().tm_yday
    g = 2 * math.pi / 365.0 * (n - 1)
    eq = 229.18 * (0.000075 + 0.001868 * math.cos(g) - 0.032077 * math.sin(g) - 0.014615 * math.cos(2 * g) - 0.040849 * math.sin(2 * g))
    dec = (0.006918 - 0.399912 * math.cos(g) + 0.070257 * math.sin(g) - 0.006758 * math.cos(2 * g)
           + 0.000907 * math.sin(2 * g) - 0.002697 * math.cos(3 * g) + 0.00148 * math.sin(3 * g))
    la = math.radians(lat)
    c = math.cos(math.radians(90.833)) / (math.cos(la) * math.cos(dec)) - math.tan(la) * math.tan(dec)
    if c > 1:
        return "dark"
    if c < -1:
        return "light"
    ha = math.degrees(math.acos(c))
    try:
        tz = datetime(d.year, d.month, d.day, 12).astimezone().utcoffset().total_seconds() / 60.0
    except (OverflowError, OSError, ValueError):
        tz = 0.0
    return (720 - 4 * (lon + ha) - eq + tz, 720 - 4 * (lon - ha) - eq + tz)


@functools.lru_cache(maxsize=64)
def _parse_skip(text):
    """'2026-12-24..2026-12-26, 08-01' -> ranges. 'MM-DD' repeats every year."""
    def point(t):
        m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", t)
        try:
            if m:
                return ("d", datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).date())
            m = re.fullmatch(r"(\d{2})-(\d{2})", t)
            if m:
                datetime(2000, int(m.group(1)), int(m.group(2)))
                return ("y", (int(m.group(1)), int(m.group(2))))
        except ValueError:
            pass
        return None
    out = []
    for tok in re.split(r"[,; ]+", text or ""):
        if not tok:
            continue
        a, _, b = tok.partition("..")
        pa, pb = point(a), point(b or a)
        if pa and pb and pa[0] == pb[0]:
            out.append((pa[0], pa[1], pb[1]))
    return tuple(out)


def _is_skipped(s, d):
    for kind, a, b in _parse_skip(s.get("skip", "")):
        if kind == "d" and a <= d <= b:
            return True
        if kind == "y" and a <= (d.month, d.day) <= b:
            return True
    return False


def _window_start(s, dt):
    """The calendar day on which the time window that contains `dt` started (None = outside). A window that crosses midnight
    belongs to the day it starts on."""
    today, cur = dt.date(), dt.hour * 60 + dt.minute
    if s.get("sun"):
        r = sun_times(today, CFG["latitude"], CFG["longitude"])
        light = s["sun"] == "light"
        if r in ("dark", "light"):
            return today if (r == "light") == light else None
        rise, sset = r[0] + s.get("sun_offset", 0), r[1] + s.get("sun_offset", 0)
        if light:
            return today if rise <= cur < sset else None
        if cur >= sset:
            return today
        return today - timedelta(days=1) if cur < rise else None
    a, b = _mins(s["start"]), _mins(s["end"])
    if a == b:                                   # same start and end = the whole day
        return today
    if a < b:
        return today if a <= cur < b else None
    if cur >= a:
        return today
    return today - timedelta(days=1) if cur < b else None


def schedule_window_contains(s, dt):
    """Is the moment `dt` inside the schedule's weekdays + time window? (ignores 'enabled' and presence)"""
    if not s["days"]:
        return False
    d = _window_start(s, dt)
    return d is not None and d.weekday() in s["days"] and not _is_skipped(s, d)


def presence_ok(s):
    p = s.get("presence")
    home = PRESENCE["home"]
    if not p or home is None:                    # no rule, or presence unknown -> stay armed
        return True
    return home if p == "home" else not home


def schedule_active(s, dt=None):
    return bool(s["enabled"]) and schedule_window_contains(s, dt or datetime.now()) and presence_ok(s)


def days_text(days, names=("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")):
    days = sorted(days)
    if len(days) == 7:
        return "every day" if names[0] == "Mon" else "täglich"
    if days == [0, 1, 2, 3, 4]:
        return f"{names[0]}–{names[4]}"
    if days == [5, 6]:
        return f"{names[5]}, {names[6]}"
    return ", ".join(names[d] for d in days) or "–"


def schedule_tick():
    """Apply all schedules (called once per second by the Scheduler thread and after every edit)."""
    with LOCK:
        plans = [dict(s) for s in SCHEDULES]
    now = datetime.now()
    forced, active, active_idx = {}, [], []
    for i, s in enumerate(plans):
        if schedule_active(s, now):
            active.append(s["name"]); active_idx.append(i)
            forced.update(s["actions"])                  # later schedules win over earlier ones
    base, manual, last = SCHED["base"], SCHED["manual"], SCHED["last"]
    labels = dict(SCHED_FEATURES)
    prev = SCHED["active"]
    for n in active:
        if n not in prev:
            log_event("sched", f"Schedule started: {n}")
    for n in prev:
        if n not in active:
            log_event("sched", f"Schedule ended: {n}")
    SCHED["active"] = active
    for k, v in forced.items():
        if last.get(k) != v:
            manual.discard(k)                            # new window / new value -> the schedule takes over again
        if k in manual:
            continue
        if k not in base:
            base[k] = CFG[k]
        if CFG[k] != v:
            CFG[k] = v
            log_event("sched", f"Schedule: {labels.get(k, k)} {'ON' if v else 'OFF'}")
    for k in list(base):
        if k not in forced:                              # no schedule controls it any more -> give the user's value back
            CFG[k] = base.pop(k); manual.discard(k)
            log_event("sched", f"Schedule: {labels.get(k, k)} back to {'ON' if CFG[k] else 'OFF'}")
    SCHED["last"] = dict(forced)
    STATE["sched_active"] = list(active); STATE["sched_active_idx"] = active_idx
    STATE["sched_forced"] = dict(forced); STATE["sched_manual"] = sorted(manual)


def sched_user_changed(key):
    """A switch was changed by hand. If a schedule currently forces it, the user's choice wins until the schedule changes."""
    if key in SCHED["last"]:
        SCHED["manual"].add(key)
        SCHED["base"][key] = CFG[key]


def schedule_add():
    with LOCK:
        if len(SCHEDULES) >= MAX_SCHEDULES:
            return False, f"maximum {MAX_SCHEDULES} schedules"
        SCHEDULES.append(_clean_schedule({"name": f"Schedule {len(SCHEDULES) + 1}", "actions": {}}, len(SCHEDULES)))
    save_settings(); log_event("sched", "Schedule added")
    schedule_tick()
    return True, ""


def schedule_save(index, data):
    clean = _clean_schedule(data, index if isinstance(index, int) else 0)
    if clean is None:
        return False, "invalid schedule"
    with LOCK:
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < len(SCHEDULES):
            return False, "unknown schedule"
        SCHEDULES[index] = clean
    save_settings()
    schedule_tick()
    return True, ""


def schedule_remove(index):
    with LOCK:
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < len(SCHEDULES):
            return False, "unknown schedule"
        gone = SCHEDULES.pop(index)
    save_settings(); log_event("sched", f"Schedule removed: {gone['name']}")
    schedule_tick()
    return True, ""


class Scheduler:
    """Background thread: applies the time plans once per second."""
    def __init__(self):
        schedule_tick()
        threading.Thread(target=self.loop, daemon=True).start()

    def loop(self):
        while True:
            try:
                schedule_tick(); arm_tick()
            except Exception as e:                      # never let the scheduler thread die
                log_event("sys", f"Scheduler error: {e}")
            time.sleep(1.0)


# ----------------------------------------------------------------------------
# Settings persistence (autosaved 2 s after any change)
# ----------------------------------------------------------------------------
VOLATILE = {"web_stream", "web_password", "rain_mode", "fullscreen"}   # never restored from disk
_save_timer = None


WEB_UI_KEY = re.compile(r"^mw-[A-Za-z0-9_:\-./ ]{1,90}$")
WEB_UI_LOCAL = {"mw-sound", "mw-hdr", "mw-listen-vol"}                      # per device on purpose (sound on the phone, not on the PC)


# ---- web password set on the page / in the window: stored as a salted PBKDF2 hash; checked passwords are remembered
#      (as a keyed digest, only in memory) so the Pi does not have to compute the slow hash for every picture of the stream
_PW_KEY = os.urandom(32)
_PW_OK = set()


def pw_hash(pw):
    import hashlib
    salt = os.urandom(16)
    h = hashlib.pbkdf2_hmac("sha256", pw.encode(), salt, 200000)
    return f"pbkdf2${200000}${salt.hex()}${h.hex()}"


def pw_check(pw, stored=None):
    import hashlib
    stored = (CFG.get("web_pw_hash") or "") if stored is None else stored
    key = hmac.new(_PW_KEY, (stored + "|" + str(pw)).encode(), "sha256").digest()
    if key in _PW_OK:
        return True
    try:
        _alg, it, salt, h = stored.split("$")
        ok = hmac.compare_digest(hashlib.pbkdf2_hmac("sha256", str(pw).encode(), bytes.fromhex(salt), int(it)).hex(), h)
    except (ValueError, TypeError):
        return False
    if ok:
        if len(_PW_OK) > 50:
            _PW_OK.clear()
        _PW_OK.add(key)
    return ok


USER_ROLES = ("operate", "view")
_USER_RE = re.compile(r"^[A-Za-z0-9ÄÖÜäöüéèàç][A-Za-z0-9ÄÖÜäöüéèàç ._\-]{0,23}$")
# what an "operate" user may change (everything else is read-only); "view" may only look
OPERATE_POST = {"/api/tunnel", "/api/disco", "/api/helper", "/api/info", "/api/nettest", "/api/tv", "/api/mode", "/api/mover", "/api/arm", "/api/night", "/api/camping", "/api/quick", "/api/light", "/api/move", "/api/stick", "/api/talk",
                "/api/talk/stop", "/api/tts", "/api/rec/fav", "/api/rec/false", "/api/action"}
VIEW_POST = {"/api/webpush", "/api/time", "/api/gps", "/api/rec/prepare", "/rec/zip"}
OPERATE_SET_KEYS = {"thermal_on", "nightvision", "show_objects", "show_mask", "track_person"}
ADMIN_GET = ("/api/settings/export", "/api/ext", "/api/wifi", "/api/qr", "/setup-card", "/api/update", "/api/guest", "/api/fleet",
             "/api/users", "/api/setup", "/api/log/file/", "/api/tools", "/tools/diag.zip", "/api/usb")


def users_clean(lst):
    out, seen = [], set()
    for u in (lst if isinstance(lst, list) else [])[:20]:
        if not isinstance(u, dict):
            continue
        n = str(u.get("name", "")).strip()
        if not _USER_RE.match(n) or n.lower() in seen or not str(u.get("hash", "")).startswith("pbkdf2$"):
            continue
        seen.add(n.lower())
        out.append({"name": n, "hash": u["hash"], "role": u.get("role") if u.get("role") in USER_ROLES else "view"})
    return out


def user_login(name, pw):
    """(name, role) for a web login, or None. The web password = administrator (any user name)."""
    if CFG["web_password"]:
        if hmac.compare_digest(str(pw).encode(), str(CFG["web_password"]).encode()):
            return (name or "admin", "admin")
    elif CFG["web_pw_hash"] and pw_check(pw):
        return (name or "admin", "admin")
    for u in CFG["users"]:
        if u["name"].lower() == str(name or "").strip().lower() and pw_check(pw, u["hash"]):
            return (u["name"], u["role"])
    return None


TRUST_COOKIE = "mw_trust"


def _trust_hash(tok):
    import hashlib
    return hashlib.sha256(("mw-trust|" + str(tok)).encode()).hexdigest()


def trust_find(tok):
    """the trusted device of this cookie: (user, role) or None. The user must still exist (the administrator always does)."""
    if not tok or len(tok) < 20 or len(tok) > 100:
        return None
    h = _trust_hash(tok)
    for e in CFG.get("trusted") or []:
        if hmac.compare_digest(e.get("h", ""), h):
            u = e.get("user", "admin")
            if e.get("role", "admin") == "admin":
                return (u, "admin"), e
            for x in CFG["users"]:
                if x["name"].lower() == u.lower():
                    return (x["name"], x["role"]), e
            return None
    return None


def trust_add(user, role, ua, ip):
    """a new trusted device: returns the cookie value (only its hash is kept here)"""
    import secrets
    tok = secrets.token_urlsafe(32)
    name = "Gerät"
    for k, n in (("iPad", "iPad"), ("iPhone", "iPhone"), ("Android", "Android"), ("Macintosh", "Mac"), ("Windows", "Windows-PC"), ("Linux", "Linux")):
        if k in ua:
            name = n
            break
    for k, n in (("Edg/", "Edge"), ("Firefox", "Firefox"), ("Chrome", "Chrome"), ("Safari", "Safari")):
        if k in ua:
            name += " · " + n
            break
    lst = [e for e in (CFG.get("trusted") or [])][-29:]
    lst.append({"h": _trust_hash(tok), "user": user, "role": "admin" if role == "admin" else "user", "name": name, "t0": int(time.time()),
                "seen": int(time.time()), "ip": str(ip)[:45]})
    CFG["trusted"] = lst
    save_settings()
    log_event("web", f"Trusted device added: {name} ({user}, {ip})")
    return tok


def users_action(d, who="admin"):
    a = d.get("action")
    if a == "add":
        if not web_pw_active():
            return False, "set the web password first (it is the administrator)"
        n = str(d.get("name", "")).strip(); pw = str(d.get("password", ""))
        if not _USER_RE.match(n):
            return False, "name: 1 to 24 letters / digits"
        if any(u["name"].lower() == n.lower() for u in CFG["users"]):
            return False, "this name exists already"
        if not (6 <= len(pw) <= 64 and all(32 <= ord(c) < 127 for c in pw)):
            return False, "the password must have 6 to 64 characters (letters, digits, signs, no umlauts)"
        if len(CFG["users"]) >= 20:
            return False, "at most 20 users"
        CFG["users"] = users_clean(CFG["users"] + [{"name": n, "hash": pw_hash(pw), "role": d.get("role") if d.get("role") in USER_ROLES else "view"}])
        log_event("web", f"{who}: user «{n}» added ({CFG['users'][-1]['role']})")
    else:
        u = next((x for x in CFG["users"] if x["name"] == d.get("name")), None)
        if u is None:
            return False, "unknown user"
        if a == "remove":
            CFG["users"] = [x for x in CFG["users"] if x is not u]; log_event("web", f"{who}: user «{u['name']}» removed")
        elif a == "role" and d.get("role") in USER_ROLES:
            u["role"] = d["role"]; log_event("web", f"{who}: user «{u['name']}» now {u['role']}")
        elif a == "password":
            pw = str(d.get("password", ""))
            if not (6 <= len(pw) <= 64 and all(32 <= ord(c) < 127 for c in pw)):
                return False, "the password must have 6 to 64 characters (letters, digits, signs, no umlauts)"
            u["hash"] = pw_hash(pw); log_event("web", f"{who}: new password for «{u['name']}»")
        else:
            return False, "unknown action"
        CFG["trusted"] = [e for e in (CFG.get("trusted") or []) if e.get("user") != u["name"]]   # 2.95.33: log in again
    _PW_OK.clear(); save_settings_now()
    return True, ""


# 2.95.35: ONE list of what users without admin rights may read. Everything else (also every new function) is only for
# the administrator. Changing things (POST): VIEW_POST for everybody, OPERATE_POST (+ the keys below) for «operate».
VIEW_GET_PAGES = {"/", "/cams", "/recordings", "/diary", "/help", "/quick", "/preview", "/zones"}
VIEW_GET = ("/api/tunnel", "/api/dataset.zip", "/api/helper", "/api/info", "/api/nettest", "/api/state", "/api/alerts", "/api/appearance", "/api/version", "/api/health", "/api/cams", "/api/frame.jpg",
            "/video_feed", "/cam_feed/", "/snapshot.jpg", "/api/audio/live", "/api/recordings", "/api/places", "/rec/file/",
            "/rec/play/", "/rec/thumb/", "/rec/share/", "/rec/report/", "/api/day", "/api/diary", "/diary/img/", "/api/timelapse",
            "/timelapse/", "/api/species", "/api/loop", "/api/gps", "/api/zones", "/api/webpush", "/api/ui", "/api/report",
            "/api/battery", "/api/sensors", "/api/qs", "/api/schedule", "/api/schema", "/api/triggers", "/api/fa", "/api/appicon",
            "/api/audio", "/i18n/", "/app-icon/", "/sim-icon/", "/sim/view.jpg", "/sim/view.mjpg")


def role_allows(role, path, method, d):
    if role == "admin":
        return True
    if method in ("GET", "HEAD"):
        return (path in VIEW_GET_PAGES or path.startswith(VIEW_GET)) and not path.startswith(ADMIN_GET)
    if path == "/api/webpush":
        return d.get("action") in ("subscribe", "unsubscribe", "key", None)
    if path in VIEW_POST:
        return True
    if role != "operate":
        return False
    if path == "/api/set":
        return d.get("key") in OPERATE_SET_KEYS
    if path == "/api/audio":
        return d.get("action") in ("test", "siren", "stop")
    if path == "/api/action":
        return d.get("action") in ("center", "patrol")
    return path in OPERATE_POST


def web_pw_active():
    return bool(CFG["web_password"] or CFG["web_pw_hash"])


def web_pw_set(pw):
    """pw = "" removes the password. A password given on the command line (--web-password) always wins."""
    if CFG["web_password"]:
        return False, "the password was given on the command line (--web-password) - change it there"
    pw = str(pw or "")
    if pw and not (6 <= len(pw) <= 64 and all(32 <= ord(c) < 127 for c in pw)):
        return False, "the password must have 6 to 64 characters (letters, digits, signs, no umlauts)"
    CFG["web_pw_hash"] = pw_hash(pw) if pw else ""
    _PW_OK.clear()
    CFG["trusted"] = []                                    # a new password: every device logs in again
    save_settings_now()
    log_event("web", "Web password set" if pw else "Web password removed")
    return True, ""


def clean_web_ui(d):
    out = {}
    if isinstance(d, dict):
        for k, v in list(d.items())[:400]:
            if isinstance(k, str) and WEB_UI_KEY.match(k) and k not in WEB_UI_LOCAL and isinstance(v, str) and len(v) <= 4000:
                out[k] = v
    return out


def web_ui_update(changes, removes=()):
    if not isinstance(changes, dict):
        return False
    cur = dict(CFG["web_ui"])
    cur.update(clean_web_ui(changes))
    for k in (removes if isinstance(removes, list) else []):
        cur.pop(k, None)
    CFG["web_ui"] = clean_web_ui(cur)                # re-assign: DEFAULTS share the old dict
    save_settings()
    return True


def settings_status_text(lang=None):
    """The settings line (saved / loaded / defaults) in the language of the page / window."""
    st = str(STATE.get("settings_status", ""))
    m = re.match(r"^saved (\S+)$", st)
    if m:
        return trf("saved {t}", lang, t=m.group(1))
    m = re.match(r"^loaded (\d+) settings, (\d+) waypoints, (\d+) relays, (\d+) schedules$", st)
    if m:
        return trf("loaded: {a} settings, {b} waypoints, {c} relays, {d} schedules", lang, a=m.group(1), b=m.group(2), c=m.group(3), d=m.group(4))
    if st.startswith("save failed: "):
        return tr("save failed", lang) + ": " + st[13:]
    return tr(st, lang)


def _read_settings_file(p):
    with open(p) as f:
        d = json.load(f)
    if not isinstance(d, dict) or not isinstance(d.get("cfg", {}), dict):
        raise ValueError("not a settings object")
    return d


def load_settings():
    """2.95.33: a broken file (power cut while saving) is kept as .bad and the backup copy of the last good settings is
    used instead - otherwise password, users and messages would silently fall back to the defaults."""
    try:
        data = _read_settings_file(SETTINGS_FILE)
    except OSError:
        STATE["settings_status"] = "defaults (no file yet)"
        return
    except ValueError:
        bad = SETTINGS_FILE + ".bad-" + datetime.now().strftime("%Y%m%d-%H%M%S")
        try:
            shutil.copy2(SETTINGS_FILE, bad)
        except OSError:
            pass
        try:
            data = _read_settings_file(os.path.join(DATA_DIR, "motionwatch_settings.backup.json"))
            STATE["settings_restored"] = bad; STATE["settings_from_backup"] = True
        except (OSError, ValueError):
            STATE["settings_status"] = "defaults (settings file damaged, no usable backup)"
            STATE["settings_restored"] = bad; STATE["settings_from_backup"] = False
            return
    apply_settings(data)
    if STATE.get("settings_from_backup"):
        STATE["settings_status"] = "restored from the backup copy (the settings file was damaged)"
    if isinstance(data, dict) and isinstance(data.get("cfg"), dict) and "setup_done" not in data["cfg"]:
        CFG["setup_done"] = True                     # settings from an earlier version: already set up


def settings_data():
    """Everything that is saved (also used for "export settings")."""
    return {"cfg": {k: SCHED["base"].get(k, v) for k, v in CFG.items() if k not in VOLATILE}, "waypoints": list(WAYPOINTS),
            "relays": [dict(r) for r in RELAYS], "schedules": [dict(x) for x in SCHEDULES], "zones": [dict(z) for z in ZONES],
            "saved": datetime.now().isoformat(timespec="seconds")}


SETTINGS_GEN = {"n": 0}                  # +1 after an import: the window rebuilds itself


def import_settings(data):
    """Settings from an exported file. The current file is kept as motionwatch_settings.before_import.json."""
    if not isinstance(data, dict) or not isinstance(data.get("cfg"), dict):
        return False, "not a Motion Watch settings file"
    try:
        shutil.copy2(SETTINGS_FILE, os.path.join(DATA_DIR, "motionwatch_settings.before_import.json"))
    except OSError:
        pass
    data = dict(data); data["cfg"] = {k: v for k, v in data["cfg"].items() if k not in ("record_dir",)}   # 2.95.34
    apply_settings(data)
    save_settings_now()
    HW_REINIT["want"] = True; _PW_OK.clear(); SETTINGS_GEN["n"] += 1
    log_event("sys", "Settings imported (the previous ones are in motionwatch_settings.before_import.json)")
    return True, ""


def apply_settings(data):
    n = 0
    if not isinstance(data, dict):
        return
    try:
        specs = web_specs()
    except Exception:
        specs = {}
    cfg_in = data.get("cfg", {}) if isinstance(data.get("cfg", {}), dict) else {}
    for k, v in cfg_in.items():
        if k not in CFG or k in VOLATILE:
            continue
        if isinstance(v, type(CFG[k])) or (isinstance(CFG[k], float) and isinstance(v, int) and not isinstance(v, bool)):
            v = type(CFG[k])(v)
            sp = specs.get(k) or {}
            if isinstance(v, (int, float)) and not isinstance(v, bool) and sp.get("type") != "bool":
                if isinstance(v, float) and not math.isfinite(v):
                    continue
                if "min" in sp:
                    v = type(CFG[k])(max(sp["min"], v))
                if "max" in sp:
                    v = type(CFG[k])(min(sp["max"], v))
            CFG[k] = v; n += 1
    wps = []
    for w in data.get("waypoints", []):
        if isinstance(w, (int, float)) and not isinstance(w, bool):        # old files: pan only
            wps.append([float(w), float(CFG["patrol_tilt"])])
        elif isinstance(w, (list, tuple)) and len(w) == 2 and all(isinstance(x, (int, float)) for x in w):
            wps.append([max(0.0, min(100.0, float(w[0]))), max(0.0, min(100.0, float(w[1])))])
    WAYPOINTS[:] = wps[:50]
    CFG["ui_hidden"] = [k for k in CFG["ui_hidden"] if isinstance(k, str)][:200]
    CFG["ui_open"] = [k for k in CFG["ui_open"] if isinstance(k, str)][:100]
    _ql = CFG["qs_layout"] if isinstance(CFG["qs_layout"], dict) else {}
    CFG["qs_layout"] = {"order": [k for k in (_ql.get("order") or []) if isinstance(k, str)][:60], "hidden": [k for k in (_ql.get("hidden") or []) if isinstance(k, str)][:60]}
    CFG["web_ui"] = clean_web_ui(CFG["web_ui"])
    rl = data.get("relays")
    if isinstance(rl, list):
        used, out = set(), []
        for r in rl[:MAX_RELAYS]:
            if isinstance(r, dict):
                c = _clean_relay(r, len(out), used)
                if c:
                    out.append(c); used.add(c["gpio"])
        RELAYS[:] = out
    else:                                    # settings file from 1.2.2 -> migrate the single relay
        old = data.get("cfg", {}); r0 = default_relays()[0]
        if old.get("relay_on_person") is False:
            r0["mode"] = "off"
        if isinstance(old.get("relay_hold"), (int, float)) and not isinstance(old.get("relay_hold"), bool):
            r0["hold"] = max(0.5, min(600.0, float(old["relay_hold"])))
        RELAYS[:] = [r0]
    sc = data.get("schedules")
    if isinstance(sc, list):
        out = []
        for x in sc[:MAX_SCHEDULES]:
            c = _clean_schedule(x, len(out))
            if c:
                out.append(c)
        SCHEDULES[:] = out
    zl = data.get("zones")
    if isinstance(zl, list):
        ZONES[:] = [z for z in (_clean_zone(x, i) for i, x in enumerate(zl[:MAX_ZONES])) if z]
    CFG["presence_hosts"] = [h for h in CFG["presence_hosts"] if isinstance(h, str) and _HOST_RE.match(h)][:8]
    CFG["extra_cams"] = [x for x in CFG["extra_cams"] if isinstance(x, str) and SRC_RE.match(x) and x != "auto"][:MAX_EXTRA]
    CFG["fleet"] = [d for d in CFG["fleet"] if isinstance(d, dict) and isinstance(d.get("url"), str) and _FLEET_URL.match(d["url"])
                    and isinstance(d.get("id"), str)][:12]
    if CFG["notify_type"] not in NOTIFY_TYPES:
        CFG["notify_type"] = "webhook"
    CFG["ip_sources"] = _clean_ip_sources(CFG["ip_sources"])
    CFG["sensors"] = sens_clean(CFG["sensors"])
    CFG["users"] = users_clean(CFG["users"])
    if not SRC_RE.match(str(CFG["source"])):
        CFG["source"] = "auto"
    STATE["settings_status"] = f"loaded {n} settings, {len(WAYPOINTS)} waypoints, {len(RELAYS)} relays, {len(SCHEDULES)} schedules"
    log_event("sys", f"Settings loaded from {SETTINGS_FILE} ({n} values, {len(WAYPOINTS)} waypoints, {len(RELAYS)} relays, {len(SCHEDULES)} schedules)")


_SAVE_LOCK = threading.Lock()


def save_settings_now():
    """Atomic: own temp file, flushed to the card (fsync) before it replaces the old one; one save at a time."""
    with _SAVE_LOCK:
        tmp = f"{SETTINGS_FILE}.{os.getpid()}.{threading.get_ident()}.tmp"
        try:
            txt = json.dumps(settings_data(), indent=1)
            with open(tmp, "w") as f:
                f.write(txt); f.flush(); os.fsync(f.fileno())
            try:
                os.chmod(tmp, 0o600)
            except OSError:
                pass
            os.replace(tmp, SETTINGS_FILE)
            try:
                dfd = os.open(os.path.dirname(os.path.abspath(SETTINGS_FILE)), os.O_RDONLY)
                try:
                    os.fsync(dfd)
                finally:
                    os.close(dfd)
            except OSError:
                pass
            STATE["settings_status"] = "saved " + datetime.now().strftime("%H:%M:%S")
        except Exception as e:                          # also TypeError / RuntimeError: must not vanish in a thread
            STATE["settings_status"] = f"save failed: {e}"[:200]
            try:
                os.remove(tmp)
            except OSError:
                pass


def save_settings():
    """Debounced: many slider moves -> one write."""
    global _save_timer
    if _save_timer:
        _save_timer.cancel()
    _save_timer = threading.Timer(2.0, save_settings_now); _save_timer.daemon = True; _save_timer.start()


def reset_settings():
    for k, v in DEFAULTS.items():
        if k not in VOLATILE and k not in ("pan", "tilt", "source", "ip_sources", "extra_cams", "latitude", "longitude",
                                           "presence_hosts", "telegram_token", "telegram_chat", "public_url", "notify_url", "notify_type",
                                           "pushover_user", "pushover_token", "email_to", "email_host", "email_port", "email_user",
                                           "email_password", "email_from", "shortcut_token",
                                           "web_ui", "ui_open", "ui_hidden", "theme", "lang"):
            CFG[k] = v
    WAYPOINTS.clear()
    RELAYS[:] = default_relays()
    ZONES.clear(); SCHEDULES.clear(); SCHED["base"].clear(); SCHED["manual"].clear(); SCHED["last"] = {}; SCHED["active"] = []
    save_settings_now()
    log_event("sys", "Settings reset to defaults")


