SIMPROC = {"p": None}


def sim_dir():
    return os.path.join(DATA_DIR, "simulator")


def _desktop_user():
    """(uid, gid, home, name) of the person at the desktop (the service often runs as root) - or of this program."""
    import pwd
    for d in sorted(glob.glob("/run/user/*")):
        try:
            uid = int(os.path.basename(d))
        except ValueError:
            continue
        if uid >= 1000 and (glob.glob(os.path.join(d, "wayland-*")) or os.path.exists(os.path.join(d, "bus"))):
            try:
                p = pwd.getpwuid(uid); return uid, p.pw_gid, p.pw_dir, p.pw_name
            except KeyError:
                continue
    p = pwd.getpwuid(os.getuid())
    return p.pw_uid, p.pw_gid, p.pw_dir, p.pw_name


def sim_install():
    """Unpack the simulator into <data>/simulator, add a menu entry and a desktop icon for the person at the Pi."""
    import base64, io
    d = sim_dir(); os.makedirs(d, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(SIM_ZIP_B64.split())))) as z:
        for n in z.namelist():
            if re.fullmatch(r"[A-Za-z0-9_.]+", n):
                with open(os.path.join(d, n), "wb") as f:
                    f.write(z.read(n))
    os.chmod(os.path.join(d, "motionwatch_simulator.py"), 0o755)
    icon = os.path.join(d, "simulator.png")
    try:
        import base64
        with open(icon, "wb") as f:
            f.write(base64.b64decode("".join(SIM_ICONS_PNG["simbasis"])))      # MW Sim · Basis: the radar eye with the grey badge
    except Exception:
        pass
    entry = ("[Desktop Entry]\nType=Application\nName=MW Sim · Basis\nComment=Test Motion Watch without hardware\n"
             f"Exec={sys.executable} {os.path.join(d, 'motionwatch_simulator.py')}\nPath={d}\nIcon={icon}\nTerminal=false\nCategories=Utility;\n")
    uid, gid, home, name = _desktop_user()
    made = []
    for folder in (os.path.join(home, ".local", "share", "applications"), os.path.join(home, "Desktop"), os.path.join(home, "Schreibtisch")):
        if folder.endswith(("Desktop", "Schreibtisch")) and not os.path.isdir(folder):
            continue
        try:
            os.makedirs(folder, exist_ok=True)
            p = os.path.join(folder, "motionwatch-simulator.desktop")
            with open(p, "w") as f:
                f.write(entry)
            os.chmod(p, 0o755)
            if os.getuid() == 0:
                os.chown(p, uid, gid)
            made.append(p)
        except OSError:
            continue
    if os.getuid() == 0:
        for root_, _ds, fs in os.walk(d):
            for x in fs + [""]:
                try:
                    os.chown(os.path.join(root_, x) if x else root_, uid, gid)
                except OSError:
                    pass
    log_event("sys", f"Simulator installed in {d}" + (f" (menu / desktop icon for {name})" if made else ""))
    return True, d


def sim_running():
    p = SIMPROC["p"]
    return p is not None and p.poll() is None


def sim_start():
    """Start the simulator on this Pi: with its window on the desktop when somebody is logged in, otherwise without window."""
    if sim_running():
        return True, ""
    exe = os.path.join(sim_dir(), "motionwatch_simulator.py")
    if not os.path.isfile(exe):
        ok, _ = sim_install()
    else:
        sim_autoupdate()
    uid, gid, home, name = _desktop_user()
    env = dict(os.environ)
    run = f"/run/user/{uid}"
    way = sorted(glob.glob(os.path.join(run, "wayland-*")))
    window = bool(way) or os.path.exists("/tmp/.X11-unix/X0") or bool(os.environ.get("DISPLAY"))
    if window:
        env.update(XDG_RUNTIME_DIR=run, HOME=home, USER=name)
        if way:
            env["WAYLAND_DISPLAY"] = os.path.basename([w for w in way if not w.endswith(".lock")][0]) if [w for w in way if not w.endswith(".lock")] else "wayland-0"
        env.setdefault("DISPLAY", ":0")
    cmd = [sys.executable, exe] + ([] if window else ["--no-window"])
    kw = {"user": uid, "group": gid} if os.getuid() == 0 and uid != 0 else {}
    try:
        SIMPROC["p"] = subprocess.Popen(cmd, cwd=sim_dir(), env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                        start_new_session=True, **kw)
    except (OSError, ValueError) as e:
        return False, str(e)[:120]
    CFG["sim_url"] = "http://127.0.0.1:8765"; save_settings()
    log_event("sys", "Simulator started on this device" + (" (with window)" if window else " (without window)"))
    return True, ""


def sim_stop():
    p = SIMPROC["p"]
    if p is not None and p.poll() is None:
        try:
            os.killpg(p.pid, signal.SIGTERM)
        except OSError:
            p.terminate()
        log_event("sys", "Simulator stopped")
    SIMPROC["p"] = None
    return True, ""


def sens_has_pir():
    return CFG["sens_on"] and any(x["kind"] == "pir" and x["src"] for x in CFG["sensors"])


def eco_fps_now():
    f = max(1.0, float(CFG["eco_fps"]))
    return 1.0 if CFG["eco_pir"] and sens_has_pir() else f


def sms_numbers():
    return [n for n in re.split(r"[,; ]+", CFG["sms_numbers"]) if _PHONE_RE.match(n)][:5]


def _sms_mmcli(num, text):
    exe = shutil.which("mmcli")
    if not exe:
        return False, "mmcli missing (sudo apt install modemmanager)"
    rc, out, err = _run([exe, "-L"], 15)
    m = re.search(r"/Modem/(\d+)", out or "")
    if not m:
        return False, "no modem found (stick plugged in? mmcli -L)"
    safe = text.replace("'", "’").replace("\\", "/")
    for pre in ([], ["sudo", "-n"]):
        rc, out, err = _run(pre + [exe, "-m", m.group(1), f"--messaging-create-sms=text='{safe}',number='{num}'"], 20)
        sm = re.search(r"/SMS/(\d+)", out or "")
        if rc == 0 and sm:
            rc2, out2, err2 = _run(pre + [exe, "-s", sm.group(1), "--send"], 60)
            if rc2 == 0:
                return True, ""
            err = err2 or out2
    return False, ("mmcli: " + (err or out or "error").strip())[:160]


def _sms_at(num, text):
    import termios
    port = CFG["sms_port"].strip() or "/dev/ttyUSB2"
    if not os.path.exists(port):
        return False, f"{port} not found"
    try:
        fd = os.open(port, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
    except OSError as e:
        return False, f"{port}: {e.strerror} (in use by ModemManager?)"
    try:
        a = termios.tcgetattr(fd)
        a[4] = a[5] = termios.B115200; a[2] |= termios.CLOCAL | termios.CREAD; a[3] = 0; a[1] = 0; a[0] = 0
        termios.tcsetattr(fd, termios.TCSANOW, a)

        def cmd(b, wait=2.0, until=(b"OK", b"ERROR", b">")):
            os.write(fd, b)
            buf = b""; end = time.time() + wait
            while time.time() < end:
                try:
                    c = os.read(fd, 256)
                    buf += c
                    if any(u in buf for u in until):
                        break
                except BlockingIOError:
                    time.sleep(0.05)
            return buf
        if b"OK" not in cmd(b"AT\r"):
            return False, "the modem does not answer (wrong port?)"
        cmd(b"AT+CMGF=1\r")
        cmd(b'AT+CSCS="GSM"\r')
        if b">" not in cmd(f'AT+CMGS="{num}"\r'.encode(), 5):
            return False, "the modem refuses the SMS"
        for a_, b_ in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("Ä", "Ae"), ("Ö", "Oe"), ("Ü", "Ue"), ("ß", "ss"), ("–", "-"), ("’", "'"), ("«", '"'), ("»", '"')):
            text = text.replace(a_, b_)
        txt = text.encode("ascii", "replace")[:160]
        r = cmd(txt + b"\x1a", 60, (b"+CMGS", b"ERROR"))
        return (True, "") if b"+CMGS" in r else (False, "SMS not sent (credit / network?)")
    finally:
        os.close(fd)


def _sms_hilink(num, text):
    import http.cookiejar
    base = "http://" + (CFG["sms_hilink"].strip() or "192.168.8.1")
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}), urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
    try:
        with op.open(base + "/api/webserver/SesTokInfo", timeout=8) as r:
            x = r.read().decode(errors="replace")
        ses = re.search(r"<SesInfo>(.*?)</SesInfo>", x); tok = re.search(r"<TokInfo>(.*?)</TokInfo>", x)
        if not tok:
            return False, "HiLink stick not found (address?)"
        from xml.sax.saxutils import escape
        body_ = (f"<?xml version='1.0' encoding='UTF-8'?><request><Index>-1</Index><Phones><Phone>{escape(num)}</Phone></Phones><Sca></Sca>"
                 f"<Content>{escape(text[:300])}</Content><Length>{len(text[:300])}</Length><Reserved>1</Reserved>"
                 f"<Date>{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}</Date></request>").encode()
        h = {"__RequestVerificationToken": tok.group(1), "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"}
        if ses:
            h["Cookie"] = ses.group(1)
        with op.open(urllib.request.Request(base + "/api/sms/send-sms", data=body_, headers=h), timeout=20) as r:
            ans = r.read().decode(errors="replace")
        return (True, "") if "<response>OK</response>" in ans else (False, "HiLink: " + (re.search(r"<code>(\d+)</code>", ans).group(1) if "<code>" in ans else "error"))
    except Exception as e:
        return False, f"HiLink: {str(e)[:120]}"


def sms_send(text, force=False):
    """Send `text` to all numbers. force=True (test) ignores the limits."""
    nums = sms_numbers()
    if not nums:
        return False, "no phone number set"
    now = time.time()
    SMS["sent"] = [t for t in SMS["sent"] if now - t < 86400]
    if not force:
        if now - SMS["last"] < float(CFG["sms_pause"]) * 60:
            return False, "pause between two SMS"
        if len(SMS["sent"]) >= int(CFG["sms_day_max"]):
            return False, "daily limit reached"
    mode = CFG["sms_mode"]
    order = {"mmcli": [_sms_mmcli], "at": [_sms_at], "hilink": [_sms_hilink]}.get(mode, [_sms_mmcli, _sms_hilink, _sms_at])
    text = re.sub(r"\s+", " ", text).strip()[:300]
    errs = []
    ok_any = False
    for n in nums:
        ok = False
        for f in order:
            ok, err = f(n, text)
            if ok:
                break
            errs.append(err)
        ok_any = ok_any or ok
    SMS["last"] = now
    if ok_any:
        SMS["sent"].append(now)
    SMS["status"] = (f"✓ {datetime.now().strftime('%H:%M')}" if ok_any else "⚠ " + (errs[-1] if errs else "error"))[:160]
    log_event("web", ("SMS sent" if ok_any else "SMS failed: " + (errs[-1] if errs else "error"))[:200])
    return ok_any, "" if ok_any else (errs[-1] if errs else "error")

# ----------------------------------------------------------------------------
# Feedback to the developer: from the page / the window, anonymous in both directions (no address of the sender, the
#   destination is not shown). Sent by the Pi; without internet it waits and is sent later.
# ----------------------------------------------------------------------------
_FB_DEST = "aHR0cHM6Ly9udGZ5LW1lLmNvbS9tdy1mYi0xYzE3ZTFkMWViNWZhMmFhZTQ5Nw=="
FEEDBACK = {"sent": [], "lock": threading.Lock()}


def _fb_file():
    return os.path.join(DATA_DIR, "feedback_outbox.json")


def feedback_send(kind, text, contact="", diag=False):
    text = str(text or "").strip()[:3000]
    if len(text) < 3:
        return False, "please write a few words"
    now = time.time()
    FEEDBACK["sent"] = [x for x in FEEDBACK["sent"] if now - x < 3600]
    if len(FEEDBACK["sent"]) >= 5:
        return False, "at most 5 messages per hour"
    kind = kind if kind in ("idea", "bug", "praise", "other") else "other"
    body_ = text + (("\n\nKontakt: " + str(contact)[:120]) if contact else "")
    if diag:
        imp = [e for e in STATE["events"] if e.get("imp")][:8]
        body_ += (f"\n\n--- Technik ---\nVersion {APP_VERSION} · Python {sys.version.split()[0]} · {platform_model()} · "
                  f"Sprache {CFG['lang']} · Laufzeit {int((now - START) / 3600)} h\n" + "\n".join(f"{e.get('t', '')} {e.get('text', '')[:140]}" for e in imp))
    msg = {"kind": kind, "body": body_, "t": datetime.now().isoformat(timespec="seconds")}
    FEEDBACK["sent"].append(now)
    with FEEDBACK["lock"]:
        box = _fb_load(); box.append(msg); _fb_save(box[-20:])
    threading.Thread(target=feedback_flush, daemon=True).start()
    log_event("web", "Feedback written - it is sent to the developer (also later, when there is internet)")
    return True, ""


def _fb_load():
    try:
        with open(_fb_file()) as f:
            return [x for x in json.load(f) if isinstance(x, dict)]
    except (OSError, ValueError):
        return []


def _fb_save(box):
    try:
        with open(_fb_file(), "w") as f:
            json.dump(box, f)
    except OSError:
        pass


def feedback_flush():
    """Send what is waiting. Called after writing and every 10 minutes."""
    import base64
    with FEEDBACK["lock"]:
        box = _fb_load()
        if not box:
            return
        url = base64.b64decode(_FB_DEST).decode()
        left = []
        for m in box:
            title = {"idea": "Idee", "bug": "Fehler", "praise": "Lob", "other": "Feedback"}[m.get("kind", "other")]
            try:
                req = urllib.request.Request(url, data=m["body"].encode(), method="POST",
                                             headers={"Title": _hdr("Motion Watch – " + title), "Tags": {"bug": "bug", "idea": "bulb", "praise": "star"}.get(m.get("kind"), "speech_balloon")})
                with urllib.request.urlopen(req, timeout=15) as r:
                    if r.status >= 300:
                        left.append(m)
            except Exception:
                left.append(m)
        _fb_save(left)
        if len(left) < len(box):
            log_event("web", f"Feedback sent ({len(box) - len(left)})")


def platform_model():
    try:
        with open("/proc/device-tree/model") as f:
            return f.read().strip("\x00 \n")[:60]
    except OSError:
        import platform
        return platform.machine()


def feedback_loop():
    while True:
        time.sleep(600)
        try:
            feedback_flush()
        except Exception:
            pass

# ----------------------------------------------------------------------------
# Sharing with a small logo: pictures (animal diary, snapshots, night report) and videos (recordings, timelapse) get a
#   discreet strip at the bottom right: app icon + "Motion Watch" + what / when. Every shared fox picture is a little advert.
# ----------------------------------------------------------------------------
_FONT_CACHE = {}


def _font(size, bold=True):
    key = (size, bold)
    if key not in _FONT_CACHE:
        from PIL import ImageFont
        f = None
        for n in (("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf"), "LiberationSans-Bold.ttf"):
            for d in ("/usr/share/fonts/truetype/dejavu", "/usr/share/fonts/truetype/liberation", "/usr/share/fonts/TTF"):
                try:
                    f = ImageFont.truetype(os.path.join(d, n), size); break
                except OSError:
                    continue
            if f:
                break
        _FONT_CACHE[key] = f or ImageFont.load_default()
    return _FONT_CACHE[key]


def brand_strip(width, caption=""):
    """RGBA picture of the logo strip for a picture / video `width` pixels wide (PIL), or None without PIL."""
    try:
        from PIL import Image, ImageDraw
    except ImportError:
        return None
    hgt = max(26, int(width * 0.045)); pad = max(5, hgt // 5)
    f1, f2 = _font(int(hgt * 0.42)), _font(int(hgt * 0.32), bold=False)
    title = "Motion Watch"; cap = str(caption or "")[:60]
    tmp = ImageDraw.Draw(Image.new("RGBA", (10, 10)))
    tw = max(tmp.textlength(title, font=f1), tmp.textlength(cap, font=f2) if cap else 0)
    icon = int(hgt - 2 * pad + pad)
    w_ = int(icon + 3 * pad + tw); h_ = hgt
    im = Image.new("RGBA", (w_, h_), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rounded_rectangle((0, 0, w_ - 1, h_ - 1), radius=h_ // 3, fill=(10, 14, 20, 165))
    ic = cv2.imdecode(np.frombuffer(app_icon_png(128), np.uint8), cv2.IMREAD_COLOR)
    ic = Image.fromarray(cv2.cvtColor(ic, cv2.COLOR_BGR2RGB)).resize((icon - pad // 2, icon - pad // 2))
    mask = Image.new("L", ic.size, 0); ImageDraw.Draw(mask).rounded_rectangle((0, 0, ic.size[0] - 1, ic.size[1] - 1), radius=ic.size[0] // 4, fill=255)
    im.paste(ic, (pad, (h_ - ic.size[1]) // 2), mask)
    x = pad * 2 + ic.size[0]
    if cap:
        d.text((x, int(h_ * 0.08)), title, font=f1, fill=(255, 255, 255, 255))
        d.text((x, int(h_ * 0.55)), cap, font=f2, fill=(255, 190, 140, 255))
    else:
        d.text((x, (h_ - f1.size) // 2 - 1), title, font=f1, fill=(255, 255, 255, 255))
    return im


def brand_image(img_bgr, caption=""):
    """Picture (BGR) with the logo strip at the bottom right. Without PIL: a plain text line (cv2)."""
    h, w = img_bgr.shape[:2]
    strip = brand_strip(w, caption)
    out = img_bgr.copy()
    m = max(6, w // 80)
    if strip is None:
        txt = "Motion Watch" + ((" - " + caption.encode("ascii", "replace").decode()) if caption else "")
        cv2.putText(out, txt, (m, h - m), cv2.FONT_HERSHEY_SIMPLEX, max(0.4, w / 1600), (255, 255, 255), max(1, w // 800), cv2.LINE_AA)
        return out
    a = np.array(strip); sh, sw = a.shape[:2]
    if sw + 2 * m > w or sh + 2 * m > h:
        return out
    y0, x0 = h - sh - m, w - sw - m
    rgb = cv2.cvtColor(a[:, :, :3], cv2.COLOR_RGB2BGR).astype(np.float32); al = a[:, :, 3:4].astype(np.float32) / 255.0
    roi = out[y0:y0 + sh, x0:x0 + sw].astype(np.float32)
    out[y0:y0 + sh, x0:x0 + sw] = (rgb * al + roi * (1 - al)).astype(np.uint8)
    return out


def brand_jpg(data, caption="", quality=88):
    img = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
    if img is None:
        return data
    ok, buf = cv2.imencode(".jpg", brand_image(img, caption), [cv2.IMWRITE_JPEG_QUALITY, quality])
    return buf.tobytes() if ok else data


def jpg_without_exif(data):
    """The JPEG without its EXIF blocks (APP1) - that is where the GPS position is; the picture itself stays untouched."""
    if data[:2] != b"\xff\xd8":
        return data
    out, i, n = [data[:2]], 2, len(data)
    while i + 4 <= n and data[i] == 0xFF:
        mk = data[i + 1]
        if mk in (0xD9, 0xDA):                                # end / start of the picture data: the rest as it is
            break
        ln = int.from_bytes(data[i + 2:i + 4], "big")
        if ln < 2 or i + 2 + ln > n:
            return data
        if not (mk == 0xE1 and data[i + 4:i + 10] in (b"Exif\0\0", b"Exif\0\xff")):
            out.append(data[i:i + 2 + ln])
        i += 2 + ln
    out.append(data[i:])
    return b"".join(out)


def share_jpg(data, caption=""):
    """A picture as it leaves the Pi when shared: logo (if on), location only when wanted."""
    g = exif_gps_bytes(data) if CFG["share_gps"] else None
    data = brand_jpg(data, caption) if CFG["share_logo"] else data
    data = jpg_without_exif(data)
    if g:
        data = data[:2] + exif_gps(g[0], g[1]) + data[2:]
    return data


def exif_gps_bytes(data):
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(suffix=".jpg")
        with os.fdopen(fd, "wb") as f:
            f.write(data[:65536])
        return exif_read_gps(tmp)
    except OSError:
        return None
    finally:
        if tmp:
            try:
                os.remove(tmp)
            except OSError:
                pass


def share_video(src, caption=""):
    """A video as it leaves the Pi when shared: logo (if on); the location removed unless wanted. (path, error)"""
    if CFG["share_logo"]:
        return brand_video(src, caption)
    if CFG["share_gps"] or not shutil.which("ffmpeg"):
        return src, ""                                        # without ffmpeg no location was written into it either
    cache = os.path.join(rec_dir(), ".cache"); os.makedirs(cache, exist_ok=True)
    dst = os.path.join(cache, os.path.splitext(os.path.basename(src))[0] + ".nogps.mp4")
    try:
        if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
            return dst, ""
        r = subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", src, "-map", "0", "-c", "copy", "-map_metadata", "-1",
                            "-movflags", "+faststart", dst + ".part.mp4"], capture_output=True, timeout=600)
        if r.returncode != 0:
            return None, (r.stderr.decode(errors="replace").strip().splitlines() or ["ffmpeg failed"])[-1][:200]
        os.replace(dst + ".part.mp4", dst)
        return dst, ""
    except (OSError, subprocess.SubprocessError) as e:
        return None, str(e)[:200]
    finally:
        try:
            os.remove(dst + ".part.mp4")
        except OSError:
            pass


def brand_video(src, caption=""):
    """Copy of a video with the logo strip (ffmpeg overlay), kept in the cache folder. Returns (path, error)."""
    if not shutil.which("ffmpeg"):
        return None, "ffmpeg is missing (sudo apt install ffmpeg)"
    cache = os.path.join(rec_dir(), ".cache"); os.makedirs(cache, exist_ok=True)
    dst = os.path.join(cache, os.path.splitext(os.path.basename(src))[0] + (".share.gps.mp4" if CFG["share_gps"] else ".share.mp4"))
    try:
        if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
            return dst, ""
    except OSError:
        pass
    cap = cv2.VideoCapture(src); w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 1280); cap.release()
    strip = brand_strip(w, caption)
    if strip is None:
        CFG_logo = CFG["share_logo"]; CFG["share_logo"] = False
        try:
            return share_video(src, caption)
        finally:
            CFG["share_logo"] = CFG_logo
    png = dst + ".logo.png"; strip.save(png)
    m = max(6, w // 80)
    cmd = ["ffmpeg", "-y", "-loglevel", "error", "-i", src, "-i", png, "-filter_complex", f"overlay=W-w-{m}:H-h-{m}",
           "-c:v", "libx264", "-preset", "veryfast", "-crf", "24", "-pix_fmt", "yuv420p", "-c:a", "copy"]
    cmd += [] if CFG["share_gps"] else ["-map_metadata", "-1"]
    cmd += ["-movflags", "+faststart", dst + ".part.mp4"]
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=600)
        if r.returncode != 0:
            return None, (r.stderr.decode(errors="replace").strip().splitlines() or ["ffmpeg failed"])[-1][:200]
        os.replace(dst + ".part.mp4", dst)
        return dst, ""
    except (OSError, subprocess.SubprocessError) as e:
        return None, str(e)[:200]
    finally:
        for f in (png, dst + ".part.mp4"):
            try:
                os.remove(f)
            except OSError:
                pass

# ----------------------------------------------------------------------------
# Targeted deterrence: what is seen decides the reaction - person, small animal (cat, dog, bird), big animal (bear, cow,
#   horse ...) or a warm body (thermal camera): own sound on the loudspeaker and / or the white light flashing.
#   Only when armed (or always, e.g. to keep animals out of the garden), with a pause between two reactions.
# ----------------------------------------------------------------------------
DETER_GROUPS = (("person", {"person"}), ("big", {"bear", "horse", "cow", "sheep", "elephant", "zebra", "giraffe"}),
                ("small", {"cat", "dog", "bird"}), ("warm", {"warm"}))
DETER_ACTS = ("off", "sound", "light", "both")


class Deterrence:
    def __init__(self):
        self.seen = {}; self.last = 0.0; self.last_group = ""

    def check(self, present, t0):
        if not (is_armed() or CFG["deter_always"]):
            self.seen.clear(); return
        hit = None
        for g, labels in DETER_GROUPS:                    # the first group that matches wins (person before animals)
            if present & labels and CFG[f"deter_{g}_act"] != "off":
                hit = g; break
        if hit is None:
            return
        first = self.seen.get(hit)
        if first is None or t0 - first > 4.0:
            self.seen[hit] = t0; return                   # must still be there a moment later (no reaction to one wrong picture)
        if t0 - first < 1.0 or t0 - self.last < float(CFG["deter_pause"]):
            return
        self.react(hit, sorted(present & dict(DETER_GROUPS)[hit])[0] if present & dict(DETER_GROUPS)[hit] else hit)
        self.last = t0; self.seen.pop(hit, None)

    def react(self, group, label):
        act = CFG[f"deter_{group}_act"]; secs = float(CFG["deter_seconds"]); done = []
        if act in ("sound", "both") and out_selected() and not SOUND["playing"] and TALK["proc"] is None:
            ok, _e = sound_play(CFG[f"deter_{group}_sound"], secs, None, reason="deterrence " + label)
            if ok:
                done.append("sound")
        if act in ("light", "both") and CFG["light_white_out"]:
            LIGHTS["strobe_until"] = time.time() + secs; done.append("light")
        log_event("alarm" if group != "small" else "sys", f"Deterrence: {label} -> {' + '.join(done) or 'nothing (no loudspeaker / light connected)'}")
        STATE["deter_last"] = datetime.now().strftime("%H:%M") + " " + tr(label) + " → " + (" + ".join(tr(x) for x in done) or "–")


DETER = Deterrence()

# ---- talking from the phone through the loudspeaker (push to talk) ------------------------------
#   The page records the phone microphone (only allowed on a secure https page), sends 16 kHz / 16 bit pieces every 0.2 s,
#   they are played with aplay. 1.5 s without a piece ends it. While somebody talks, the noise alarm does not listen.
TALK = {"proc": None, "last": 0.0, "who": "", "dev": ""}
_TALK_LOCK = threading.Lock()


def talk_chunk(data, who=""):
    dev = CFG["audio_out"]
    if not out_selected():
        return False, "no loudspeaker selected"
    if not dev.startswith("bt:") and not shutil.which("aplay"):
        return False, "aplay is missing (sudo apt install alsa-utils)"
    if not data or len(data) > 96000:
        return False, "invalid sound data"
    a = np.frombuffer(data[:len(data) // 2 * 2], dtype="<i2").astype(np.float32) * (10.0 ** (float(CFG["talk_gain"]) / 20.0))
    pcm = np.clip(a, -32768, 32767).astype("<i2").tobytes()
    now = time.time()
    with _TALK_LOCK:
        p = TALK["proc"]
        if p is None or p.poll() is not None or TALK["dev"] != dev:
            if SOUND["playing"]:
                sound_stop()                             # the voice wins over a siren that is still playing
            cmd, err = out_cmd(AUDIO_RATE, connect=False)
            if cmd is None:
                return False, err
            try:
                p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except OSError as e:
                return False, str(e)[:200]
            TALK.update(proc=p, who=who, dev=dev, last=now)
            try:
                p.stdin.write(bytes(int(AUDIO_RATE * 0.15) * 2))     # a little head start: small network gaps do not stutter
            except (BrokenPipeError, OSError):
                pass
            log_event("sys", f"Talking through the loudspeaker ({who or '?'})")
            threading.Thread(target=_talk_watch, args=(p,), daemon=True).start()
        try:
            p.stdin.write(pcm); p.stdin.flush()
        except (BrokenPipeError, OSError):
            TALK["proc"] = None
            return False, "the loudspeaker could not be opened"
        TALK["last"] = now
    if AUDIO is not None:
        AUDIO.mute_until = now + 2.5
    return True, ""


def _talk_watch(p):
    while TALK["proc"] is p:
        if time.time() - TALK["last"] > 1.5:
            talk_stop(); break
        time.sleep(0.25)


def talk_stop():
    with _TALK_LOCK:
        p = TALK["proc"]; TALK["proc"] = None
    if p is None:
        return
    try:
        p.stdin.close()                                  # aplay plays what is left, then ends by itself
    except Exception:
        pass
    def reap():
        try:
            p.wait(timeout=10)
        except Exception:
            p.kill()
    threading.Thread(target=reap, daemon=True).start()
    if AUDIO is not None:
        AUDIO.mute_until = time.time() + 2.0


# ----------------------------------------------------------------------------
# Updates: choose a version and switch to it. Source = the URL of a versions.json (e.g. in a GitHub repository) or a folder
#   (e.g. a USB stick). Downloaded versions are kept next to this file, so you can always go back (also without internet).
#   versions.json: {"versions": [{"version": "1.8.7", "file": "webcam_bewegung_2_95_70.py", "url": "https://...", "sha256": "...",
#   "date": "2026-10-22", "notes": "..."}]}  - made with:  python3 webcam_bewegung_X.py --make-manifest <folder> --base-url <url>
# ----------------------------------------------------------------------------
UPD = {"items": [], "msg": "", "busy": False, "time": 0.0, "list_time": ""}
UPD_PROG = {"phase": "", "got": 0, "size": 0, "t0": 0.0, "tp": 0.0}   # progress of an update for the bar on the page (2.95.30)
_RESTART_M = {"todo": True}


def _restart_file():
    return os.path.join(DATA_DIR, "restart_time.json")


def restart_est():
    """how long the last restarts took (from «update» to the first answer of the new program), in seconds"""
    try:
        with open(_restart_file()) as f:
            return max(5.0, min(300.0, float(json.load(f).get("avg") or 25)))
    except (OSError, ValueError, TypeError, AttributeError):
        return 25.0


def restart_measure():
    """called by the first request of a new program: how long did the restart take?"""
    _RESTART_M["todo"] = False
    try:
        with open(_restart_file()) as f:
            d = json.load(f)
        t0 = float(d.get("pending") or 0)
        if not t0:
            return
        dur = time.time() - t0
        d.pop("pending", None)
        if 3 < dur < 300:
            d["avg"] = round(dur if not d.get("avg") else 0.5 * float(d["avg"]) + 0.5 * dur, 1); d["last"] = round(dur, 1)
        with open(_restart_file(), "w") as f:
            json.dump(d, f)
    except (OSError, ValueError, TypeError, AttributeError):
        pass


def _restart_mark():
    try:
        try:
            with open(_restart_file()) as f:
                d = json.load(f)
        except (OSError, ValueError):
            d = {}
        d["pending"] = time.time()
        with open(_restart_file(), "w") as f:
            json.dump(d, f)
    except (OSError, TypeError, AttributeError):
        pass
# Signed updates: every version in versions.json carries a signature made with the developer's secret key (kept offline).
# The program only installs versions whose signature fits this public key - so nobody who gets into the GitHub account can
# push a program onto the devices. (Setting «Also accept unsigned versions» switches the check off, e.g. for own builds.)
UPDATE_PUBKEY = "91d5eab3ab9f6e092d78081ca511144235cb9b22b770c3b1047e011d978bd416"

def _ed25519_impl():
    """Ed25519 (RFC 8032, reference algorithm) in pure Python - no extra package needed. Only used for update signatures."""
    p = 2 ** 255 - 19
    q = 2 ** 252 + 27742317777372353535851937790883648493
    d = -121665 * pow(121666, p - 2, p) % p
    I = pow(2, (p - 1) // 4, p)
    H = lambda m: hashlib.sha512(m).digest()

    def add(P, Q):
        A = (P[1] - P[0]) * (Q[1] - Q[0]) % p; B = (P[1] + P[0]) * (Q[1] + Q[0]) % p
        C = 2 * P[3] * Q[3] * d % p; D = 2 * P[2] * Q[2] % p
        E, F, G, Hh = B - A, D - C, D + C, B + A
        return (E * F % p, G * Hh % p, F * G % p, E * Hh % p)

    def mul(s, P):
        Q = (0, 1, 1, 0)
        while s > 0:
            if s & 1:
                Q = add(Q, P)
            P = add(P, P); s >>= 1
        return Q

    def eq(P, Q):
        return (P[0] * Q[2] - Q[0] * P[2]) % p == 0 and (P[1] * Q[2] - Q[1] * P[2]) % p == 0

    def recover_x(y, sign):
        if y >= p:
            return None
        x2 = (y * y - 1) * pow(d * y * y + 1, p - 2, p)
        if x2 == 0:
            return None if sign else 0
        x = pow(x2, (p + 3) // 8, p)
        if (x * x - x2) % p != 0:
            x = x * I % p
        if (x * x - x2) % p != 0:
            return None
        if (x & 1) != sign:
            x = p - x
        return x

    gy = 4 * pow(5, p - 2, p) % p
    gx = recover_x(gy, 0)
    G = (gx, gy, 1, gx * gy % p)

    def compress(P):
        zi = pow(P[2], p - 2, p); x = P[0] * zi % p; y = P[1] * zi % p
        return int.to_bytes(y | ((x & 1) << 255), 32, "little")

    def decompress(s):
        if len(s) != 32:
            return None
        y = int.from_bytes(s, "little"); sign = y >> 255; y &= (1 << 255) - 1
        x = recover_x(y, sign)
        return None if x is None else (x, y, 1, x * y % p)

    def expand(seed):
        h = H(seed); a = int.from_bytes(h[:32], "little")
        a &= (1 << 254) - 8; a |= 1 << 254
        return a, h[32:]

    def public(seed):
        return compress(mul(expand(seed)[0], G))

    def sign(seed, msg):
        a, prefix = expand(seed); A = compress(mul(a, G))
        r = int.from_bytes(H(prefix + msg), "little") % q
        R = compress(mul(r, G))
        h = int.from_bytes(H(R + A + msg), "little") % q
        return R + int.to_bytes((r + h * a) % q, 32, "little")

    def verify(pub, msg, sig):
        if len(pub) != 32 or len(sig) != 64:
            return False
        A = decompress(pub); R = decompress(sig[:32])
        if A is None or R is None:
            return False
        s = int.from_bytes(sig[32:], "little")
        if s >= q:
            return False
        h = int.from_bytes(H(sig[:32] + pub + msg), "little") % q
        return eq(mul(s, G), add(R, mul(h, A)))
    return public, sign, verify


_ED = []


def _sig_msg(version, fname, sha):
    return ("MotionWatch|" + str(version) + "|" + str(fname) + "|" + str(sha).lower()).encode()


def sig_ok(version, fname, sha, sig, pub=None):
    """True when `sig` (hex) is a valid signature of this version / file / checksum."""
    try:
        if not _ED:
            _ED.extend(_ed25519_impl())
        return bool(sha) and _ED[2](bytes.fromhex(pub or UPDATE_PUBKEY), _sig_msg(version, fname, sha), bytes.fromhex(str(sig or "")))
    except (ValueError, TypeError):
        return False


def _installable(it):
    """May this list entry be installed? (already on the Pi, or signed, or unsigned ones are allowed)"""
    return bool(it.get("installed") or it.get("signed") or CFG["update_unsigned"])

VFILE_RE = re.compile(r"^webcam_bewegung_(\d{1,3})_(\d{1,3})_(\d{1,3})\.py$")
VER_RE = re.compile(r"^\d{1,3}\.\d{1,3}\.\d{1,3}$")


def _vkey(v):
    try:
        return tuple(int(x) for x in str(v).split("."))
    except ValueError:
        return (0,)


def file_version(text):
    """Version of a program file: APP_VERSION (from 1.8.5), else the window title (older versions)."""
    m = (re.search(r'^APP_VERSION = "(\d+\.\d+\.\d+)"', text, re.M)
         or re.search(r'root\.title\("Motion Watch (\d+\.\d+\.\d+)"\)', text))
    return m.group(1) if m else ""


def file_notes(text, ver):
    m = re.search(r"^  \* " + re.escape(ver) + r": (.*?)(?=^  \* \d|^\S|\n\s*\n)", text, re.M | re.S)
    return " ".join(m.group(1).split())[:600] if m else ""


def local_versions(folder):
    out = []
    try:
        names = os.listdir(folder)
    except OSError:
        return out
    for n in names:
        m = VFILE_RE.match(n)
        if not m:
            continue
        p = os.path.join(folder, n)
        try:
            with open(p, encoding="utf-8", errors="replace") as f:
                head = f.read(400000)
            st = os.stat(p)
        except OSError:
            continue
        v = file_version(head) or ".".join(m.groups())
        out.append({"version": v, "file": n, "path": p, "date": datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M"),
                    "notes": file_notes(head, v), "size": st.st_size})
    return out


def _upd_source_ok(src):
    return src == "" or re.match(r"^https://[^\s]{4,400}$", src) is not None or (src.startswith("/") and len(src) < 300)


# ----------------------------------------------------------------------------
# Event log on the SD card: motionwatch.log is written at once (every line). Each day gets its own file in the archive
# logs/motionwatch_YYYY-MM-DD.log.gz (packed), kept for log_keep_days. A status line every log_status_min minutes.
# ----------------------------------------------------------------------------
LOG_NAME_RE = re.compile(r"^motionwatch_\d{4}-\d{2}-\d{2}(_\d+)?\.log(\.gz)?$")
LOG_LINE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})  \[([a-z]+)\]  (.*)$")
LOG_MAX_MB = 20


def log_dir():
    return os.path.join(DATA_DIR, "logs")


def log_rotate(force=False):
    """Move yesterday's (or a too big) motionwatch.log into the archive and pack it."""
    import gzip
    try:
        st = os.stat(LOG_FILE)
    except OSError:
        return False
    day = datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d")
    big = st.st_size > LOG_MAX_MB * 1024 * 1024
    if not (force or big or day != datetime.now().strftime("%Y-%m-%d")):
        return False
    os.makedirs(log_dir(), exist_ok=True)
    base = os.path.join(log_dir(), f"motionwatch_{day}")
    name, i = base + ".log.gz", 1
    while os.path.exists(name):
        i += 1; name = f"{base}_{i}.log.gz"
    tmp = LOG_FILE + ".rotating"
    try:
        os.replace(LOG_FILE, tmp)                         # new lines go into a fresh motionwatch.log from now on
        with open(tmp, "rb") as src, gzip.open(name + ".part", "wb", compresslevel=6) as dst:
            shutil.copyfileobj(src, dst)
        os.replace(name + ".part", name)
        os.remove(tmp)
    except OSError as e:
        print(f"Log rotation failed: {e}")
        return False
    return True


def log_purge():
    keep = max(1, int(CFG["log_keep_days"]))
    limit = (datetime.now() - timedelta(days=keep)).strftime("%Y-%m-%d")
    n = 0
    try:
        for f in os.listdir(log_dir()):
            if LOG_NAME_RE.match(f) and f[12:22] < limit:
                os.remove(os.path.join(log_dir(), f)); n += 1
    except OSError:
        pass
    return n


def log_archive():
    out = []
    try:
        for f in sorted(os.listdir(log_dir()), reverse=True):
            if LOG_NAME_RE.match(f):
                out.append({"name": f, "day": f[12:22], "size": os.path.getsize(os.path.join(log_dir(), f))})
    except OSError:
        pass
    cur = os.path.getsize(LOG_FILE) if os.path.isfile(LOG_FILE) else 0
    return {"current": {"name": "motionwatch.log", "size": cur}, "files": out, "keep_days": int(CFG["log_keep_days"])}


def log_lines(name="", limit=300, kind="", q=""):
    """The newest lines of today's log (or of an archive day), newest first, filtered by kind / words."""
    import gzip
    path = LOG_FILE if not name or name == "motionwatch.log" else (os.path.join(log_dir(), name) if LOG_NAME_RE.match(name) else "")
    if not path or not os.path.isfile(path):
        return []
    try:
        if path.endswith(".gz"):
            with gzip.open(path, "rt", encoding="utf-8", errors="replace") as f:
                lines = f.read().splitlines()
        else:
            with open(path, "rb") as f:                   # only the end of a big file
                f.seek(0, 2); size = f.tell(); f.seek(max(0, size - 4 * 1024 * 1024))
                lines = f.read().decode("utf-8", "replace").splitlines()
    except OSError:
        return []
    words = [w for w in (q or "").lower().split() if w]
    out = []
    for ln in reversed(lines):
        m = LOG_LINE_RE.match(ln)
        if not m:
            continue
        if kind == "important":
            if not log_important(m.group(3), m.group(4)):
                continue
        elif kind and m.group(3) != kind:
            continue
        if words and not all(w in ln.lower() for w in words):
            continue
        out.append({"d": m.group(1), "t": m.group(2), "kind": m.group(3), "text": m.group(4)})
        if len(out) >= limit:
            break
    return out


def status_line():
    st = STATE; parts = []
    parts.append({"armed": "armed", "arming": "arming"}.get(st.get("arm_state"), "disarmed"))
    if st.get("cpu") is not None:
        parts.append(f"CPU {st['cpu']:.0f}%" + (f" {st['cpu_temp']:.0f}°C" if st.get("cpu_temp") is not None else ""))
    parts.append(f"{st.get('fps', 0):.0f} FPS · camera {st.get('source_status', '?')}")
    wf = st.get("wifi") or {}
    if wf.get("connected"):
        parts.append(f"Wi-Fi {wf.get('dbm')} dBm")
    net = st.get("net") or {}
    if net.get("online") is not None:
        parts.append("internet ok" if net["online"] else "no internet")
    dk = st.get("disk") or {}
    if dk.get("free_mb") is not None:
        parts.append(f"{dk['free_mb']} MB free")
    sup = st.get("supply") or {}
    if sup.get("volt"):
        parts.append(f"{sup['volt']:.2f} V" + (" UNDER-VOLTAGE" if sup.get("uv_now") else ""))
    bt = st.get("battery") or {}
    if bt.get("pct") is not None:
        parts.append(f"battery {bt['pct']} %")
    if st.get("remote"):
        parts.append("remote: " + ", ".join(st["remote"]))
    parts.append(f"persons today {st.get('detections_total', 0)}")
    return "Status: " + " · ".join(parts)


def preload_events():
    """After a (re)start the overview would be empty: take the last entries of today's log (and of the newest archive day)."""
    lines = log_lines("", 300)                           # today's file already holds the lines of this start too
    if sum(1 for x in lines if log_important(x["kind"], x["text"])) < 10:
        arch = log_archive()["files"]
        if arch:
            lines += log_lines(arch[0]["name"], 300)
    old = [{"t": x["t"], "d": x["d"], "kind": x["kind"], "text": x["text"], "imp": log_important(x["kind"], x["text"])} for x in lines]
    if old:
        with LOCK:
            STATE["events"][:] = old[:300]


class LogKeeper:
    """Every minute: new day -> archive yesterday's log; delete old archive files; status line every N minutes."""
    def __init__(self):
        self._st = time.time(); self._purge_t = 0.0
        try:
            log_rotate()                                  # a log from an earlier day (e.g. after the Pi was off)
            preload_events()
        except Exception:
            pass
        threading.Thread(target=self.loop, daemon=True).start()

    def loop(self):
        while True:
            time.sleep(60)
            try:
                if log_rotate():
                    log_event("sys", "New day: yesterday's event log was moved into the archive")
                if time.time() - self._purge_t > 3600:
                    self._purge_t = time.time()
                    n = log_purge()
                    if n:
                        log_event("sys", f"Event log archive: {n} old day(s) deleted")
                every = int(CFG["log_status_min"])
                if every > 0 and time.time() - self._st >= every * 60:
                    self._st = time.time()
                    log_event("status", status_line())
            except Exception as e:
                print(f"Log keeper: {e}")


# ----------------------------------------------------------------------------
# Operator mode ("lock"): the person using the device can switch the main functions on and off, but cannot change
# any settings. Unlocking needs the PIN (4-8 digits, stored as PBKDF2 hash). Enforced by the web server and the window.
# ----------------------------------------------------------------------------
OPER_KEYS = {"detection_on", "record", "notify_on", "browser_alarm", "timelapse_on", "eco_on", "patrol", "track_person",
             "relays_on", "noise_alarm", "thermal_on", "thermal_alarm", "report_on", "show_objects", "nightvision"}
LOCK_FAILS = []


def _pin_hash(pin, salt=None):
    import hashlib
    salt = salt or secrets.token_hex(8)
    return salt + "$" + hashlib.pbkdf2_hmac("sha256", pin.encode(), salt.encode(), 120000).hex()


def lock_pin_ok(pin):
    h = CFG["lock_pin"]
    if not h or "$" not in h or not isinstance(pin, str):
        return False
    return hmac.compare_digest(_pin_hash(pin, h.split("$", 1)[0]), h)


# not put back when unlocking: what the operator does (arm, move the camera), what the Pi measures itself, how a
# device shows the page
LOCK_KEEP = {"armed", "pan", "tilt", "hotspot_on", "lock_on", "lock_pin", "lock_snap", "web_ui", "ui_open", "ui_tab", "theme", "lang",
             "fullscreen", "latitude", "longitude", "batt_full_t", "batt_warned", "setup_done", "autostart", "ui_simple"}
LOCK_LAST = {"restored": []}


def lock_snapshot():
    d = json.loads(json.dumps(settings_data()))
    d["cfg"] = {k: v for k, v in d["cfg"].items() if k not in LOCK_KEEP}
    d["v"] = 2
    return d


def lock_restore():
    """Unlocking: everything changed since the lock goes back to the copy (settings, zones, schedules, waypoints, relays)."""
    snap = CFG.get("lock_snap") if isinstance(CFG.get("lock_snap"), dict) else {}
    CFG["lock_snap"] = {}
    if not snap:
        return []
    if snap.get("v") != 2:                                           # copy made by 2.44.0: settings only
        snap = {"cfg": {k: v for k, v in snap.items() if not k.startswith("_")}}
    now = json.loads(json.dumps(settings_data()))
    back = [k for k, v in snap.get("cfg", {}).items() if k in CFG and k not in LOCK_KEEP and k not in VOLATILE and now["cfg"].get(k) != v]
    for part in ("waypoints", "relays", "schedules", "zones"):
        if part in snap and snap[part] != now.get(part):
            back.append(part)
    if not back:
        return []
    data = {"cfg": {k: v for k, v in snap.get("cfg", {}).items() if k not in LOCK_KEEP and k not in VOLATILE}}
    for part in ("waypoints", "relays", "schedules", "zones"):
        data[part] = snap.get(part, now.get(part))
    keep = {k: CFG[k] for k in LOCK_KEEP if k in CFG}
    apply_settings(data)
    CFG.update(keep)
    for k in back:
        if k in CFG:
            try:
                sched_user_changed(k)
            except Exception:
                pass
    HW_REINIT["want"] = True; SETTINGS_GEN["n"] += 1                 # servos / lights / window follow the old values
    return back


def lock_info():
    snap = CFG.get("lock_snap") if isinstance(CFG.get("lock_snap"), dict) else {}
    since = str(snap.get("saved") or "")[11:16] if CFG["lock_on"] else ""
    return {"on": bool(CFG["lock_on"]), "pin_set": bool(CFG["lock_pin"]), "restored": len(LOCK_LAST["restored"]), "since": since}


def lock_set(action, pin="", new_pin="", source="web"):
    """lock (optionally with a new PIN) / unlock (PIN) / pin (change the PIN while unlocked)."""
    pin, new_pin = str(pin or "").strip(), str(new_pin or "").strip()
    if new_pin and not re.fullmatch(r"\d{4,8}", new_pin):
        return False, "the PIN must have 4 to 8 digits"
    if action in ("lock", "pin"):
        if CFG["lock_on"]:
            return False, "locked - settings can only be changed after unlocking (PIN)"
        if new_pin:
            CFG["lock_pin"] = _pin_hash(new_pin)
        if action == "pin":
            save_settings(); log_event("sys", f"Operator mode: PIN changed ({source})")
            return True, ""
        if not CFG["lock_pin"]:
            return False, "set a PIN first"
        CFG["lock_snap"] = lock_snapshot(); CFG["lock_on"] = True; save_settings()
        log_event("sys", f"Operator mode ON - settings locked, a copy of all {len(CFG['lock_snap'])} settings kept ({source})")
        return True, ""
    if action == "unlock":
        now = time.time()
        LOCK_FAILS[:] = [t for t in LOCK_FAILS if now - t < 300]
        if len(LOCK_FAILS) >= 5:
            return False, "too many wrong PINs - try again in 5 minutes"
        if not lock_pin_ok(pin):
            LOCK_FAILS.append(now)
            log_event("sys", f"Operator mode: wrong PIN ({source})")
            return False, "wrong PIN"
        LOCK_FAILS.clear()
        back = lock_restore(); LOCK_LAST["restored"] = back
        CFG["lock_on"] = False; save_settings()
        log_event("sys", f"Operator mode OFF - settings unlocked ({source})"
                         + (f", {len(back)} change(s) put back: " + ", ".join(back[:12]) + (" …" if len(back) > 12 else "") if back else ", nothing was changed"))
        return True, ""
    return False, "unknown action"


# operator mode: everything may be changed and is put back at unlocking - except what could lock the owner out
LOCK_DENY_PATHS = {"/api/wifi", "/api/hotspot", "/api/password", "/api/settings/import", "/api/autostart", "/api/setup", "/api/ext",
                   "/api/users", "/api/trusted", "/api/shortcut"}     # 2.95.34: users, trusted devices, shortcut keys too
LOCK_DENY_KEYS = {"net_mode", "hotspot_ssid", "hotspot_password", "hotspot_on", "update_url", "update_token", "update_unsigned",
                  "lock_on", "lock_pin", "autostart", "web_port"}


def lock_allows(path, method, data):
    """Web requests in operator mode: all but the ones that could lock the owner out."""
    if not CFG["lock_on"]:
        return True
    if method != "POST":
        return path != "/api/settings/export"            # the settings file contains passwords
    if path in LOCK_DENY_PATHS:
        return False
    d = data or {}
    if path in ("/api/set", "/api/text") and d.get("key") in LOCK_DENY_KEYS:
        return False
    if path == "/api/action" and d.get("action") == "reset_settings":
        return False
    return True


_GH_HOSTS = ("raw.githubusercontent.com", "api.github.com", "github.com", "objects.githubusercontent.com")


class _SafeRedirect(urllib.request.HTTPRedirectHandler):
    """urllib copies the Authorization header to the new address of a redirect - only keep it on the same host
    (or GitHub to GitHub). 2.95.33"""
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        new = super().redirect_request(req, fp, code, msg, headers, newurl)
        if new is not None:
            try:
                from urllib.parse import urlparse
                h0, h1 = (urlparse(req.full_url).hostname or "").lower(), (urlparse(new.full_url).hostname or "").lower()
            except ValueError:
                h0, h1 = "", "?"
            if h0 != h1 and not (h0 in _GH_HOSTS and h1 in _GH_HOSTS):
                for k in list(new.headers):
                    if k.lower() == "authorization":
                        del new.headers[k]
                new.unredirected_hdrs.pop("Authorization", None)
        return new


try:
    urllib.request.install_opener(urllib.request.build_opener(_SafeRedirect))
except Exception:
    pass


def _upd_request(url, extra=None):
    """Request for the update source. The GitHub key is added only for GitHub addresses (never sent anywhere else)."""
    h = {"User-Agent": "MotionWatch/" + APP_VERSION}
    h.update(extra or {})
    try:
        from urllib.parse import urlparse
        host = (urlparse(url).hostname or "").lower()
    except ValueError:
        host = ""
    tok = CFG["update_token"].strip()
    if tok and host in _GH_HOSTS:
        h["Authorization"] = "token " + tok
    return urllib.request.Request(url, headers=h)


def _upd_error(e):
    """Readable reason why the update source did not answer (the key never appears in it)."""
    import urllib.error
    code = getattr(e, "code", None)
    if code in (401, 403, 404) and "github" in CFG["update_url"]:
        if not CFG["update_token"].strip():
            return "not found - is the repository private? Then enter the GitHub key (token)"
        return "GitHub refused the key - check that it is valid and may read this repository"
    msg = str(e)
    tok = CFG["update_token"].strip()
    return msg.replace(tok, "***") if tok else msg


def update_check():
    """List what can be chosen: versions next to this program (installed) + versions at the update source."""
    src = CFG["update_url"].strip()
    items = {}
    for it in local_versions(HERE):
        items[it["version"]] = dict(it, installed=True, available=False, url="")
    msg = ""
    if src.startswith("https://"):
        try:
            # GitHub's file server keeps a copy for up to 5 minutes - a changing ?t= asks for the newest list
            req = _upd_request(src + ("&" if "?" in src else "?") + "t=" + str(int(time.time())), {"Cache-Control": "no-cache"})
            with urllib.request.urlopen(req, timeout=15) as r:
                data = json.loads(r.read(1024 * 1024 + 1)[:1024 * 1024].decode("utf-8"))
            UPD["list_time"] = str(data.get("generated") or "")[:16]
            base = src.rsplit("/", 1)[0] + "/"
            for e in (data.get("versions") or [])[:200]:
                v, fn = str(e.get("version", "")), str(e.get("file", ""))
                url = str(e.get("url") or (base + fn))
                if not (VER_RE.match(v) and VFILE_RE.match(fn) and url.startswith("https://")):
                    continue
                it = items.setdefault(v, {"version": v, "file": fn, "installed": False, "path": ""})
                sha = str(e.get("sha256", ""))[:64].lower()
                it.update(available=True, url=url, sha256=sha, signed=sig_ok(v, fn, sha, e.get("sig")),
                          date=str(e.get("date", it.get("date", "")))[:16], notes=str(e.get("notes", it.get("notes", "")))[:600])
        except Exception as e:
            msg = f"update source not reachable: {_upd_error(e)}"[:240]
    elif src.startswith("/"):
        found = local_versions(src)
        if not found and not os.path.isdir(src):
            msg = "folder not found"
        sigs = {}
        try:                                             # signatures of a folder (USB stick) come from its versions.json
            with open(os.path.join(src, "versions.json"), encoding="utf-8") as f:
                sigs = {str(e.get("file")): str(e.get("sig") or "") for e in (json.load(f).get("versions") or [])[:500]}
        except (OSError, ValueError, AttributeError):
            pass
        for it in found:
            cur = items.setdefault(it["version"], dict(it, installed=False, path=""))
            sha = ""
            if sigs.get(it["file"]):
                try:
                    with open(it["path"], "rb") as f:
                        sha = hashlib.sha256(f.read(8 * 1024 * 1024 + 1)).hexdigest()
                except OSError:
                    pass
            cur.update(available=True, src_path=it["path"], url="", sha256=sha, signed=sig_ok(it["version"], it["file"], sha, sigs.get(it["file"])))
            cur.setdefault("notes", it["notes"])
    for v, it in items.items():
        it["current"] = v == APP_VERSION
        it.setdefault("signed", False)
    UPD["items"] = sorted(items.values(), key=lambda x: _vkey(x["version"]), reverse=True)
    newer = [x for x in UPD["items"] if x.get("available") and _installable(x) and _vkey(x["version"]) > _vkey(APP_VERSION)]
    STATE["update_new"] = ({"version": newer[0]["version"], "notes": newer[0].get("notes", "")[:300], "date": newer[0].get("date", "")}
                           if newer else {})
    UPD["msg"] = msg; UPD["time"] = time.time()
    return UPD["items"], msg


def _verify_program(data, want_version, sha=""):
    import hashlib
    if len(data) > 8 * 1024 * 1024 or len(data) < 10000:
        return "the file does not look like Motion Watch"
    if sha and hashlib.sha256(data).hexdigest() != sha:
        return "the file is damaged (checksum does not match) - try again"
    try:
        text = data.decode("utf-8")
        compile(text, "update.py", "exec")
    except Exception:
        return "the file is not a working Python program"
    if "class MotionWatch" not in text or file_version(text) != want_version:
        return "the file does not look like Motion Watch"
    return ""


def update_install(version):
    """Fetch (if needed), check and start the chosen version. The program restarts itself (settings stay)."""
    if UPD["busy"]:
        return False, "an update is already running"
    if not UPD["items"] or time.time() - UPD["time"] > 600:
        update_check()
    it = next((x for x in UPD["items"] if x["version"] == version), None)
    if it is None:
        return False, "unknown version"
    if it.get("current"):
        return False, "this version is already running"
    if not _installable(it):
        return False, "this version is not signed by the developer - not installed (only with the setting «Also accept unsigned versions»)"
    UPD["busy"] = True
    UPD_PROG.update(phase="download", got=0, size=int(it.get("size") or 0), t0=time.time(), tp=time.time())
    try:
        dst = os.path.join(HERE, it["file"])
        if not it.get("installed"):
            if it.get("url"):
                req = _upd_request(it["url"])
                with urllib.request.urlopen(req, timeout=60) as r:
                    try:
                        UPD_PROG["size"] = int(r.headers.get("Content-Length") or 0) or UPD_PROG["size"]
                    except ValueError:
                        pass
                    parts, n = [], 0
                    while n <= 8 * 1024 * 1024:
                        b = r.read(min(65536, 8 * 1024 * 1024 + 1 - n))
                        if not b:
                            break
                        parts.append(b); n += len(b); UPD_PROG["got"] = n
                    data = b"".join(parts)
            elif it.get("src_path"):
                with open(it["src_path"], "rb") as f:
                    data = f.read(8 * 1024 * 1024 + 1)
            else:
                return False, "unknown version"
            UPD_PROG.update(phase="check", tp=time.time())
            err = _verify_program(data, version, it.get("sha256", ""))
            if err:
                return False, err
            tmp = dst + ".part"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, dst)
            log_event("sys", f"Version {version} downloaded: {it['file']}")
        else:
            UPD_PROG.update(phase="check", tp=time.time())
            with open(dst, "rb") as f:
                err = _verify_program(f.read(8 * 1024 * 1024 + 1), version)
            if err:
                return False, err
        UPD_PROG.update(phase="restart", tp=time.time())
        update_restart(dst, version)
        return True, ""
    except Exception as e:
        return False, f"update failed: {_upd_error(e)}"[:240]
    finally:
        UPD["busy"] = False
        if UPD_PROG["phase"] != "restart":
            UPD_PROG["phase"] = ""


RESTART = {"pending": ""}
PAUSING = {"on": False}


def _close_fds_on_exec():
    """The web server sockets are inheritable: they must not survive os.execv (the new program needs the port)."""
    try:
        if RUNGUARD.get("clean"):
            RUNGUARD["clean"]()                         # a planned restart (update, pause) is a clean end
    except Exception:
        pass
    try:
        for fd in os.listdir("/proc/self/fd"):
            if int(fd) > 2:
                try:
                    os.set_inheritable(int(fd), False)
                except OSError:
                    pass
    except OSError:
        pass


def _base_args():
    """Command line of this run without one-shot options and without --paused-until."""
    out, skip = [], False
    for x in sys.argv[1:]:
        if skip:
            skip = False; continue
        if x == "--paused-until":
            skip = True; continue
        if x.startswith("--paused-until=") or x in ("--print-service", "--install-service", "--allow-wifi"):
            continue
        out.append(x)
    return out


PAUSE_CHOICES = (5, 15, 30, 60, 120, 240, 480, 720)
TOOLMODE = {"until": 0.0, "by": "", "since": 0.0}         # tool mode: camera, detection and AI rest - the tools get the computer


def toolmode_on():
    return time.time() < TOOLMODE["until"]


def toolmode_set(minutes, source="web"):
    """minutes > 0: Motion Watch rests (no camera, no detection, no alarms) and comes back by itself after the time.
    0: back now. The web page and the tools keep running."""
    try:
        minutes = int(minutes)
    except (TypeError, ValueError):
        return False, "not a number"
    if minutes <= 0:
        if toolmode_on():
            TOOLMODE["until"] = 0.0
            log_event("sys", f"Tool mode ended by {source} - monitoring runs again")
        return True, ""
    if minutes > 720:
        return False, "not a number"
    was = toolmode_on()
    TOOLMODE.update(until=time.time() + minutes * 60, by=source, since=TOOLMODE["since"] if was else time.time())
    log_event("sys", f"Tool mode for {minutes} min by {source}: monitoring paused until {datetime.fromtimestamp(TOOLMODE['until']).strftime('%H:%M')}")
    return True, ""


def toolmode_state():
    on = toolmode_on()
    return {"on": on, "until": TOOLMODE["until"] if on else 0, "since": TOOLMODE["since"] if on else 0, "cpu": STATE.get("cpu"),
            "temp": STATE.get("cpu_temp"), "armed": bool(CFG["armed"])}


def pause_program(minutes, source="web"):
    """Switch the program off now (recording finished, settings saved) and start it again after <minutes>.
    The same process becomes a tiny waiting page (same PID: autostart and watchdog stay happy)."""
    try:
        minutes = int(minutes)
    except (TypeError, ValueError):
        return False, "not a number"
    if not 1 <= minutes <= 1440:
        return False, "not a number"
    if RESTART.get("pending"):
        return False, "a restart is already running"
    until = int(time.time() + minutes * 60)
    RESTART["pending"] = "pause"
    log_event("sys", f"Program paused for {minutes} min by {source} - starts again at {datetime.fromtimestamp(until).strftime('%H:%M')}")

    def work():
        time.sleep(1.5)                                   # the page gets its answer first
        try:
            w = WATCH_REF["w"]
            end = time.time() + 10.0
            while w is not None and w.writer is not None and time.time() < end:
                time.sleep(0.2)
            if AUDIO is not None:
                AUDIO.wait_mux(20.0)
            sound_stop(); talk_stop()
            PAUSING["on"] = True                          # relays and lights off before the program goes away
            time.sleep(0.6)
            if getattr(w, "sights", None) is not None:
                w.sights.tick(time.time(), force=True)    # the open visits go into the diary
            save_settings_now()
            _close_fds_on_exec()
            os.execv(sys.executable, [sys.executable, os.path.abspath(__file__)] + _base_args() + ["--paused-until", str(until)])
        except Exception as e:
            RESTART["pending"] = ""
            log_event("sys", f"Pause failed: {e}"[:200])
    threading.Thread(target=work, daemon=True, name="pause").start()
    return True, ""


PAUSE_PAGE = """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Motion Watch – __T_TITLE__</title><style>
body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#0b0f14;color:#e6edf3;
font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;text-align:center;padding:20px;box-sizing:border-box}
.c{max-width:420px}.big{font-size:56px}.t{font-size:22px;font-weight:700;margin:6px 0}.m{color:#8b9bb0}
#cd{font-size:40px;font-weight:700;margin:14px 0;font-variant-numeric:tabular-nums}
button{font:inherit;font-weight:700;padding:12px 22px;border-radius:12px;border:0;background:#2f81f7;color:#fff;cursor:pointer;margin-top:10px}
</style></head><body><div class="c"><div class="big">⏸</div><div class="t">__T_TITLE__</div>
<div class="m">__T_BACK__ <b>__UNTIL__</b></div><div id="cd">–</div>
<div class="m">__T_NOTE__</div>
<form method="post" action="/resume"><button>▶ __T_NOW__</button></form></div>
<script>const U=__UNTIL_TS__*1000;function f(){const s=Math.max(0,Math.round((U-Date.now())/1000));
document.getElementById("cd").textContent=Math.floor(s/3600)+":"+String(Math.floor(s%3600/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0");
if(s<=0){document.getElementById("cd").textContent="…";setTimeout(()=>location.replace("/"),4000);return;}setTimeout(f,1000);}f();</script>
</body></html>"""


def run_paused(until, argv_rest):
    """Waiting mode: no camera, no detection - only a small page on the web port. At <until> (or 'Start now')
    the full program comes back (same process, same options)."""
    import http.server
    de = CFG["lang"] == "de"
    T = {"title": tr("Program paused"), "back": tr("Starts again at"), "note": tr("While paused there is no monitoring and there are no alarms."),
         "now": tr("Start now")}
    state = {"go": False}

    def restart():
        print("Pause over - starting Motion Watch again")
        log_event("sys", "Pause over - starting again")
        _close_fds_on_exec()
        os.execv(sys.executable, [sys.executable, os.path.abspath(__file__)] + argv_rest)

    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def _send(self, code, body, ctype="text/html; charset=utf-8", extra=None):
            data = body.encode()
            self.send_response(code)
            self.send_header("Content-Type", ctype); self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            for k, v in (extra or {}).items():
                self.send_header(k, v)
            self.end_headers(); self.wfile.write(data)

        def do_GET(self):
            if self.path.startswith("/api/") or self.path.startswith("/video") or self.path.startswith("/g/"):
                self._send(503, json.dumps({"paused": True, "until": until}), "application/json")
                return
            page = (PAUSE_PAGE.replace("__T_TITLE__", T["title"]).replace("__T_BACK__", T["back"]).replace("__T_NOTE__", T["note"])
                    .replace("__T_NOW__", T["now"]).replace("__UNTIL_TS__", str(int(until)))
                    .replace("__UNTIL__", datetime.fromtimestamp(until).strftime("%H:%M")))
            self._send(200, page)

        def do_POST(self):
            if self.path != "/resume":
                self._send(404, "not found", "text/plain"); return
            if web_pw_active() and self.client_address[0] not in ("127.0.0.1", "::1"):
                import base64
                ok = False
                h = self.headers.get("Authorization", "")
                if h.startswith("Basic "):
                    try:
                        pw = base64.b64decode(h[6:]).decode("utf-8", "replace").split(":", 1)[1]
                        ok = (hmac.compare_digest(pw.encode(), CFG["web_password"].encode()) if CFG["web_password"] else pw_check(pw))
                    except (ValueError, IndexError):
                        ok = False
                if not ok:
                    self._send(401, "Login required", "text/plain", {"WWW-Authenticate": 'Basic realm="Motion Watch"'}); return
            state["go"] = True
            self._send(200, "<meta http-equiv='refresh' content='15;url=/'>" + tr("Starting …"))

    srv = None
    for _i in range(30):                                   # the old program has just released the port
        try:
            http.server.ThreadingHTTPServer.allow_reuse_address = True
            srv = http.server.ThreadingHTTPServer((WEB_OPTS.get("bind") or "0.0.0.0", int(CFG["web_port"])), H)
            break
        except OSError:
            time.sleep(1.0)
    if srv is not None:
        srv.daemon_threads = True
        threading.Thread(target=srv.serve_forever, daemon=True).start()
    print(f"Motion Watch paused until {datetime.fromtimestamp(until).strftime('%H:%M')} - page on port {CFG['web_port']}")
    sd_notify("READY=1\nSTATUS=paused")
    last_ping = 0.0
    try:
        while time.time() < until and not state["go"]:
            if time.time() - last_ping > 20:
                last_ping = time.time(); sd_notify("WATCHDOG=1")
            time.sleep(0.5)
        if state["go"]:
            log_event("sys", "Pause ended early ('Start now')")
            time.sleep(0.8)                                # the answer reaches the browser first
    except KeyboardInterrupt:
        sys.exit(0)
    restart()


def _guard_file():
    return os.path.join(DATA_DIR, "update_guard.json")


RUNGUARD = {"t0": time.time(), "m0": time.monotonic(), "safe": False, "last": None, "streak": 0, "changed": []}
SAFE_SET = {"ai_enabled": False, "thermal_on": False, "thermal_alarm": False, "nightvision": False, "nightvision_auto": False,
            "patrol": False, "track_person": False, "timelapse_on": False, "light_white": "off", "light_ir": "off"}


def _run_file():
    return os.path.join(DATA_DIR, "run_state.json")


def _run_write(d):
    try:
        tmp = _run_file() + ".tmp"
        with open(tmp, "w") as f:
            json.dump(d, f)
        os.replace(tmp, _run_file())
    except OSError:
        pass


def run_guard_start():
    """At every start: did the last run end without a clean stop (the whole Pi went off)? Two short runs in a row ->
    safe start with the heavy parts off. Then a heartbeat every 10 s keeps the conditions for next time."""
    if DEMO["on"]:
        return
    try:
        with open(_run_file()) as f:
            prev = json.load(f)
    except (OSError, ValueError):
        prev = None
    streak = 0
    if isinstance(prev, dict) and not prev.get("clean"):
        ran = int(prev.get("up", 0))
        RUNGUARD["last"] = {"ran_s": ran, "cpu_temp": prev.get("cpu_temp"), "uv": prev.get("uv"), "throttled": prev.get("throttled"),
                            "cpu": prev.get("cpu"), "ai": prev.get("ai"), "ver": prev.get("ver"), "when": prev.get("beat_txt", "")}
        streak = int(prev.get("streak", 0)) + 1 if ran < 600 else 0
        ct = prev.get("cpu_temp")
        log_event("sys", f"The last run ended unexpectedly after {ran // 60} min {ran % 60} s"
                         + (f" (CPU {ct:.0f} °C" if isinstance(ct, (int, float)) else " (") + (", under-voltage" if prev.get("uv") else "")
                         + (", AI on" if prev.get("ai") else "") + ") - power supply, heat or a crash")
    RUNGUARD["streak"] = streak
    if streak >= 2:
        RUNGUARD["safe"] = True
        RUNGUARD["changed"] = [k for k, v in SAFE_SET.items() if k in CFG and CFG[k] != v]
        for k in RUNGUARD["changed"]:
            CFG[k] = SAFE_SET[k]
        save_settings()
        log_event("sys", "Safe start: the Pi went off twice shortly after starting - AI, thermal camera, night vision, IR light "
                         "and patrol are off. Check power supply (5 V / 5 A) and cooling, then switch them on again one by one.")

        def tell():
            time.sleep(40)
            w = WATCH_REF["w"]
            if w is not None:
                w.notifier.info(tr("Safe start: the Pi went off twice shortly after starting. AI, thermal camera, night vision, "
                                   "IR light and patrol are off - check power supply and cooling."), title="{name}: " + tr("safe start"))
        threading.Thread(target=tell, daemon=True).start()
    state = {"start": time.time(), "up": 0, "clean": False, "streak": streak, "ver": APP_VERSION}
    _run_write(state)

    def clean():
        state["clean"] = True; state["up"] = int(time.monotonic() - RUNGUARD["m0"]); _run_write(state)
    atexit.register(clean); RUNGUARD["clean"] = clean

    def beat():
        while True:
            time.sleep(10)
            sup = STATE.get("supply") or {}
            up = int(time.monotonic() - RUNGUARD["m0"])
            state.update(up=up, cpu_temp=STATE.get("cpu_temp"), uv=bool(sup.get("uv_now") or sup.get("uv_boot")),
                         throttled=bool(sup.get("throttled")), cpu=STATE.get("cpu"), ai=bool(CFG["ai_enabled"] and str(STATE.get("ai_status", "")).startswith("running")),
                         beat_txt=datetime.now().strftime("%Y-%m-%d %H:%M"))
            if up > 1800 and state.get("streak"):
                state["streak"] = 0                              # ran long enough: the next short run starts counting again
            if not state["clean"]:
                _run_write(state)
    threading.Thread(target=beat, daemon=True, name="runguard").start()


def start_guard():
    """Called early at every start. After an update the new version must run 90 s; if it crashes 3 times in a row
    (the autostart restarts it), the previous version is started again."""
    p = _guard_file()
    try:
        with open(p) as f:
            g = json.load(f)
    except (OSError, ValueError):
        return
    if g.get("new") != APP_VERSION:
        if g.get("old") == APP_VERSION and g.get("new"):   # the old program runs again: the new one did not get far
            log_event("sys", f"Version {g['new']} did not start - back to {APP_VERSION}; it will not be installed automatically again")
            try:
                with open(os.path.join(DATA_DIR, "update_bad.json"), "w") as f:
                    json.dump({"version": g["new"]}, f)
            except OSError:
                pass
        try:
            os.remove(p)
        except OSError:
            pass
        return
    g["tries"] = int(g.get("tries", 0)) + 1
    old = g.get("old_path", "")
    if g["tries"] > 3 and old and os.path.isfile(old) and os.path.abspath(old) != os.path.abspath(__file__):
        log_event("sys", f"Version {APP_VERSION} did not start 3 times - going back to {g.get('old', '?')}")
        try:
            with open(os.path.join(DATA_DIR, "update_bad.json"), "w") as f:
                json.dump({"version": APP_VERSION}, f)    # the automatic update will not try this version again
        except OSError:
            pass
        try:
            os.remove(p)
        except OSError:
            pass
        _close_fds_on_exec()
        os.execv(sys.executable, [sys.executable, old] + _base_args())
    try:
        with open(p, "w") as f:
            json.dump(g, f)
    except OSError:
        pass

    def ok_later():
        time.sleep(90)
        try:
            os.remove(p)
            log_event("sys", f"Version {APP_VERSION} runs fine (update finished)")
        except OSError:
            pass
    threading.Thread(target=ok_later, daemon=True).start()


def update_restart(path, version):
    """Finish the recording, save the settings, then replace this program by the chosen file (same options, same PID:
    the autostart keeps working and points to the new file from now on)."""
    RESTART["pending"] = version
    log_event("sys", f"Switching to version {version} - restarting")
    _restart_mark()

    def work():
        time.sleep(2.0)                                   # the page gets its answer first
        try:
            w = WATCH_REF["w"]
            end = time.time() + 10.0
            while w is not None and w.writer is not None and time.time() < end:
                time.sleep(0.2)
            if AUDIO is not None:
                AUDIO.wait_mux(30.0)
            sound_stop(); talk_stop()
            save_settings_now()
            try:                                          # start guard: the new version must prove it starts
                with open(_guard_file(), "w") as f:
                    json.dump({"old": APP_VERSION, "old_path": os.path.abspath(__file__), "new": version, "tries": 0}, f)
            except OSError:
                pass
            _close_fds_on_exec()
            os.execv(sys.executable, [sys.executable, path] + _base_args())
        except Exception as e:
            RESTART["pending"] = ""; UPD["msg"] = f"restart failed: {e}"[:200]; UPD_PROG["phase"] = ""
            log_event("sys", UPD["msg"])
    threading.Thread(target=work, daemon=True, name="update").start()


class UpdateWatcher:
    """Looks for a new version 2 minutes after the start and then every 3 hours. A new one is shown on the page / in the
    window (button to update) and announced once by push message."""
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True, name="updwatch").start()

    def loop(self):
        time.sleep(120)
        last = 0.0
        while True:
            try:
                if time.time() - last > 3 * 3600 or UPD.get("recheck"):
                    UPD["recheck"] = False; last = time.time()
                    self.tick()
                self.auto_install()
            except Exception as e:
                print(f"Update watcher: {e}")
            time.sleep(60)

    def auto_install(self):
        """Automatic update: in the chosen hour, when nothing is going on (disarmed unless allowed, no recording, no person),
        install the newest version. If the new version does not start, the start guard goes back to the old one."""
        if not CFG["update_install"] or RESTART["pending"] or UPD["busy"] or POWER.get("pending"):
            return
        u = STATE.get("update_new") or {}
        v = u.get("version")
        if not v or datetime.now().hour != int(CFG["update_hour"]) % 24:
            return
        if (is_armed() and not CFG["update_install_armed"]) or STATE.get("recording") or STATE.get("persons") or STATE.get("arm_state") == "arming":
            return
        try:
            with open(os.path.join(DATA_DIR, "update_bad.json")) as f:
                if json.load(f).get("version") == v:
                    return                                   # this version was rolled back once: only by hand
        except (OSError, ValueError, AttributeError):
            pass
        if getattr(self, "_tried", {}).get(v, 0) >= 2:
            return                                           # failed twice already: leave it to a person
        self._tried = getattr(self, "_tried", {}); self._tried[v] = self._tried.get(v, 0) + 1
        log_event("sys", f"Automatic update to version {v}")
        w = WATCH_REF["w"]
        if w is not None and CFG["update_push"]:
            de = CFG["lang"] == "de"
            w.notifier.info(trf("Automatic update to version {v} – the program restarts (about 20 s)", v=v), title="{name}: Update")
        ok, err = update_install(v)
        if not ok:
            log_event("sys", f"Automatic update failed: {err}")

    def tick(self):
        if not CFG["update_auto"] or not CFG["update_url"].strip() or RESTART["pending"]:
            return
        items, err = update_check()
        new = sorted((x for x in items if x.get("available") and _installable(x) and _vkey(x["version"]) > _vkey(APP_VERSION)), key=lambda x: _vkey(x["version"]))
        if not new:
            STATE["update_new"] = {}; return
        top = new[-1]
        STATE["update_new"] = {"version": top["version"], "notes": top.get("notes", "")[:300], "date": top.get("date", "")}
        if CFG["update_notified"] != top["version"]:
            CFG["update_notified"] = top["version"]; save_settings()
            log_event("sys", f"New version {top['version']} available")
            w = WATCH_REF["w"]
            if CFG["update_push"] and w is not None:
                de = CFG["lang"] == "de"
                pub = CFG["public_url"].strip().rstrip("/")
                w.notifier.info(trf("New version {v} available - tap «Update now» on the page", v=top["version"]),
                                pub + "/" if pub else "", title="{name}: Update")


def self_test(folder=""):
    """--self-test [FOLDER]: quick checks without camera / hardware (also run on GitHub for every version). Returns 0 = all ok."""
    res = []

    def chk(name, fn):
        try:
            r = fn()
            res.append((name, r is not False, "" if r in (None, True) else str(r)))
        except Exception as e:
            res.append((name, False, f"{e.__class__.__name__}: {e}"[:200]))
    pub, sign, verify = _ed25519_impl()

    def ed():
        sk = bytes.fromhex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60")
        assert pub(sk).hex() == "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"
        sig = sign(sk, b"")
        assert sig.hex().startswith("e5564300c360ac729086e2cc806e828a") and verify(pub(sk), b"", sig) and not verify(pub(sk), b"x", sig)
        assert len(UPDATE_PUBKEY) == 64
    chk("Ed25519 (RFC 8032 test vector)", ed)

    def qr():
        det = cv2.QRCodeDetector()
        for t in ("http://10.42.0.1:5000/", wifi_qr_text("Motion;Watch", "pa:ss"), "x" * 200):
            img = cv2.imdecode(np.frombuffer(qr_png(t, 6), np.uint8), cv2.IMREAD_GRAYSCALE)
            got = det.detectAndDecode(img)[0]
            assert got == t, f"QR decoded {got!r}"
    chk("QR codes (encode + decode)", qr)

    def wp():
        if not webpush_supported():
            return "skipped (python3-cryptography missing)"
        from cryptography.hazmat.primitives import hashes, hmac as chmac, serialization
        from cryptography.hazmat.primitives.asymmetric import ec
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        ua = ec.generate_private_key(ec.SECP256R1()); auth = os.urandom(16)
        ua_pub = ua.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        body_ = _webpush_encrypt(b'{"t":1}', _b64u(ua_pub), _b64u(auth))

        def hm(k, d):
            h = chmac.HMAC(k, hashes.SHA256()); h.update(d); return h.finalize()
        salt, as_pub, ct = body_[:16], body_[21:86], body_[86:]
        sh = ua.exchange(ec.ECDH(), ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), as_pub))
        prk = hm(salt, hm(hm(auth, sh), b"WebPush: info\x00" + ua_pub + as_pub + b"\x01"))
        pt = AESGCM(hm(prk, b"Content-Encoding: aes128gcm\x00\x01")[:16]).decrypt(hm(prk, b"Content-Encoding: nonce\x00\x01")[:12], ct, None)
        assert pt == b'{"t":1}\x02'
    chk("Web push encryption (RFC 8291)", wp)

    def schema():
        miss = [k for _s, k, *_r in TOGGLES + SLIDERS if k not in CFG] + [k for _s, k, *_r in TEXTS if k not in CFG]
        secs = {x[0] for x in TOGGLES + SLIDERS + TEXTS} - set(SECTIONS)
        nde = [lab for _s, _k, lab, *_r in TOGGLES + SLIDERS + TEXTS if lab not in DE]
        assert not miss, f"settings without default: {miss}"
        assert not secs, f"sections missing in SECTIONS: {secs}"
        return f"{len(nde)} labels without German text" if nde else None
    chk("Settings schema", schema)

    def pages():
        node = shutil.which("node")
        names = ["WEB_PAGE", "CAMS_PAGE", "ZONES_PAGE", "REC_PAGE", "DIARY_PAGE", "HELP_PAGE", "LOG_PAGE", "GUEST_PAGE"]
        n = 0
        for nm in names:
            html = render_page(globals()[nm], "live")
            for i, js in enumerate(re.findall(r"<script>(.*?)</script>", html, re.S)):
                if not node:
                    continue
                with tempfile.NamedTemporaryFile("w", suffix=".js", delete=False) as f:
                    f.write(js); fn = f.name
                r = subprocess.run([node, "--check", fn], capture_output=True, text=True)
                os.remove(fn)
                assert r.returncode == 0, f"{nm} script {i}: {r.stderr.strip().splitlines()[-1] if r.stderr else 'error'}"
                n += 1
        return None if node else "JavaScript not checked (node missing)"
    chk("Web pages (render + JavaScript)", pages)

    if folder:
        def manifest():
            with open(os.path.join(folder, "versions.json"), encoding="utf-8") as f:
                m = json.load(f)
            bad = []
            for e in m.get("versions", []):
                p_ = os.path.join(folder, e["file"])
                if not os.path.isfile(p_):
                    continue
                with open(p_, "rb") as f:
                    sha = hashlib.sha256(f.read()).hexdigest()
                if sha != e.get("sha256") or not sig_ok(e["version"], e["file"], sha, e.get("sig")):
                    bad.append(e["version"])
            assert not bad, f"bad checksum / signature: {bad}"
            return f"{len(m.get('versions', []))} versions signed and checked"
        chk("versions.json signatures", manifest)
    ok = all(r[1] for r in res)
    for name, good, note in res:
        print(("✓ " if good else "✗ ") + name + (f" – {note}" if note else ""))
    print("Self-test " + ("OK" if ok else "FAILED") + f" (Motion Watch {APP_VERSION})")
    return 0 if ok else 1


def make_manifest(folder, base_url, sign_key=""):
    """--make-manifest: write versions.json for all webcam_bewegung_X_Y_Z.py in a folder (to put on GitHub / a web server).
    --sign-key FILE: sign every version with the secret key in FILE (64 hex characters; never put this file on GitHub)."""
    base = (base_url or "").rstrip("/") + "/"
    seed = b""
    if sign_key:
        with open(os.path.expanduser(sign_key)) as f:
            seed = bytes.fromhex(f.read().strip())
        if not _ED:
            _ED.extend(_ed25519_impl())
        if _ED[0](seed).hex() != UPDATE_PUBKEY:
            print("Note: this key does not belong to the public key built into this program - devices will not accept the signatures.")
    out = []
    for it in sorted(local_versions(folder), key=lambda x: _vkey(x["version"]), reverse=True):
        with open(it["path"], "rb") as f:
            sha = hashlib.sha256(f.read()).hexdigest()
        e = {"version": it["version"], "file": it["file"], "url": base + it["file"] if base_url else "", "sha256": sha,
             "date": it["date"], "notes": it["notes"]}
        if seed:
            e["sig"] = _ED[1](seed, _sig_msg(it["version"], it["file"], sha)).hex()
        out.append(e)
    p = os.path.join(folder, "versions.json")
    with open(p, "w") as f:
        json.dump({"app": "Motion Watch", "generated": datetime.now().strftime("%Y-%m-%d %H:%M"), "versions": out}, f, indent=1, ensure_ascii=False)
    print(f"{p}: {len(out)} version(s)" + (", signed" if seed else ", NOT signed"))
    return 0


# ----------------------------------------------------------------------------
# Power: shut down / restart the Raspberry Pi (web page + desktop window). The recording is finished and the settings are
#   saved first. Works as root, with the polkit rule of --allow-wifi or (Raspberry Pi OS) with sudo without a password.
# ----------------------------------------------------------------------------
POWER = {"pending": "", "msg": ""}


def _power_cmd(action):
    cmds = [["systemctl", action]]
    if not _is_root() and shutil.which("sudo"):
        cmds.append(["sudo", "-n", "systemctl", action])
    err = ""
    for c in cmds:
        rc, _out, e = _run(c, timeout=30)
        if rc == 0:
            return ""
        err = e or f"exit {rc}"
    return (f"no permission to {'shut down' if action == 'poweroff' else 'restart'} ({err[:120]}) - allow it once with: "
            f"sudo {sys.executable} {os.path.abspath(__file__)} --allow-wifi")


def power_action(action, delay=3.0, source="desktop"):
    """action: poweroff | reboot. The answer comes back at once, the Pi goes down after `delay` seconds."""
    if action not in ("poweroff", "reboot"):
        return False, "unknown action"
    if POWER["pending"]:
        return True, ""
    POWER["pending"] = action; POWER["msg"] = ""
    STATE["power"] = action
    log_event("sys", ("Shutting down the Pi" if action == "poweroff" else "Restarting the Pi") + f" ({source})")

    def work():
        time.sleep(delay)                                    # the page / window gets its answer first
        try:
            w = WATCH_REF["w"]
            end = time.time() + 10.0                         # the camera loop ends a running recording (POWER["pending"])
            while w is not None and w.writer is not None and time.time() < end:
                time.sleep(0.2)
            if AUDIO is not None:
                AUDIO.wait_mux(30.0)
            sound_stop()
            save_settings_now()
        except Exception as e:
            log_event("sys", f"Before shutdown: {e}"[:200])
        err = _power_cmd(action)
        if err:
            POWER["pending"] = ""; POWER["msg"] = err; STATE["power"] = ""
            log_event("sys", ("Shutdown failed: " if action == "poweroff" else "Restart failed: ") + err[:160])
    threading.Thread(target=work, daemon=True, name="power").start()
    return True, ""


class MotionWatch:
    def __init__(self):
        self.cap = None                    # the video source (CvSource / PiCamSource), opened in a background thread
        self.bg = cv2.createBackgroundSubtractorMOG2(history=400, varThreshold=28, detectShadows=False)
        self.weather = WeatherAnalyzer(); self.tracker = Tracker(); self.tuner = AutoTuner(); self.zwatch = ZoneWatch()
        self.ai = AIDetector(); self.hw = Hardware(); self.patrol = Patrol(); self.relays = RelayManager()
        self.frame_out = None; self.jpeg = None; self.jpeg_seq = 0
        self.frame_raw = None; self.raw_until = 0.0
        self.sysmon = SysMonitor(); self.netmon = NetMonitor(); self.remotemon = RemoteMonitor()
        self.sights = SightingTracker(); self.reports = ReportScheduler(); self.battmon = BatteryMonitor()
        self.logkeeper = LogKeeper(); self.updwatch = UpdateWatcher()
        self.mask_buf = deque(maxlen=5)
        self.color_bg = None               # slow colour background for the shadow filter
        self.writer = None; self.last_person_time = 0; self.last_relay_time = 0
        self.rec_name = ""; self.rec_info = None; self.rec_size = None; self._rec_retry = 0.0
        self.preroll = deque()
        self.frame_times = deque(maxlen=30)
        self.seen_t = deque(maxlen=40)           # 2.95.64: when each picture was analysed -> the REAL frame rate
        self.mt = {"id": None, "t": 0.0, "moved": 0.0, "tpl": None, "box": None}  # follow movement: target, its look, last own move
        self.frame_gaps = deque(maxlen=60); self._last_t0 = 0.0     # time between camera frames -> real frame rate of a recording
        self.eco_wake_t = 0.0; self.eco_slow = False; self._eco_src = None
        self.read_failures = 0; self.web_viewers = 0
        self.pre_since = 0.0; self.pre_last = 0.0; self.pre_alerted = False
        self.last_warm = 0.0; self.warm_alerted = False
        self.notifier = Notifier(); self.clahe = cv2.createCLAHE(clipLimit=2.5, tileGridSize=(8, 8))
        self.last_cleanup = 0
        self._open_lock = threading.Lock(); self._open_gen = 0; self._opened = None; self._opening = False; self._retry_at = 0.0
        self._switch_fail_until = 0.0; self._sim_retry_at = 0.0
        if CFG.get("sim_on") and not str(CFG.get("source", "")).startswith("sim:"):
            CFG["source"] = "sim:0"                           # 2.95.55: an older version kept the webcam for good after a failed switch
        os.makedirs(CFG["record_dir"], exist_ok=True); rec_clean_tmp()
        atexit.register(self.close)
        self.presence = PresenceMonitor()
        self.scheduler = Scheduler()
        global THERMAL, AUDIO, BACKUP
        self.timelapse = Timelapse(); THERMAL = ThermalCam()
        if BACKUP is None:
            BACKUP = Backup()
        global TAMPER, LENS
        if LENS is None:
            LENS = LensCheck()
        if TAMPER is None:
            TAMPER = TamperGuard()
            global ENV
            if ENV is None:
                ENV = EnvSensor()
                threading.Thread(target=weather_loop, daemon=True, name="weather").start()
            threading.Thread(target=fleet_loop, daemon=True, name="fleet").start()
            threading.Thread(target=feedback_loop, daemon=True, name="feedback").start()
        global MQTT_BRIDGE, SENSHUB
        if MQTT_BRIDGE is None:
            MQTT_BRIDGE = MqttBridge()
        if SENSHUB is None:
            SENSHUB = SensorHub()
        global STORMWATCH, GPSMODULE
        if STORMWATCH is None:
            STORMWATCH = StormWatch()
        if GPSMODULE is None:
            GPSMODULE = GpsModule()
        global MOVERCTL
        if MOVERCTL is None:
            MOVERCTL = MoverControl()
        global SOLARMON, SIMLINK
        if SOLARMON is None:
            SOLARMON = SolarMonitor()
        if SIMLINK is None:
            SIMLINK = SimLink()
            SimDiscovery()
            ToolsWatch(); UplinkWatch(); WifiGuard()
            threading.Thread(target=sim_autoupdate, daemon=True, name="simupdate").start()
        if AUDIO is None:
            AUDIO = AudioMonitor()
            SOUNDEV_OBJ["o"] = SoundEvents()
            if bt_available():
                threading.Thread(target=lambda: (bt_list(), bt_keeper()), daemon=True, name="bt").start()
        hotspot_password()                                 # the own Wi-Fi has its password from the start (shown on the page)
        WATCH_REF["w"] = self
        self.request_source(CFG["source"])

    def close(self):
        if self.writer is not None:
            self.writer.release(); self.writer = None
            self._finish_recording()
        sound_stop()
        save_settings_now()

    # ---- recordings folder housekeeping ---------------------------------
    def cleanup_recordings(self):
        """Delete the oldest recordings (video + snapshot + info file belong together) until below record_max_gb.
        Favourites (star in the preview page) are never deleted."""
        groups = {}
        for f in glob.glob(os.path.join(CFG["record_dir"], "*")):
            if os.path.isfile(f):
                groups.setdefault(os.path.splitext(os.path.basename(f))[0], []).append(f)
        items = []
        for stem, fs in groups.items():
            try:
                items.append((max(os.path.getmtime(f) for f in fs), sum(os.path.getsize(f) for f in fs), stem, fs))
            except OSError:
                pass
        items.sort(key=lambda g: g[0])
        total = sum(g[1] for g in items)
        removable = [g for g in items if not _read_sidecar(g[2] + ".json").get("fav")]
        limit = CFG["record_max_gb"] * 1024 ** 3
        removed = 0

        def card_full():
            try:
                return shutil.disk_usage(CFG["record_dir"]).free < 400 * 1024 ** 2      # keep 400 MB free for the system
            except OSError:
                return False
        while (total > limit or card_full()) and removable and len(items) - removed > 1:
            _mt, size, stem, fs = removable.pop(0)
            if any(os.path.basename(f) in LIVE_RECS or os.path.basename(f) == self.rec_name for f in fs):
                continue                                          # never delete what is being recorded right now
            try:
                for f in fs:
                    os.remove(f)
            except OSError:
                break
            rec_purge_extras(stem)
            total -= size; removed += 1
        STATE["rec_dir_mb"] = int(total / 1024 ** 2)
        if removed:
            log_event("rec", f"Cleanup: {removed} old recording(s) deleted, folder now {STATE['rec_dir_mb']} MB")

    # ---- video source ----------------------------------------------------
    def request_source(self, spec):
        """Switch to another video source (any thread). The running camera keeps working until the new one delivers a picture."""
        CFG["source"] = spec; save_settings()
        active = STATE["source_id"]
        if self.cap is not None and (spec == active or (spec == "auto" and active.startswith("usb:"))):
            return                                                # that camera is already running
        self._open_gen += 1
        self._start_opener(spec)

    def _start_opener(self, spec, quiet=False):
        gen = self._open_gen
        self._opening = True
        if not quiet:
            STATE["source_status"] = "connecting…"

        def work():
            res = open_source(spec)
            with self._open_lock:
                if gen == self._open_gen:
                    self._opened = res; self._opening = False
                elif res[0] is not None:
                    res[0].release()                              # a newer request replaced this one
        threading.Thread(target=work, daemon=True).start()

    def _take_opened(self):
        with self._open_lock:
            res, self._opened = self._opened, None
        return res

    def _apply_opened(self, res):
        src, sid, label, err = res
        if src is None:
            log_event("sys", f"Video source '{label}' not available: {err}")
            if self.cap is not None and str(STATE.get("source_id", "")).startswith("sim:") and not CFG["sim_on"]:
                self.cap.release(); self.cap = None                # simulation switched off: never keep the simulator picture
                STATE["source_status"] = f"failed: {err}"; self._retry_at = time.time() + 3.0
            elif self.cap is not None and str(sid).startswith("sim:") and CFG["sim_on"]:
                # 2.95.55: the simulation is on but its camera gives no picture (slow PC / VM, firewall): keep the working
                # camera for now, but stay with the simulator and try again - before, the webcam stayed for good
                STATE["source_status"] = f"switch failed: simulator camera - {err}, next try in 10 s (still using {STATE['source_label']})"
                self._switch_fail_until = time.time() + 12.0; self._sim_retry_at = time.time() + 10.0
            elif self.cap is not None:                            # a switch failed: keep the working camera
                STATE["source_status"] = f"switch failed: {err} (still using {STATE['source_label']})"
                self._switch_fail_until = time.time() + 60.0   # yellow note for a minute, the camera keeps working
                CFG["source"] = STATE["source_id"]; save_settings()
            else:
                STATE["source_status"] = f"failed: {err}"
                self._retry_at = time.time() + 3.0
            return
        old, self.cap = self.cap, src
        if old is not None:
            old.release()
        self.reset_scene()
        size = getattr(src, "size", None)
        STATE.update(source_id=sid, source_label=label, source_status="connected",
                     source_res=f"{size[0]}x{size[1]}" if size else "")
        log_event("rec", f"Video source: {label}" + (f" ({STATE['source_res']})" if STATE["source_res"] else ""))

    def reset_scene(self):
        """New camera = new picture size and scene: forget everything that depends on the old picture."""
        if self.writer is not None:
            self.writer.release(); self.writer = None
            self._finish_recording()
        self.bg = cv2.createBackgroundSubtractorMOG2(history=400, varThreshold=28, detectShadows=False)
        self.weather = WeatherAnalyzer(); self.tracker = Tracker()
        self.mask_buf.clear(); self.color_bg = None; self.preroll.clear()
        self.tuner.reset()
        self.read_failures = 0

    def no_camera_frame(self):
        img = np.zeros((360, 640, 3), np.uint8)
        busy = STATE["source_status"].startswith(("connecting", "connection lost"))
        ascii_ = lambda s: str(s).encode("ascii", "replace").decode()
        cv2.putText(img, "CONNECTING..." if busy else "NO CAMERA FOUND", (150, 150), cv2.FONT_HERSHEY_SIMPLEX, 1.1,
                    (0, 200, 255) if busy else (0, 0, 255), 3)
        cv2.putText(img, ascii_(source_label(CFG["source"]))[:50], (150, 195), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (230, 230, 230), 2)
        cv2.putText(img, ascii_(STATE["source_status"])[:60], (150, 230), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (200, 200, 200), 1)
        cv2.putText(img, "check the camera / network  |  ls /dev/video*", (150, 265), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (150, 150, 150), 1)
        return img

    # ---- processing ------------------------------------------------------
    def preprocess(self, gray, rain_mode):
        if rain_mode:
            g = cv2.medianBlur(cv2.GaussianBlur(gray, (9, 9), 0), 5)
            self.mask_buf.append(g)
            if len(self.mask_buf) >= 3:
                g = np.median(np.array(self.mask_buf), axis=0).astype(np.uint8)
            return g
        self.mask_buf.clear()
        return cv2.GaussianBlur(gray, (5, 5), 0)

    def remove_shadows(self, fg, small):
        """Drop moving pixels that are only a darker copy of the background (= shadows)."""
        if self.color_bg is None:
            self.color_bg = small.astype(np.float32)
            return fg
        cv2.accumulateWeighted(small, self.color_bg, 0.002)
        if not CFG["shadow_filter"] or not np.any(fg):
            return fg
        bg = self.color_bg.astype(np.uint8)
        hsv_c = cv2.cvtColor(small, cv2.COLOR_BGR2HSV); hsv_b = cv2.cvtColor(bg, cv2.COLOR_BGR2HSV)
        vb = hsv_b[:, :, 2].astype(np.float32) + 1.0
        ratio = hsv_c[:, :, 2].astype(np.float32) / vb
        dh = np.abs(hsv_c[:, :, 0].astype(np.int16) - hsv_b[:, :, 0].astype(np.int16))
        dh = np.minimum(dh, 180 - dh)
        ds = np.abs(hsv_c[:, :, 1].astype(np.int16) - hsv_b[:, :, 1].astype(np.int16))
        # on grey / low-saturation ground (asphalt, concrete, dusk) the hue is numerically unstable,
        # so the hue test is skipped there and only brightness ratio + saturation decide
        low_sat = (hsv_b[:, :, 1] < 50) & (hsv_c[:, :, 1] < 70)
        hue_ok = (dh < 12) | low_sat
        shadow = ((ratio > CFG["shadow_ratio_min"]) & (ratio < CFG["shadow_ratio_max"])
                  & hue_ok & (ds < 45) & (fg > 0)).astype(np.uint8) * 255
        # smooth the shadow mask so single person pixels are not punched out
        shadow = cv2.morphologyEx(shadow, cv2.MORPH_CLOSE, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)))
        shadow = cv2.morphologyEx(shadow, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)))
        total = np.count_nonzero(fg)
        STATE["shadow_pct"] = int(100 * np.count_nonzero(shadow) / max(1, total))
        return cv2.bitwise_and(fg, cv2.bitwise_not(shadow))

    def foreground(self, gray, small, rain_mode, wind_boost):
        sens = CFG["sensitivity"] / 100.0
        self.bg.setVarThreshold(16 + (1 - sens) * 40 + (12 if rain_mode else 0))
        lr = 0.004 if rain_mode else 0.002
        mv = self.mt["moved"]
        if mv > self.mt.get("bg_reset", 0.0) and time.time() - mv > 0.3:
            lr = 1.0; self.mt["bg_reset"] = time.time()          # the camera turned to follow movement and stands again: new background at once
        elif time.time() - self.mt.get("bg_reset", 0.0) < 1.5:
            lr = 0.08                                            # ... and the "ghost" of the animal in it fades quickly
        fg = self.bg.apply(gray, learningRate=lr)
        _, fg = cv2.threshold(fg, 200, 255, cv2.THRESH_BINARY)
        fg = self.remove_shadows(fg, small)                      # colour based shadow removal
        k = 5 if rain_mode or wind_boost > 1.5 else 3
        fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k)))
        return cv2.dilate(fg, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 13)), 1)

    def classify(self, t, frame_area, wind_boost, ai_boxes):
        x, y, w, h = t.box
        aspect = w / float(h + 1e-6); area = w * h; sp = t.speed()
        t.ai_confirmed = any(iou(t.box, b) > 0.2 for b in ai_boxes)
        k = fps_k()                                            # 2.95.65: speed limits for the real frame rate
        if CFG["car_filter"] and not t.ai_confirmed:
            sv = float(np.median(t.speeds)) if len(t.speeds) >= 3 else sp     # one jump of the tracker is no vehicle
            vehicle = (aspect > CFG["car_aspect"] and sv > 3.0 * k) or sv > CFG["car_speed"] * k or \
                      (area > CFG["car_area_frac"] * frame_area and aspect > 1.2 and sv > 1.0 * k)
            vehicle = vehicle and len(t.speeds) >= 2                 # judged from two steps on, not from the very first
            if vehicle:
                if not t.is_vehicle:
                    STATE["ignored_vehicles"] += 1
                    log_event("car", f"Vehicle-like object #{t.id} ignored (aspect {aspect:.2f}, speed {sp:.1f})")
                t.is_vehicle, t.is_person = True, False
                return
            t.is_vehicle = False                               # shape became person-like again -> re-evaluate
        need_frames = int(CFG["walk_frames"] * wind_boost)
        walking = (len(t.speeds) >= need_frames and CFG["walk_min_speed"] <= sp <= CFG["walk_max_speed"] * k
                   and t.steadiness() >= CFG["speed_consistency"] and aspect < CFG["car_aspect"])
        if t.ai_confirmed:
            walking = True                                  # AI says person -> person
        elif CFG["ai_require"] and self.ai.net is not None and CFG["ai_enabled"]:
            walking = False                                 # needs AI confirmation
        elif t.is_person and CFG["person_sticky"] and sp <= CFG["walk_max_speed"] * k:
            walking = True                                  # keep flag while tracked (may stand still)
        if walking and not t.is_person:
            STATE["detections_total"] += 1
            log_event("person", f"Person #{t.id} {'AI-confirmed' if t.ai_confirmed else 'walking'}, speed {sp:.1f} px/f")
        t.is_person = walking

    # ---- servo tracking --------------------------------------------------
    def motion_target(self, candidates, animals, pw, ph, gray):
        """Something that is not a person but really goes somewhere (an animal, also one the AI does not know):
        big enough, moving for some time and away from where it started (branches in the wind swing back and forth).
        Once chosen it is followed by its look (template), so the turning camera does not lose it."""
        now = time.time(); area = float(pw * ph); mt = self.mt
        if STATE.get("wind_boost", 1.0) > 1.6 or STATE.get("wind_level") in ("strong", "storm"):
            mt.update(id=None, tpl=None); return None    # strong wind: everything moves, do not chase it

        def keep(b):                                      # remember where it was; something that only swings to and fro is let go
            tr = mt.setdefault("trail", deque(maxlen=60)); tr.append((now, b[0] + b[2] / 2.0, b[1] + b[3] / 2.0))
            pts = [p for p in tr if now - p[0] <= 4.0]
            if len(pts) >= 8 and now - pts[0][0] >= 3.0 and now - mt.get("since", now) > 4.0:
                path = sum(math.hypot(pts[i][1] - pts[i - 1][1], pts[i][2] - pts[i - 1][2]) for i in range(1, len(pts)))
                net = math.hypot(pts[-1][1] - pts[0][1], pts[-1][2] - pts[0][2])
                if path > 0.08 * pw and net < 0.25 * path and now - mt["moved"] > 1.0:
                    log_event("servo", "Followed movement only swings to and fro (branch in the wind?) - released")
                    mt.update(id=None, tpl=None); mt["trail"].clear(); return None
            mt["box"] = b; mt["t"] = now
            return b
        def tight(b):                                     # the movement boxes are made bigger (dilate 7 x 13): back to the animal
            x, y, w, h = [int(v) for v in b[:4]]
            if w > 14 and h > 20:
                x, y, w, h = x + 3, y + 6, w - 6, h - 12
            w = max(8, w); h = max(8, h)
            return max(0, min(pw - w, x)), max(0, min(ph - h, y)), w, h
        if mt.get("tpl") is not None and now - mt["moved"] > 1.0:   # camera stands still: the movement itself is the best guide
            x, y, w, h = mt["box"]; cx, cy = x + w / 2.0, y + h / 2.0
            near = [t for t in candidates if not t.lost and math.hypot(t.center()[0] - cx, t.center()[1] - cy) < max(max(w, h) * 2.5 + 20, 0.2 * pw)
                    and t.box[2] * t.box[3] < 0.2 * area]
            if near:
                t = min(near, key=lambda t: math.hypot(t.center()[0] - cx, t.center()[1] - cy))
                b = tight(t.box); tpl = gray[b[1]:b[1] + b[3], b[0]:b[0] + b[2]].copy()
                if tpl.shape[0] >= 8 and tpl.shape[1] >= 8:
                    mt.update(tpl=tpl, move_t=now)
                    return keep(b)
        if mt.get("tpl") is not None:                     # camera turns / nothing moves: find it again by its look
            x, y, w, h = mt["box"]; th_, tw_ = mt["tpl"].shape
            r = int(max(w, h) * 2.5) + (int(0.35 * pw) if now - mt["moved"] < 1.5 else 0)
            x0, y0 = max(0, x - r), max(0, y - r); x1, y1 = min(pw, x + w + r), min(ph, y + h + r)
            best = None
            if x1 - x0 > tw_ and y1 - y0 > th_:
                res = cv2.matchTemplate(gray[y0:y1, x0:x1], mt["tpl"], cv2.TM_CCOEFF_NORMED)
                _mn, sc, _l, loc = cv2.minMaxLoc(res)
                if sc >= 0.5:
                    best = (x0 + loc[0], y0 + loc[1], tw_, th_)
                    if sc > 0.65:                             # it changes its look while walking: learn slowly
                        cur = gray[best[1]:best[1] + th_, best[0]:best[0] + tw_]
                        if cur.shape == mt["tpl"].shape:
                            mt["tpl"] = cv2.addWeighted(mt["tpl"], 0.8, cur, 0.2, 0)
            if best is not None:
                if any(iou(t.box, best) > 0.05 for t in candidates if not t.lost):
                    mt["move_t"] = now
                if now - mt["moved"] > 1.5 and now - mt.get("move_t", now) > 3.0:
                    log_event("servo", "Followed movement: nothing moves there any more - released")   # stands still or gone
                    mt.update(id=None, tpl=None); return None
                return keep(best)
            if now - mt["t"] > 2.0:
                bx = mt["box"]; cx = (bx[0] + bx[2] / 2.0) / pw
                if (cx < 0.2 or cx > 0.8) and now - mt["moved"] > 0.4:     # it left the picture at the side: one look after it
                    p0 = CFG["pan"]; self.track((int((0.1 if cx < 0.5 else 0.9) * pw), int(ph / 2), 1, 1), pw, ph, 1.5)
                    if CFG["pan"] != p0:
                        mt["moved"] = now
                    log_event("servo", "Followed movement left the picture - looking after it")
                mt.update(id=None, tpl=None)
            return None
        amin = max(0.0002, float(CFG["track_motion_min"]) / 100.0) * area
        ok = []
        for t in candidates:
            a = t.box[2] * t.box[3]
            if t.lost or (t.is_vehicle and a > 0.02 * area):   # a small animal walking sideways looks "vehicle-like" - a car is big
                continue
            if a < amin or a > 0.35 * area:
                continue
            ok.append(t)
        box = None
        if animals:                                       # an animal the AI knows: at once
            b = max(animals, key=lambda o: o[2] * o[3]); box = tuple(int(v) for v in b[:4]); what = "animal (AI)"
        else:
            hold = float(CFG["track_motion_hold"])
            def goes(t):                                  # really goes somewhere: far enough and mostly in one direction
                net = math.hypot(t.center()[0] - t.start[0], t.center()[1] - t.start[1])
                h_ = list(t.hist); path = sum(math.hypot(h_[i][0] - h_[i - 1][0], h_[i][1] - h_[i - 1][1]) for i in range(1, len(h_)))
                net_h = math.hypot(h_[-1][0] - h_[0][0], h_[-1][1] - h_[0][1]) if len(h_) > 1 else 0.0
                return net >= 0.06 * pw and net_h >= 0.6 * max(path, 1e-6)
            good = [t for t in ok if now - t.born >= hold and goes(t)]
            if good:
                t = max(good, key=lambda t: t.box[2] * t.box[3]); box = tuple(int(v) for v in t.box); what = f"#{t.id}"
        if box is None:
            return None
        x, y, w, h = tight(box)
        tpl = gray[y:y + h, x:x + w].copy()
        if tpl.shape[0] < 8 or tpl.shape[1] < 8:
            return None
        log_event("servo", f"Following movement {what} ({w}x{h} px, not a person)")
        mt.update(id=what, tpl=tpl, box=(x, y, w, h), t=now, move_t=now, since=now); mt.setdefault("trail", deque(maxlen=60)).clear()
        return (x, y, w, h)

    def track(self, target_box, pw, ph, gain=1.0):
        x, y, w, h = target_box[:4]
        ex = (x + w / 2.0) / pw - 0.5          # -0.5 .. 0.5  (right = positive)
        ey = (y + h / 2.0) / ph - 0.5          # down  = positive
        dz = CFG["track_deadzone"]
        g = CFG["track_gain"] * 10.0 * gain
        if abs(ex) > dz:
            CFG["pan"] = max(0.0, min(100.0, CFG["pan"] + ex * g))
        if abs(ey) > dz:
            CFG["tilt"] = max(0.0, min(100.0, CFG["tilt"] - ey * g))

    # ---- recording ----------------------------------------------
    def handle_recording(self, frame, persons):
        now = time.time()
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")          # video and snapshot of one event share the same name
        if not is_armed():
            persons = []                                  # disarmed: no snapshots, no notifications, no new recordings
        settle = now - SIM.get("off_t", 0.0) < 30.0       # just back from the simulation: the camera learns its picture
        if settle:
            persons = []; self.last_person_time = 0
        new_person = bool(persons) and (now - self.last_person_time) > CFG["record_tail"]
        if persons:
            self.last_person_time = now
        if new_person:
            snap = None
            if CFG["snapshot_on_person"] and not CFG["sim_on"]:
                snap = os.path.join(CFG["record_dir"], f"person_{stamp}.jpg")
                cv2.imwrite(snap, frame, [cv2.IMWRITE_JPEG_QUALITY, 85]); gps_tag_jpg(snap)
            self.notifier.person(len(persons), snap, frame)
            try:
                alarm_track_begin("person", stamp, snap)
            except Exception:
                pass
            if snap and BACKUP is not None and CFG["backup_type"] != "off":
                BACKUP.add(snap, {"first": True})                 # off the device at once - a thief may take the Pi
            push_alert("person", "person", count=len(persons), source=STATE["source_label"])
            siren_alarm("person")
        man_rec = now < QUICK["rec_until"]
        want = man_rec or CFG["record"] and ((self.last_person_time > 0 and (now - self.last_person_time) < CFG["record_tail"])
                                  or (CFG["thermal_alarm"] and is_armed() and now - self.last_warm < CFG["record_tail"])
                                  or (CFG["noise_alarm"] and AUDIO is not None and now - AUDIO.last_noise < CFG["record_tail"]))
        if POWER["pending"] or CFG["sim_on"] or settle:
            want = False                                  # the Pi shuts down / simulation: no (or finish the) recording
        h, w = frame.shape[:2]
        if self.writer is not None and (self.rec_size != (w, h) or getattr(self.writer, "failed", False)):
            early = getattr(self.writer, "failed", False) and time.time() - getattr(self.writer, "t_open", 0) < 15
            if early:                                          # 2.95.33: died right away -> other encoder, wait before trying
                _BAD_CODECS.add("ffmpeg_hw" if getattr(self.writer, "hw", False) else "ffmpeg")
                self._rec_retry = now + 15.0
                log_event("rec", "The video encoder stopped right after the start - trying another one in 15 s")
                REC_HEALTH.update(fail_t=time.time(), fail_n=REC_HEALTH["fail_n"] + 1, msg="the video encoder stopped right after the start")
            self.writer.release(); self.writer = None          # picture size changed (camera switched) or the encoder died
            self._finish_recording()
        pre = float(CFG["pre_roll"])
        if self.writer is None and not want and pre > 0 and CFG["record"] and not CFG["sim_on"]:
            ok, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 70])      # small ring buffer of recent frames
            if ok:
                self.preroll.append((now, buf.tobytes()))
        while self.preroll and (pre <= 0 or now - self.preroll[0][0] > pre + 0.5):
            self.preroll.popleft()
        if want and self.writer is None and now >= self._rec_retry:
            if now - self.last_cleanup > 60:
                self.cleanup_recordings(); self.last_cleanup = now
            name = os.path.join(CFG["record_dir"], (f"manual_{stamp}.mp4" if man_rec else f"person_{stamp}.mp4"))
            real = len(self.frame_gaps) / sum(self.frame_gaps) if len(self.frame_gaps) >= 5 and sum(self.frame_gaps) > 0 else 0.0
            fps = max(2.0, min(30.0, real or float(STATE["fps"]) or 15.0))     # real frame rate -> correct playback speed
            self.writer, codec = open_writer(name, fps, (w, h))
            if self.writer is None:
                self._rec_retry = now + 30.0
                log_event("rec", "Recording failed: no video encoder could be opened (retry in 30 s)")
                REC_HEALTH.update(fail_t=time.time(), fail_n=REC_HEALTH["fail_n"] + 1, msg="no video encoder could be opened (drive full or missing?)")
            else:
                self.rec_name = os.path.basename(name); self.rec_size = (w, h); STATE["rec_name"] = self.rec_name
                REC_HEALTH.update(fail_n=0)
                self.rec_info = {"start": now - (now - self.preroll[0][0] if self.preroll else 0.0), "fps": fps, "frames": 0, "persons": 0,
                                 "codec": codec, "source": STATE["source_label"], "source_id": STATE["source_id"],
                                 "schedules": list(SCHED["active"])}
                n = 0
                for _t, jb in self.preroll:                            # the seconds before the detection come first
                    img = cv2.imdecode(np.frombuffer(jb, np.uint8), cv2.IMREAD_COLOR)
                    if img is not None and img.shape[:2] == (h, w):
                        self.writer.write(img); n += 1
                self.preroll.clear(); self.rec_info["frames"] += n
                if AUDIO is not None and AUDIO.rec_start(name, self.rec_info["start"]):
                    self.rec_info["audio"] = name
                log_event("rec", f"Recording started: {self.rec_name} ({fps:.0f} fps, {STATE['recording_enc'] or codec}"
                                 + (f", {n} pre-roll frames" if n else "") + ")")
        elif not want and self.writer is not None:
            self.writer.release(); self.writer = None
            self._finish_recording()
            log_event("rec", "Recording stopped")
        if self.writer is not None:
            rs = tuple(getattr(self, "rec_size", ()) or ())
            if len(rs) == 2 and (frame.shape[1], frame.shape[0]) != rs:
                frame = cv2.resize(frame, rs)             # picture turned during a recording: keep the size of the file
            self.writer.write(frame)
            self.rec_info["frames"] += 1; self.rec_info["persons"] = max(self.rec_info["persons"], len(persons))
        STATE["recording"] = self.writer is not None

    def _finish_recording(self):
        """Write the small info file (<name>.json) next to a finished recording: source, schedules, duration, codec ..."""
        info, name = self.rec_info, self.rec_name
        self.rec_info = None; self.rec_name = ""; STATE["rec_name"] = ""
        if not info or not name:
            return
        meta = {"start": datetime.fromtimestamp(info["start"]).isoformat(timespec="seconds"),
                "end": datetime.now().isoformat(timespec="seconds"),
                "duration": round(info["frames"] / info["fps"], 1) if info["fps"] else 0.0,
                "frames": info["frames"], "fps": round(info["fps"], 1), "codec": info["codec"],
                "persons": info["persons"], "source": info["source"], "source_id": info["source_id"],
                "schedules": info["schedules"]}
        g = gps_now() if CFG["gps_tag"] else None
        if g:
            meta["gps"] = {"lat": g[0], "lon": g[1], "src": g[2]}
        try:
            with open(os.path.join(CFG["record_dir"], os.path.splitext(name)[0] + ".json"), "w") as f:
                json.dump(meta, f)
        except OSError:
            pass
        if info.get("audio") and AUDIO is not None:
            AUDIO.rec_stop(info["audio"], info["frames"], info["fps"])       # joins the sound with the video (background)
        elif g:
            threading.Thread(target=gps_tag_video, args=(os.path.join(CFG["record_dir"], name),), daemon=True).start()
        if BACKUP is not None and CFG["backup_type"] != "off" and (CFG["backup_all"] or info["persons"] or is_armed()):
            BACKUP.add(os.path.join(CFG["record_dir"], name), meta)

    # ---- power saving --------------------------------------------------
    def _eco(self, present, t0):
        """Power saving: while nothing happens only eco_fps pictures per second (camera slower, less CPU = less current).
        Movement, noise, an alarm, a recording, manual control or (if wanted) somebody watching = full speed for eco_wake s."""
        if not CFG["eco_on"]:
            if self.eco_slow:
                self._eco_set(False)
            STATE["eco"] = "off"; return
        busy = (bool(present & {"prealarm", "motion", "person", "warm", "noise"}) or self.writer is not None or STATE["tracking"] or manual_active() or TL_HOLD["on"]
                or (CFG["eco_view_full"] and self.web_viewers > 0) or (AUDIO is not None and AUDIO.noisy())
                or TALK["proc"] is not None or POWER["pending"] or time.time() - SENS["pir_t"] < 3)
        if busy:
            self.eco_wake_t = t0
        slow = t0 - self.eco_wake_t > float(CFG["eco_wake"])
        if slow != self.eco_slow or self._eco_src is not self.cap:
            self._eco_set(slow)
        STATE["eco"] = "saving" if slow else "awake"
        if slow:
            wait = 1.0 / eco_fps_now() - (time.time() - t0)
            end = time.time() + max(0.0, wait)
            while time.time() < end and self.eco_slow and CFG["eco_on"]:
                if (CFG["eco_view_full"] and self.web_viewers > 0) or manual_active() or (AUDIO is not None and AUDIO.noisy()) or time.time() - SENS["pir_t"] < 1:
                    self.eco_wake_t = time.time(); break               # wake up at once
                time.sleep(0.05)

    def _eco_set(self, slow):
        if slow != self.eco_slow:
            log_event("sys", "Power saving: few pictures (all quiet)" if slow else "Power saving: full speed")
        self.eco_slow = slow; self._eco_src = self.cap
        if self.cap is not None and hasattr(self.cap, "set_fps"):
            self.cap.set_fps(eco_fps_now() if slow else None)
        self._last_t0 = 0.0

    # ---- main loop -------------------------------------------------------
    def toolmode_frame(self):
        img = np.zeros((360, 640, 3), np.uint8)
        cv2.putText(img, "|| TOOL MODE", (150, 150), cv2.FONT_HERSHEY_SIMPLEX, 1.1, (0, 200, 255), 3)
        cv2.putText(img, "monitoring paused until " + datetime.fromtimestamp(TOOLMODE["until"]).strftime("%H:%M"), (150, 195),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.7, (230, 230, 230), 2)
        cv2.putText(img, "all computing power for the tools", (150, 230), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (200, 200, 200), 1)
        return img

    def run(self):
        """2.95.33: the camera loop must never stop for good. An error is logged, the scene is learnt again and the loop
        goes on; after several errors in a row while armed, a push message says so."""
        errs = deque(maxlen=20)
        while True:
            try:
                self._run_loop()
            except Exception as e:
                now = time.time(); errs.append(now)
                import traceback
                tb = traceback.format_exc(limit=4).strip().splitlines()
                log_event("sys", f"Camera loop error (restarted): {type(e).__name__}: {e}"[:200] + " | " + " / ".join(x.strip() for x in tb[-3:])[:300])
                try:
                    self._reset_models()
                except Exception:
                    pass
                recent = [x for x in errs if now - x < 300]
                if len(recent) == 5 and is_armed():
                    try:
                        self.notifier.alert("{name}: " + tr("Camera loop disturbed"), tr("The detection had 5 errors in 5 minutes and keeps restarting - please check the log."), None)
                    except Exception:
                        pass
                time.sleep(min(10.0, 0.5 * len(recent)))

    def _reset_models(self):
        """only the learnt background / trackers (picture size changed) - a running recording goes on"""
        self.bg = cv2.createBackgroundSubtractorMOG2(history=400, varThreshold=28, detectShadows=False)
        self.weather = WeatherAnalyzer(); self.tracker = Tracker()
        self.mask_buf.clear(); self.color_bg = None
        self.tuner.reset()

    def _run_loop(self):
        tm_was = False
        while True:
            HEART["t"] = time.time()
            a_now = is_armed()
            if a_now != getattr(self, "_armed_was", a_now):     # 2.95.33: a warm body / movement seen while disarmed
                self.warm_alerted = False; self.pre_alerted = False   # must still alarm after arming
            self._armed_was = a_now
            if toolmode_on():                             # tool mode: the camera is closed, nothing is detected
                if not tm_was:
                    tm_was = True
                    if self.cap is not None:
                        try:
                            self.cap.release()
                        except Exception:
                            pass
                        self.cap = None
                    try:
                        self.reset_scene()                # a running recording is finished, the scene is learnt again later
                    except Exception:
                        pass
                    self.relays.update(set()); STATE["present"] = []; STATE["persons"] = 0; STATE["tracking"] = False
                    STATE["source_status"] = "tool mode"
                    self.frame_out = self.toolmode_frame()
                    ok_, buf_ = cv2.imencode(".jpg", self.frame_out, [cv2.IMWRITE_JPEG_QUALITY, 70])
                    self._tm_jpeg = buf_.tobytes() if ok_ else None
                if getattr(self, "_tm_jpeg", None):              # the live picture shows the pause picture (once a second)
                    self.jpeg = self._tm_jpeg; self.jpeg_seq += 1
                time.sleep(1.0); continue
            if tm_was:
                tm_was = False; self._retry_at = 0.0
                STATE["source_status"] = "connecting"
                log_event("sys", "Tool mode over - camera and detection run again")
            opened = self._take_opened()
            if opened is not None:
                self._apply_opened(opened)
            if self.cap is None:
                self.relays.update(set()); STATE["present"] = []
                self.frame_out = self.no_camera_frame(); time.sleep(0.5)
                if not self._opening and time.time() >= self._retry_at:
                    self._start_opener(CFG["source"])
                continue
            if self._switch_fail_until and time.time() >= self._switch_fail_until:
                self._switch_fail_until = 0.0
                if STATE["source_status"].startswith(("switch failed", "simulator camera")):
                    STATE["source_status"] = "connected"
            if (CFG["sim_on"] and str(CFG["source"]).startswith("sim:") and not str(STATE.get("source_id", "")).startswith("sim:")
                    and not self._opening and time.time() >= self._sim_retry_at):
                self._sim_retry_at = time.time() + 10.0          # 2.95.55: simulation on, but another camera runs: try the simulator again
                self._open_gen += 1; self._start_opener(CFG["source"], quiet=True)
            ok, frame = self.cap.read()
            if not ok:
                self.read_failures += 1
                if self.read_failures >= 60:            # ~3 s without a frame -> reconnect the source
                    log_event("sys", "Camera stopped delivering frames - reconnecting")
                    STATE["source_status"] = "connection lost - reconnecting"
                    if self.writer is not None:          # 2.95.33: the recording up to now is kept and backed up
                        try:
                            self.writer.release()
                        except Exception:
                            pass
                        self.writer = None; self._finish_recording()
                    if is_armed() and not CFG["sim_on"] and time.time() - getattr(self, "_lost_alert", 0) > 600:
                        self._lost_alert = time.time()
                        try:
                            self.notifier.alert("{name}: " + tr("Camera lost"), tr("The camera stopped delivering pictures - reconnecting."), self.frame_out)
                        except Exception:
                            pass
                    self.cap.release()
                    self.cap = None; self.read_failures = 0; self._retry_at = time.time() + 2.0
                time.sleep(0.05); continue
            self.read_failures = 0
            ok_ = (str(CFG.get("cam_rotate", "0")), bool(CFG.get("cam_mirror")))
            if ok_ != getattr(self, "_orient", ok_):        # turned / mirrored now: a new scene for the detection
                self.reset_scene()
                if TAMPER is not None:
                    TAMPER.ref = None; TAMPER.settle = time.time() + 10   # no "camera turned" alarm because of this
                log_event("sys", f"Camera picture: turned {ok_[0]}°" + (", mirrored" if ok_[1] else ""))
            self._orient = ok_
            frame = cam_orient(frame)                     # turned / mirrored as set, before zones and detection
            frame = apply_privacy(frame)                  # privacy zones: black before anything else sees the picture
            rec_clean = frame.copy() if (CFG["record"] or QUICK["rec_until"] > 0 or self.writer is not None) and CFG["rec_marks"] != "full" else None
            rec_animals = []
            t0 = time.time()
            pm = CFG["picture_mode"]
            if pm == "grey" or (pm == "night_grey" and (LIGHTS["dark"] or (STATE.get("lights") or {}).get("ir"))):
                frame = cv2.cvtColor(cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY), cv2.COLOR_GRAY2BGR)
            if self._last_t0 and t0 - self._last_t0 < 2.0 and not self.eco_slow:
                self.frame_gaps.append(t0 - self._last_t0)
            self._last_t0 = t0
            # timelapse: an alarm (person seen, recording running, tracking) always has priority over the photo
            alarm = (self.writer is not None or STATE["persons"] > 0 or STATE["tracking"]
                     or (self.last_person_time > 0 and t0 - self.last_person_time < CFG["record_tail"] + 1.0))
            if not CFG["sim_on"]:                         # simulation: no timelapse photos, no continuous recording
                self.timelapse.update(frame, alarm)
            if LOOPREC is not None and not CFG["sim_on"]:
                LOOPREC.feed(frame, t0)                         # continuous recording: a copy now and then
            if t0 < self.raw_until:
                self.frame_raw = frame.copy()
            H, W = frame.shape[:2]
            pw = CFG["proc_width"]; ph = int(H * pw / W); sx = W / pw; sy = H / ph
            if (pw, ph) != getattr(self, "_proc_size", (pw, ph)):     # power mode / camera changed the working size
                self._reset_models()
            self._proc_size = (pw, ph)
            small = cv2.resize(frame, (pw, ph))
            if TAMPER is not None:
                TAMPER.feed(small, t0)
            if LENS is not None:
                LENS.feed(small, t0)
            nv_on = NIGHTVISION.active()
            STATE["nightvision"] = nv_on
            if CFG["thermal_on"] and THERMAL is not None and not nv_on:
                frame = THERMAL.overlay(frame)             # detection keeps using `small` (the normal picture)
            gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
            bright = float(gray.mean()); STATE["brightness"] = int(bright)
            lowlight = CFG["lowlight_auto"] and bright < CFG["lowlight_threshold"]
            if lowlight != STATE["lowlight"]:
                log_event("auto", f"Low-light mode {'ON' if lowlight else 'OFF'} (brightness {bright:.0f})")
                STATE["lowlight"] = lowlight
            if lowlight:
                gray = self.clahe.apply(cv2.medianBlur(gray, 5))   # denoise, then boost contrast so dark figures separate
            if lowlight and CFG["lowlight_view"] and bright > 1.5:
                # the picture you see: gamma curve that lifts the average brightness to ~115 (dark parts much more than bright ones)
                gm = max(0.3, min(1.0, math.log(115.0 / 255.0) / math.log(max(bright, 2.0) / 255.0)))
                gm = round(gm, 2)
                if getattr(self, "_lut_g", None) != gm:
                    self._lut_g = gm
                    self._lut = np.array([min(255, int(round(255.0 * (i / 255.0) ** gm))) for i in range(256)], np.uint8)
                frame = cv2.LUT(frame, self._lut)
                STATE["view_gain"] = gm
            else:
                STATE["view_gain"] = 1.0
            if nv_on:
                frame = NIGHTVISION.apply(frame)           # night vision look (the detection keeps using the normal picture)

            rain_score = self.weather.rain(gray) if CFG["rain_auto"] else 0.0
            rain_mode = (rain_score > CFG["rain_threshold"]) if CFG["rain_auto"] else CFG["rain_mode"]
            if rain_mode != STATE["rain_mode"]:
                log_event("rain", "Rain mode ON - filtering rain" if rain_mode else "Rain mode OFF")
            wind_boost = STATE["wind_boost"]

            persons, candidates, person_boxes = [], [], []
            present = set()                      # what is in view right now -> relay triggers
            if CFG["detection_on"]:
                g = self.preprocess(gray, rain_mode)
                fg = self.foreground(g, small, rain_mode, wind_boost)
                ai_boxes = [b for b in self.ai.detect(small) if zone_box_ok(b, pw, ph)]
                ai_objs = [o for o in self.ai.objects if zone_box_ok(o, pw, ph)]
                rec_animals = [o for o in ai_objs if COCO_LABELS.get(o[5]) in ANIMALS]
                objects = ai_objs if (CFG["show_objects"] and CFG["ai_enabled"]) else []
                counts = {}
                for o in objects:
                    nm = COCO_LABELS.get(o[5], "object"); counts[nm] = counts.get(nm, 0) + 1
                STATE["objects"] = len(objects)
                STATE["object_summary"] = ", ".join(f"{n} x{c}" for n, c in counts.items())
                min_area = CFG["min_area"] * (1.0 - CFG["sensitivity"] / 200.0) * wind_boost
                cnts, _ = cv2.findContours(fg, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
                # following movement also sees smaller things (a cat, a fox far away) - they never count as a person / alarm
                small_area = min(min_area, float(CFG["track_motion_min"]) / 100.0 * pw * ph) if CFG["track_motion"] else min_area
                boxes = [b for b in (cv2.boundingRect(c) for c in cnts if cv2.contourArea(c) >= small_area) if zone_box_ok(b, pw, ph)]
                if any(b[2] * b[3] >= min_area for b in boxes):
                    present.add("prealarm")              # pre-alarm: anything at all moves in the picture (before it is judged to be a person)
                boxes = merge_boxes(boxes + [b[:4] for b in ai_boxes])   # AI persons become tracks too
                tracks = self.tracker.update(boxes)
                for t in tracks:
                    if t.lost:
                        continue
                    self.classify(t, pw * ph, wind_boost, ai_boxes)
                    if t.is_person and not t.ai_confirmed and t.box[2] * t.box[3] < min_area * 0.8:
                        t.is_person = False                     # too small for a person (only seen for following movement)
                    if t.is_person:
                        persons.append(t); person_boxes.append(t.box)
                    else:
                        candidates.append(t)            # anything else that moves -> white
                try:
                    alarm_track_sample(persons, rec_animals, pw, ph)       # 2.95.53: for the Alarm-Rückblick in 3D
                except Exception:
                    pass
                if person_boxes or ai_boxes:
                    present.add("person")
                try:
                    self.zwatch.update(persons, pw, ph, frame, t0)
                except Exception as e:                     # never break the camera loop
                    log_event("sys", f"Zones: {e}"[:160])
                if persons or candidates:
                    present.add("motion")
                present.update(COCO_LABELS.get(o[5], "object") for o in ai_objs)
                if present & ANIMALS:
                    present.add("animal")
                species_update(ai_objs, frame, pw, ph, t0)
                if CFG["diary_on"] and not CFG["sim_on"]:  # animal diary + night report: best picture of every visit (not in the simulation)
                    for o in ai_objs:
                        lab = COCO_LABELS.get(o[5], "object")
                        if lab in ANIMALS:
                            sp = species_for(o[:4]) if CFG["species_on"] else None
                            self.sights.see(sp[0] if sp else lab, t0, frame, o, sp[1] if sp else o[4], pw, ph)
                    if "person" in present:
                        pb = person_boxes or [b[:4] for b in ai_boxes]
                        if pb:
                            self.sights.see("person", t0, frame, max(pb, key=lambda b: b[2] * b[3]), 0.9, pw, ph)
                self.tuner.observe(fg, tracks, persons, STATE["fps"])
                if CFG["wind_auto"]:
                    ws = self.weather.wind(fg, person_boxes)
                    STATE["wind_score"] = ws
                    boost = 1.0 + max(0.0, ws - CFG["wind_threshold"]) / (1 - CFG["wind_threshold"]) * (CFG["wind_boost_max"] - 1)
                    STATE["wind_boost"] = round(min(CFG["wind_boost_max"], boost), 2)
                    lvl = "calm" if ws < CFG["wind_threshold"] else ("breezy" if ws < 0.55 else ("strong" if ws < 0.8 else "storm"))
                    if lvl != STATE["wind_level"]:
                        log_event("wind", f"Wind: {lvl} (score {ws:.2f}, threshold x{STATE['wind_boost']})")
                    STATE["wind_level"] = lvl
                else:
                    STATE["wind_boost"] = 1.0; STATE["wind_score"] = 0.0; STATE["wind_level"] = "off"

                # servo tracking: follow the largest person
                # (paused while the camera is moved by hand: pad, arrow keys, web page)
                manual = manual_active()
                if CFG["track_person"] and person_boxes and not manual:
                    target = max(person_boxes, key=lambda b: b[2] * b[3])
                    self.track(target, pw, ph)
                    if not STATE["tracking"]:
                        log_event("servo", "Tracking person - patrol paused")
                    STATE["tracking"] = True
                elif CFG["track_motion"] and not manual and (mt_box := self.motion_target(candidates + persons, rec_animals, pw, ph, gray)) is not None:
                    if t0 - self.mt["moved"] > 0.4:                # move, let the picture settle a moment, look again
                        p0, q0 = CFG["pan"], CFG["tilt"]
                        self.track(mt_box, pw, ph, 1.0)
                        if (CFG["pan"], CFG["tilt"]) != (p0, q0):
                            self.mt["moved"] = t0
                    if not STATE["tracking"]:
                        log_event("servo", "Following movement (animal or something unknown) - patrol paused")
                    STATE["tracking"] = True; STATE["track_what"] = "motion"
                    mx_, my_, mw_, mh_ = [int(v) for v in (mt_box[0] * sx, mt_box[1] * sy, mt_box[2] * sx, mt_box[3] * sy)]
                    cv2.rectangle(frame, (mx_, my_), (mx_ + mw_, my_ + mh_), (0, 220, 255), 2)
                    cv2.putText(frame, "FOLLOW", (mx_, max(14, my_ - 5)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 220, 255), 1, cv2.LINE_AA)
                    cv2.drawMarker(frame, (W // 2, H // 2), (0, 220, 255), cv2.MARKER_CROSS, 24, 1)
                elif STATE["tracking"] and (manual or (time.time() - self.last_person_time > 2.0 and time.time() - self.mt["t"] > 3.0)):
                    was = STATE.get("track_what"); STATE["tracking"] = False; STATE["track_what"] = ""
                    log_event("servo", "Manual control - tracking paused" if manual else
                              ("Movement lost - patrol may resume" if was == "motion" else "Person lost - patrol may resume"))
                    self.mt["id"] = None
                if person_boxes:
                    STATE["track_what"] = "person" if STATE["tracking"] else ""

                # drawing
                if CFG["show_mask"]:                      # the picture stays as it is, movement gets a soft red tint
                    mk = cv2.resize(fg, (W, H), interpolation=cv2.INTER_NEAREST) > 0
                    if mk.any():
                        px = frame[mk].astype(np.uint16)
                        frame[mk] = ((px * 7 + np.array([40, 40, 255], np.uint16) * 3) // 10).astype(np.uint8)    # 30 % red
                for t in candidates:
                    x, y, w, h = [int(v) for v in (t.box[0] * sx, t.box[1] * sy, t.box[2] * sx, t.box[3] * sy)]
                    draw_outline(frame, cnts, t.box, sx, sy, (255, 255, 255), 1)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 255, 255), 1)
                    cv2.putText(frame, "vehicle" if t.is_vehicle else "motion", (x, max(14, y - 5)),
                                cv2.FONT_HERSHEY_SIMPLEX, 0.45, (255, 255, 255), 1, cv2.LINE_AA)
                for obj in objects:
                    draw_object(frame, obj, sx, sy)
                for t in persons:
                    x, y, w, h = [int(v) for v in (t.box[0] * sx, t.box[1] * sy, t.box[2] * sx, t.box[3] * sy)]
                    if CFG["highlight_red"]:
                        roi = frame[max(0, y):y + h, max(0, x):x + w]
                        msrc = fg[t.box[1]:t.box[1] + t.box[3], t.box[0]:t.box[0] + t.box[2]]
                        mroi = cv2.resize(msrc, (roi.shape[1], roi.shape[0])) if roi.size and msrc.size else None
                        if mroi is not None:
                            red = np.zeros_like(roi); red[:, :, 2] = 255
                            tint = cv2.addWeighted(roi, 0.45, red, 0.55, 0)
                            roi[mroi > 0] = tint[mroi > 0]
                    draw_outline(frame, cnts, t.box, sx, sy, (0, 0, 255), 2)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 0, 255), 3)
                    cv2.putText(frame, f"PERSON #{t.id}{' AI' if t.ai_confirmed else ''}  {t.speed():.1f}px/f",
                                (x, max(20, y - 8)), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 0, 255), 2)
                    if CFG["show_tracks"] and len(t.hist) > 1:
                        pts = np.array([(int(px * sx), int(py * sy)) for px, py in t.hist], np.int32)
                        cv2.polylines(frame, [pts], False, (0, 0, 255), 2)
                if person_boxes and CFG["track_person"]:
                    cv2.drawMarker(frame, (W // 2, H // 2), (0, 255, 255), cv2.MARKER_CROSS, 24, 1)
            else:
                STATE["objects"] = 0; STATE["object_summary"] = ""
                if STATE["tracking"]:
                    STATE["tracking"] = False; STATE["track_what"] = ""

            if CFG["show_zones"] and ZONES:
                for z in ZONES:
                    if z["mode"] == "privacy":
                        continue
                    pts = np.array([(int(px * W), int(py * H)) for px, py in z["points"]], np.int32)
                    col = {"ignore": (0, 160, 255), "line": (255, 210, 60), "loiter": (60, 220, 255)}.get(z["mode"], (80, 200, 80))
                    cv2.polylines(frame, [pts], z["mode"] != "line", col, 2 if z["mode"] == "line" else 1, cv2.LINE_AA)
                    if z["mode"] == "line" and z.get("dir", "both") != "both":
                        (ax, ay), (bx, by) = pts[0], pts[1]
                        mx, my = (ax + bx) / 2.0, (ay + by) / 2.0; nx, ny = -(by - ay), (bx - ax)
                        ln = math.hypot(nx, ny) or 1.0; sgn = 1 if z["dir"] == "ab" else -1
                        cv2.arrowedLine(frame, (int(mx), int(my)), (int(mx + sgn * nx / ln * 28), int(my + sgn * ny / ln * 28)), col, 2, cv2.LINE_AA, tipLength=0.4)
                    cv2.putText(frame, z["name"][:24].encode("ascii", "replace").decode(), (int(pts[0][0]) + 4, int(pts[0][1]) + 14),
                                cv2.FONT_HERSHEY_SIMPLEX, 0.42, col, 1, cv2.LINE_AA)
            warm_boxes = []
            if CFG["thermal_alarm"] and CFG["detection_on"] and THERMAL is not None:
                warm_boxes = THERMAL.detect()                 # (x, y, w, h) 0..1 of the picture, already checked against the zones
                if warm_boxes:
                    present.add("warm"); self.last_warm = t0
                    for bx, by, bw, bh in warm_boxes:
                        p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
                        cv2.rectangle(frame, p1, p2, (0, 140, 255), 3)
                        cv2.putText(frame, "WARM", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 140, 255), 2)
                    if not self.warm_alerted:
                        self.warm_alerted = True
                        push_alert("warm", "warm", count=len(warm_boxes), source=STATE["source_label"])
                        siren_alarm("warm")
                        if self.notifier.prealarm(frame, "warm"):
                            log_event("person", "Thermal alarm: warm body in the zone - push message sent")
                        else:
                            log_event("person", "Thermal alarm: warm body in the zone" + ("" if is_armed() else " (disarmed - no alarm)"))
                elif self.warm_alerted and t0 - self.last_warm > 5.0:
                    self.warm_alerted = False
            STATE["warm"] = len(warm_boxes)
            if AUDIO is not None and AUDIO.noisy():
                present.add("noise")                      # relay trigger: loud noise at the microphone
            if CFG["diary_on"]:
                for lab in ("warm", "noise"):
                    if lab in present:
                        self.sights.see(lab, t0)
            self.sights.tick(t0)
            if is_armed() and present & {"person", "warm", "noise"}:
                light_alarm()                             # lights in "Auto" (after an alarm) switch on
            frame = apply_privacy(frame)                  # again after the overlays (thermal picture, boxes)
            if rec_clean is not None:                     # recordings / alarm pictures without the big red boxes (faces stay visible)
                if CFG["rec_marks"] == "thin":
                    for b_, col in [(b, (0, 0, 255)) for b in person_boxes] + [(o, (0, 200, 255)) for o in rec_animals]:
                        corner_marks(rec_clean, [int(b_[0] * sx), int(b_[1] * sy), int(b_[2] * sx), int(b_[3] * sy)], col)
                self.handle_recording(rec_clean, person_boxes)
            else:
                self.handle_recording(frame, person_boxes)
            self.relays.update(present)
            STATE["present"] = sorted(present); STATE["manual"] = manual_active()
            if "prealarm" in present:
                self.pre_last = t0
                if not self.pre_since:
                    self.pre_since = t0
                elif t0 - self.pre_since >= 0.5:
                    if not self.pre_alerted:                # one browser alarm per movement phase (5 s of calm ends it)
                        self.pre_alerted = True
                        push_alert("prealarm", "movement", source=STATE["source_label"])
                        siren_alarm("prealarm")
                    if CFG["notify_prealarm"] and self.notifier.prealarm(frame):
                        log_event("person", "Pre-alarm: movement - push message sent")
            else:
                self.pre_since = 0.0
                if self.pre_alerted and t0 - self.pre_last > 5.0:
                    self.pre_alerted = False

            if CFG["show_hud"]:
                hud = (f"{'RAIN MODE' if rain_mode else 'No rain'} | Wind: {STATE['wind_level']} x{STATE['wind_boost']} | "
                       f"Persons: {len(person_boxes)} | Pan {CFG['pan']:.0f}% Tilt {CFG['tilt']:.0f}% | {STATE['patrol_status']}"
                       + (f" | CPU {STATE['cpu']:.0f}%" if STATE["cpu"] is not None else "")
                       + (f" {STATE['cpu_temp']:.0f}C" if STATE["cpu"] is not None and STATE["cpu_temp"] is not None else "")
                       + (" | MANUAL" if STATE["manual"] else "")
                       + (" | IR" if CFG["thermal_on"] and STATE["thermal"] == "connected" else "")
                       + (f" | WiFi {STATE['wifi']['dbm']}dBm" if STATE["wifi"] and STATE["wifi"]["connected"] else "")
                       + (" | TIMELAPSE" if TL_HOLD["on"] else ""))
                cv2.rectangle(frame, (0, 0), (W, 34), (0, 0, 0), -1)
                cv2.putText(frame, hud, (10, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (80, 160, 255) if rain_mode else (230, 230, 230), 2)
                if STATE["recording"]:
                    cv2.circle(frame, (W - 24, 17), 8, (0, 0, 255), -1)

            self.frame_times.append(time.time() - t0)
            self.seen_t.append(t0)
            # 2.95.64: «fps» is the real number of pictures per second that are analysed (camera, simulator, power saving).
            # Before it was 1 / processing time - far too high with a slow source (simulator: 100 instead of 2.5), and the
            # auto-tuner then asked for up to 24 pictures of walking before a person counted: at low frame rates nobody did.
            span = self.seen_t[-1] - self.seen_t[0] if len(self.seen_t) >= 5 else 0.0
            proc_fps = 1.0 / max(1e-3, np.mean(self.frame_times))
            real_fps = (len(self.seen_t) - 1) / span if span > 0.2 else proc_fps
            with LOCK:
                STATE.update(rain_score=round(rain_score, 2), rain_mode=rain_mode, persons=len(person_boxes),
                             candidates=len(candidates), fps=round(min(real_fps, proc_fps), 1), proc_fps=round(proc_fps, 1),
                             frames=STATE["frames"] + 1, uptime=int(time.time() - START))
            frame = apply_privacy(frame)
            self.frame_out = frame
            DETER.check(present, t0)
            self._eco(present, t0)
            if CFG["web_stream"] and self.web_viewers > 0:
                out, ww = frame, int(CFG["web_width"])
                if W > ww:
                    out = cv2.resize(frame, (ww, int(H * ww / W)), interpolation=cv2.INTER_AREA)
                ok, buf = cv2.imencode(".jpg", out, [cv2.IMWRITE_JPEG_QUALITY, int(CFG["web_quality"])])
                if ok:
                    self.jpeg = buf.tobytes(); self.jpeg_seq += 1


# ----------------------------------------------------------------------------
# Web access options (set on the command line) + self-signed certificate + systemd unit
# ----------------------------------------------------------------------------
WEB_OPTS = {"bind": "0.0.0.0", "https": False, "cert": "", "key": ""}


def ensure_cert():
    """Use the given certificate, or create (once) a self-signed one next to the script. Returns (cert, key) or (None, None)."""
    if WEB_OPTS["cert"] and WEB_OPTS["key"]:
        return WEB_OPTS["cert"], WEB_OPTS["key"]
    cert, key = os.path.join(DATA_DIR, "motionwatch_cert.pem"), os.path.join(DATA_DIR, "motionwatch_key.pem")
    if os.path.isfile(cert) and os.path.isfile(key):
        return cert, key
    if shutil.which("openssl") is None:
        return None, None
    import socket
    host = socket.gethostname()
    for san in (f"subjectAltName=DNS:localhost,DNS:{host},DNS:{host}.local,IP:127.0.0.1", None):
        cmd = ["openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes", "-keyout", key, "-out", cert, "-days", "3650", "-subj", f"/CN={host}"]
        if san:
            cmd += ["-addext", san]
        try:
            if subprocess.run(cmd, capture_output=True, timeout=60).returncode == 0:
                os.chmod(key, 0o600)
                log_event("web", "Self-signed certificate created (browsers will show a warning once; import the .pem to remove it)")
                return cert, key
        except (OSError, subprocess.SubprocessError):
            pass
    return None, None


def service_text():
    import shlex
    args = [a for a in sys.argv[1:] if a not in ("--print-service", "--install-service")]
    if "--headless" not in args:
        args.append("--headless")
    user = os.environ.get("SUDO_USER") or os.environ.get("USER") or "pi"
    exe = " ".join(shlex.quote(x) for x in [sys.executable, os.path.abspath(__file__)] + args)
    return f"""[Unit]
Description=Motion Watch (camera motion / person detection)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User={user}
WorkingDirectory={HERE}
ExecStart={exe}
Restart=always
RestartSec=5
Environment=PYTHONUNBUFFERED=1

[Install]
WantedBy=multi-user.target
"""


def install_service():
    path = "/etc/systemd/system/motionwatch.service"
    if not hasattr(os, "geteuid") or os.geteuid() != 0:
        print("Installing a system service needs root. Run the same command again with sudo, e.g.:\n"
              f"   sudo {sys.executable} {os.path.abspath(__file__)} --install-service {' '.join(a for a in sys.argv[1:] if a != '--install-service')}\n"
              "or print the unit file with --print-service and install it yourself."); return 1
    with open(path, "w") as f:
        f.write(service_text())
    for cmd in (["systemctl", "daemon-reload"], ["systemctl", "enable", "--now", "motionwatch.service"]):
        print("$", " ".join(cmd)); subprocess.run(cmd)
    print(f"Service installed ({path}). Status: systemctl status motionwatch   Log: journalctl -u motionwatch -f")
    return 0


# ----------------------------------------------------------------------------
# Recordings backend (used by the preview page /recordings)
#   person_YYYYmmdd_HHMMSS.mp4   video          person_YYYYmmdd_HHMMSS.jpg   snapshot of the same event
#   person_YYYYmmdd_HHMMSS.json  info file (source, schedules, duration, codec) written when a recording ends
#   snapshot_*.jpg               manual snapshots
# Thumbnails are cached in recordings/.thumbs, browser-playable copies in recordings/.cache
# ----------------------------------------------------------------------------
REC_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.\-]{0,120}$")
REC_EXTS = {".mp4": "video", ".jpg": "image"}
_STAMP_RE = re.compile(r"(\d{8})_(\d{6})")
BROWSER_CODECS = {"avc1", "h264", "x264"}                   # what <video> can play everywhere (MPEG-4 part 2 "mp4v" cannot)
class _ExpiringSet(dict):
    """«x in s» is true for 10 minutes after s.add(x) (2.95.33: a removed USB disk must not disable the encoders for good)"""
    def add(self, k):
        self[k] = time.time()

    def __contains__(self, k):
        t = self.get(k)
        return t is not None and time.time() - t < 600


_BAD_CODECS = _ExpiringSet()                                # encoders that failed lately (avc1 is missing in many OpenCV builds)
_REC_META = {}                                              # name -> [mtime, size, meta, probed]
_TRANSCODE = {}                                             # name -> "running" | "done" | "error: ..."
_TRANSCODE_LOCK = threading.Lock()
_TRANSCODE_SEM = threading.Semaphore(1)                     # one conversion at a time, the detection must keep running


# ---- encoder: ffmpeg pipe (hardware H.264 on Pi 3/4, x264 elsewhere) ------------------------------------------
_ENC = {"hw": None}


def _ffmpeg_hw_ok():
    if _ENC["hw"] is None:
        try:
            r = subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x240:rate=10",
                                "-frames:v", "5", "-c:v", "h264_v4l2m2m", "-pix_fmt", "yuv420p", "-f", "null", "-"],
                               capture_output=True, timeout=20)
            _ENC["hw"] = r.returncode == 0
        except Exception:
            _ENC["hw"] = False
    return _ENC["hw"]


class FfmpegWriter:
    """Looks like cv2.VideoWriter, but pipes the frames into ffmpeg from a background thread, so the detection never waits
    for the encoder. Fragmented MP4: a recording survives a power loss up to the last few seconds."""
    def __init__(self, path, fps, size, hw):
        w, h = size
        enc = ["-c:v", "h264_v4l2m2m", "-b:v", "4M"] if hw else ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "25"]
        cmd = ["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", f"{w}x{h}", "-framerate", f"{fps:.2f}",
               "-i", "-", "-an", "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p"] + enc + \
              ["-movflags", "+frag_keyframe+empty_moov+default_base_moof", path]
        if shutil.which("nice"):
            cmd = ["nice", "-n", "5"] + cmd
        self.size = (w, h); self.failed = False; self.dropped = 0; self.hw = hw; self.t_open = time.time()
        self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self.q = queue.Queue(maxsize=max(4, min(60, int(150e6 / max(1, w * h * 3)))))   # 2.95.33: at most ~150 MB of frames
        self.th = threading.Thread(target=self._pump, daemon=True); self.th.start()

    def _pump(self):
        while True:
            item = self.q.get()
            if item is None:
                break
            try:
                self.proc.stdin.write(item)
            except (BrokenPipeError, OSError, ValueError):
                self.failed = True
                break
        try:
            self.proc.stdin.close()
        except Exception:
            pass

    def isOpened(self):
        return self.proc.poll() is None and not self.failed

    def write(self, frame):
        if self.failed or self.proc.poll() is not None:
            self.failed = True; return
        try:
            self.q.put_nowait(frame.tobytes())
        except queue.Full:
            self.dropped += 1                                   # encoder too slow: drop a frame instead of stalling the detection

    def release(self):
        try:
            self.q.put(None, timeout=5)
        except queue.Full:
            self.proc.kill()
        self.th.join(30)
        try:
            self.proc.wait(timeout=30)
        except subprocess.TimeoutExpired:
            self.proc.kill()


def open_writer(path, fps, size):
    """Open a video writer. H.264 plays in every browser. Order: ffmpeg (hardware, then x264) -> OpenCV 'avc1' -> OpenCV 'mp4v'
    (mp4v is the last resort; the preview page converts such files on first play). Returns (writer or None, codec)."""
    d_ = os.path.dirname(os.path.abspath(path))
    try:
        os.makedirs(d_, exist_ok=True)
    except OSError:
        pass
    if not os.access(d_, os.W_OK):
        return None, ""                                       # the folder (USB disk?) is missing / read-only: not the encoders' fault
    if CFG["record_encoder"] == "auto" and "ffmpeg" not in _BAD_CODECS and shutil.which("ffmpeg"):
        for hw in ((True, False) if _ffmpeg_hw_ok() else (False,)):
            if hw and ("ffmpeg_hw" in _BAD_CODECS or size[0] > 1920 or size[1] > 1088):
                continue                                      # the Pi hardware encoder: max 1920x1088, or it died lately
            try:
                w = FfmpegWriter(path, fps, size, hw)
                time.sleep(0.2)
                if w.isOpened():
                    STATE["recording_enc"] = "ffmpeg h264_v4l2m2m (hardware)" if hw else "ffmpeg x264"
                    return w, "h264"
                w.release()
            except Exception:
                pass
            try:
                os.remove(path)
            except OSError:
                pass
        _BAD_CODECS.add("ffmpeg")
    for cc in ("avc1", "mp4v"):
        if cc in _BAD_CODECS:
            continue
        try:
            w = cv2.VideoWriter(path, cv2.VideoWriter_fourcc(*cc), fps, size)
        except Exception:
            w = None
        if w is not None and w.isOpened():
            STATE["recording_enc"] = "OpenCV " + cc
            return w, cc
        _BAD_CODECS.add(cc)
        if w is not None:
            w.release()
        try:
            os.remove(path)
        except OSError:
            pass
    return None, ""


# ---- storage: SD card / SSD / USB drive -------------------------------------------------------------------------------
STORE = {"fallback": False, "moving": False, "msg": ""}
_FS_OK = {"ext4", "ext3", "ext2", "btrfs", "xfs", "f2fs", "vfat", "exfat", "ntfs", "ntfs3", "fuseblk"}


def _mounts():
    out = []
    try:
        with open("/proc/mounts") as f:
            for line in f:
                p = line.split()
                if len(p) >= 3:
                    out.append((p[0], p[1].replace("\\040", " "), p[2]))
    except OSError:
        pass
    return out


def _dev_kind(dev):
    d = os.path.basename(dev or "")
    if d.startswith("mmcblk"):
        return "sd"
    if d.startswith("nvme"):
        return "ssd"
    if d.startswith("sd"):
        return "usb"
    return "other"


def _mount_of(path):
    """(device, mount point, fs type) that holds this path."""
    path = os.path.realpath(path); best = ("", "/", "")
    for dev, mp, fs in _mounts():
        if (path == mp or path.startswith(mp.rstrip("/") + "/")) and len(mp) >= len(best[1]):
            best = (dev, mp, fs)
    return best


def storage_candidates():
    """Drives the recordings can be put on: SSD / USB mounted somewhere else than the system."""
    root_dev = _mount_of("/")[0]
    out = []
    for dev, mp, fs in _mounts():
        if fs not in _FS_OK or not dev.startswith("/dev/") or mp in ("/", "/boot", "/boot/firmware") or dev == root_dev:
            continue
        if not (mp.startswith(("/media/", "/mnt/", "/srv/")) or _dev_kind(dev) in ("ssd", "usb")):
            continue
        try:
            du = shutil.disk_usage(mp)
        except OSError:
            continue
        out.append({"path": mp, "kind": _dev_kind(dev), "fs": fs, "free_gb": round(du.free / 1024 ** 3, 1),
                    "total_gb": round(du.total / 1024 ** 3, 1), "writable": os.access(mp, os.W_OK), "fat": fs == "vfat"})
    return out


def storage_info():
    sysdev, _mp, _fs = _mount_of("/")
    rdev, rmp, rfs = _mount_of(rec_dir() if os.path.isdir(rec_dir()) else os.path.dirname(rec_dir()) or "/")
    return {"system": _dev_kind(sysdev), "rec": _dev_kind(rdev), "rec_mount": rmp, "rec_fs": rfs, "rec_dir": rec_dir(),
            "want": CFG["storage_path"], "fallback": STORE["fallback"], "moving": STORE["moving"], "msg": STORE["msg"],
            "candidates": storage_candidates()}


def storage_apply(start=False):
    """Set the recordings folder from the chosen drive. Missing drive: the memory card next to the program."""
    want = CFG["storage_path"].strip()
    if not want:
        CFG["record_dir"] = "recordings"; STORE["fallback"] = False; return True
    target = os.path.join(want, "MotionWatch", "recordings")
    ok = os.path.ismount(want) or os.path.isdir(want)
    if ok and want.startswith(("/media/", "/mnt/")):           # 2.95.34: the folder of an unplugged drive is the SD card
        q = os.path.abspath(want)
        while q not in ("/", "/media", "/mnt") and not os.path.ismount(q):
            q = os.path.dirname(q)
        ok = q not in ("/", "/media", "/mnt")
    if ok:
        try:
            os.makedirs(target, exist_ok=True)
            probe = os.path.join(target, ".mw_probe")
            with open(probe, "w") as f:
                f.write("ok")
            os.remove(probe)
        except OSError:
            ok = False
    if ok:
        CFG["record_dir"] = target; STORE["fallback"] = False
        return True
    CFG["record_dir"] = "recordings"; STORE["fallback"] = True
    log_event("sys", f"Storage: drive {want} not found or not writable - recordings go to the memory card for now")
    return False


def storage_set(path, move=True):
    """Choose where the recordings go ('' = memory card). Moves the existing recordings in the background."""
    path = str(path or "").strip()
    if path and not any(c["path"] == path for c in storage_candidates()):
        return False, "drive not found"
    if STORE["moving"]:
        return False, "already moving recordings - wait a moment"
    old = rec_dir()
    CFG["storage_path"] = path
    if not storage_apply():
        CFG["storage_path"] = ""; storage_apply()
        return False, "the drive cannot be written to"
    save_settings()
    new = rec_dir()
    log_event("sys", f"Storage: recordings now in {new}")
    if move and os.path.isdir(old) and os.path.realpath(old) != os.path.realpath(new):
        def run():
            STORE.update(moving=True, msg="moving recordings …"); n = 0
            try:
                for nm in os.listdir(old):
                    src, dst = os.path.join(old, nm), os.path.join(new, nm)
                    if nm.startswith(".") or os.path.exists(dst) or _is_live(nm, WATCH_REF.get("w")) or (nm == "loop" and LOOPREC is not None and LOOPREC.cur):
                        continue
                    try:
                        shutil.move(src, dst); n += 1
                    except (OSError, shutil.Error):
                        pass
                STORE["msg"] = f"{n} files moved"
                log_event("sys", f"Storage: {n} files moved to {new}")
            finally:
                STORE["moving"] = False
        threading.Thread(target=run, daemon=True, name="storage-move").start()
    return True, ""


LOOP_RE = re.compile(r"^loop/(\d{4}-\d{2}-\d{2})/(\d{2})-(\d{2})\.mp4$")


def loop_dir():
    return os.path.join(rec_dir(), "loop")


class LoopRecorder:
    """Continuous recording: every picture-per-second interval one picture into 10-minute files loop/<day>/<HH-MM>.mp4,
    kept for loop_hours. Runs in its own thread (the camera loop only hands over a copy now and then)."""
    SEG = 600

    def __init__(self):
        self.q = queue.Queue(maxsize=8); self.next_t = 0.0; self.wr = None; self.cur = ""; self.seg_end = 0.0
        self.size = None; self.last_clean = 0.0
        threading.Thread(target=self.loop, daemon=True, name="looprec").start()

    def feed(self, frame, t0):
        if not CFG["loop_on"] or frame is None or t0 < self.next_t:
            return
        self.next_t = t0 + 1.0 / max(1, int(CFG["loop_fps"]))
        try:
            self.q.put_nowait((frame.copy(), time.time()))
        except queue.Full:
            pass

    def _close(self):
        if self.wr is not None:
            try:
                self.wr.release()
            except Exception:
                pass
            LIVE_RECS.discard(self.cur)
        self.wr = None; self.cur = ""

    def loop(self):
        while True:
            try:
                self._step()
            except Exception as e:                         # 2.95.33: e.g. the USB disk was removed - try again later
                log_event("rec", f"Continuous recording: {type(e).__name__}: {e}"[:200])
                try:
                    self._close()
                except Exception:
                    self.wr = None
                time.sleep(30)

    def _step(self):
        beat("looprec", 120, "Continuous recording")
        if True:
            try:
                frame, t = self.q.get(timeout=5)
            except queue.Empty:
                if not CFG["loop_on"]:
                    self._close()
                self._clean()
                return
            if not CFG["loop_on"]:
                self._close(); return
            h, w = frame.shape[:2]
            if w > 1280:
                frame = cv2.resize(frame, (1280, int(h * 1280 / w))); h, w = frame.shape[:2]
            if self.wr is None or t >= self.seg_end or self.size != (w, h):
                self._close()
                dt = datetime.fromtimestamp(t)
                start = dt.replace(minute=dt.minute - dt.minute % 10, second=0, microsecond=0)
                self.seg_end = start.timestamp() + self.SEG
                name = f"loop/{start:%Y-%m-%d}/{start:%H-%M}.mp4"
                path = os.path.join(rec_dir(), name)
                os.makedirs(os.path.dirname(path), exist_ok=True)
                k_ = 1
                while os.path.exists(path):                       # restarted / clock change: a new piece, never overwrite
                    name = f"loop/{start:%Y-%m-%d}/{start:%H-%M}_{k_}.mp4"; path = os.path.join(rec_dir(), name); k_ += 1
                wr, _codec = open_writer(path, max(1, int(CFG["loop_fps"])), (w, h))
                if wr is None:
                    time.sleep(10); return
                self.wr, self.cur, self.size = wr, name, (w, h); LIVE_RECS.add(name)
            try:
                self.wr.write(frame)
            except Exception:
                self._close()
            self._clean()

    def _clean(self):
        now = time.time()
        if now - self.last_clean < 60:
            return
        self.last_clean = now
        keep = float(CFG["loop_hours"]) * 3600
        base = loop_dir()
        try:
            days = sorted(os.listdir(base))
        except OSError:
            return
        for d in days:
            dp = os.path.join(base, d)
            try:
                for n in os.listdir(dp):
                    p = os.path.join(dp, n)
                    if f"loop/{d}/{n}" != self.cur and now - os.path.getmtime(p) > keep:
                        os.remove(p)
                if not os.listdir(dp) and not self.cur.startswith(f"loop/{d}/"):
                    os.rmdir(dp)
            except OSError:
                pass
        try:                                                      # memory almost full: the oldest pieces go first
            while shutil.disk_usage(base).free < 1024 ** 3:
                files = sorted(glob.glob(os.path.join(base, "*", "*.mp4")))
                files = [f for f in files if not f.endswith(self.cur.split("/", 1)[-1])]
                if not files:
                    break
                os.remove(files[0])
        except OSError:
            pass


LOOPREC = None


def loop_day(day):
    """Pieces of one day and the alarm recordings of that day (for the timeline)."""
    out = {"day": day, "segments": [], "events": [], "days": []}
    try:
        out["days"] = sorted(os.listdir(loop_dir()), reverse=True)[:60]
    except OSError:
        pass
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", day or ""):
        return out
    dp = os.path.join(loop_dir(), day)
    try:
        names = sorted(os.listdir(dp))
    except OSError:
        names = []
    for n in names:
        m = re.fullmatch(r"(\d{2})-(\d{2})\.mp4", n)
        if not m:
            continue
        try:
            st = os.stat(os.path.join(dp, n))
        except OSError:
            continue
        name = f"loop/{day}/{n}"
        out["segments"].append({"name": name, "start": f"{m.group(1)}:{m.group(2)}", "size": st.st_size, "live": name in LIVE_RECS,
                                "min": int(m.group(1)) * 60 + int(m.group(2))})
    stamp = day.replace("-", "")
    try:
        for n in os.listdir(rec_dir()):
            if stamp in n and n.endswith((".mp4", ".jpg")):
                dt = parse_stamp(n)
                if dt is not None and dt.strftime("%Y-%m-%d") == day:
                    out["events"].append(dt.hour * 60 + dt.minute)
    except OSError:
        pass
    out["events"] = sorted(set(out["events"]))
    return out


# ---- picture for other programs: MJPEG + still picture under a secret address, optional RTSP (mediamtx + ffmpeg) ----
EXT = {"proc": None, "ff": None, "msg": "", "port": None}


def ext_token():
    if not re.fullmatch(r"[A-Za-z0-9_-]{20,64}", CFG["ext_token"] or ""):
        CFG["ext_token"] = secrets.token_urlsafe(18); save_settings()
    return CFG["ext_token"]


def ext_new_token():
    CFG["ext_token"] = secrets.token_urlsafe(18); save_settings(); rtsp_restart()
    log_event("web", "Address for other programs renewed - the old one no longer works")


def ext_links(host=None):
    if not CFG["ext_on"]:
        return {"on": False}
    base = page_address(host).rstrip("/") if host or page_address() else f"http://<pi-ip>:{CFG['web_port']}"
    tok = ext_token()
    out = {"on": True, "mjpeg": f"{base}/x/{tok}/video.mjpg", "jpg": f"{base}/x/{tok}/snapshot.jpg", "rtsp": "", "rtsp_msg": EXT["msg"]}
    if CFG["rtsp_on"]:
        h = base.split("://", 1)[-1].split("/", 1)[0].rsplit(":", 1)[0]
        out["rtsp"] = f"rtsp://motionwatch:{tok}@{h}:{int(CFG['rtsp_port'])}/motionwatch"
    return out


def _mediamtx_bin():
    for p in (shutil.which("mediamtx"), os.path.join(DATA_DIR, "mediamtx", "mediamtx"), os.path.expanduser("~/mediamtx/mediamtx"), "/usr/local/bin/mediamtx"):
        if p and os.path.isfile(p) and os.access(p, os.X_OK):
            return p
    return None


def rtsp_stop():
    for k in ("ff", "proc"):
        p = EXT.get(k)
        if p is not None:
            try:
                p.terminate(); p.wait(timeout=5)
            except Exception:
                try:
                    p.kill()
                except Exception:
                    pass
        EXT[k] = None


def rtsp_restart():
    rtsp_stop()
    if CFG["rtsp_on"] and CFG["ext_on"]:
        threading.Thread(target=rtsp_start, daemon=True, name="rtsp").start()


def rtsp_start():
    """mediamtx serves RTSP (reading needs the secret, publishing only from this Pi); ffmpeg turns the MJPEG into H.264."""
    mtx = _mediamtx_bin()
    if not mtx:
        EXT["msg"] = "mediamtx is not installed (see the manual: RTSP)"; return
    if not shutil.which("ffmpeg"):
        EXT["msg"] = "ffmpeg is missing (sudo apt install ffmpeg)"; return
    tok = ext_token(); port = int(CFG["rtsp_port"])
    cfg_dir = os.path.join(DATA_DIR, "mediamtx"); os.makedirs(cfg_dir, exist_ok=True)
    yml = os.path.join(cfg_dir, "motionwatch.yml")
    with open(yml, "w") as f:
        f.write("logLevel: warn\nrtspAddress: :%d\nrtmp: no\nhls: no\nwebrtc: no\nsrt: no\napi: no\nmetrics: no\npprof: no\nplayback: no\n"
                "authInternalUsers:\n- user: any\n  pass:\n  ips: ['127.0.0.1/32', '::1/128']\n  permissions:\n  - action: publish\n"
                "- user: motionwatch\n  pass: %s\n  ips: []\n  permissions:\n  - action: read\n    path: motionwatch\n"
                "paths:\n  motionwatch:\n" % (port, tok))
    os.chmod(yml, 0o600)
    try:
        EXT["proc"] = subprocess.Popen([mtx, yml], stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, cwd=cfg_dir)
    except OSError as e:
        EXT["msg"] = f"mediamtx: {e}"[:120]; return
    time.sleep(2)
    if EXT["proc"].poll() is not None:
        err = (EXT["proc"].stderr.read() or b"").decode(errors="replace").strip().splitlines()
        EXT["msg"] = ("mediamtx: " + (err[-1] if err else "stopped"))[:160]; EXT["proc"] = None; return
    src = f"http://127.0.0.1:{CFG['web_port']}/x/{tok}/video.mjpg"
    if WEB_OPTS.get("https"):
        src = src.replace("http://", "https://")
    cmd = ["ffmpeg", "-loglevel", "error", "-tls_verify", "0", "-f", "mjpeg", "-i", src, "-an", "-c:v", "libx264", "-preset", "ultrafast",
           "-tune", "zerolatency", "-g", "30", "-pix_fmt", "yuv420p", "-f", "rtsp", "-rtsp_transport", "tcp", f"rtsp://127.0.0.1:{port}/motionwatch"]
    if not WEB_OPTS.get("https"):
        cmd.remove("-tls_verify"); cmd.remove("0")
    try:
        EXT["ff"] = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        EXT["msg"] = "running"
        log_event("web", f"RTSP video on port {port} (for recorders)")
    except OSError as e:
        EXT["msg"] = f"ffmpeg: {e}"[:120]


def rtsp_watch():
    """Keeps RTSP running while it is switched on (restarts ffmpeg / mediamtx when they stop)."""
    while True:
        time.sleep(15)
        want = CFG["rtsp_on"] and CFG["ext_on"]
        alive = EXT["proc"] is not None and EXT["proc"].poll() is None and EXT["ff"] is not None and EXT["ff"].poll() is None
        if want and not alive:
            rtsp_restart()
        elif not want and (EXT["proc"] or EXT["ff"]):
            rtsp_stop(); EXT["msg"] = ""


atexit.register(rtsp_stop)


def mem_info():
    """RAM of the Pi from /proc/meminfo (MB): total, used (without cache), percent; swap used."""
    m = {}
    try:
        with open("/proc/meminfo") as f:
            for line in f:
                k, v = line.split(":", 1); m[k] = int(v.split()[0]) // 1024
    except (OSError, ValueError):
        return None
    tot = m.get("MemTotal") or 0; avail = m.get("MemAvailable", m.get("MemFree", 0))
    if not tot:
        return None
    return {"total": tot, "used": tot - avail, "pct": round((tot - avail) * 100.0 / tot, 1), "swap": (m.get("SwapTotal", 0) - m.get("SwapFree", 0))}


def rec_dir():
    return os.path.abspath(CFG["record_dir"])


# ----------------------------------------------------------------------------
# Event report (PDF) - a small PDF writer of its own (no extra package): A4 pages, text in Helvetica (WinAnsi, so umlauts
#   work), JPEG pictures embedded as they are.
# ----------------------------------------------------------------------------
class MiniPDF:
    W, H = 595.0, 842.0

    def __init__(self):
        self.pages = []; self.images = []; self.cur = None; self.y = 0.0; self.new_page()

    def new_page(self):
        self.cur = []; self.pages.append(self.cur); self.y = self.H - 50

    @staticmethod
    def _esc(t):
        b = str(t).encode("cp1252", "replace")
        return b.replace(b"\\", b"\\\\").replace(b"(", b"\\(").replace(b")", b"\\)")

    def text(self, t, size=10, bold=False, x=50, gap=1.35, color=(0, 0, 0)):
        width = int((self.W - x - 50) / (size * 0.5))           # rough line length for Helvetica
        lines = []
        for para in str(t).split("\n"):
            while len(para) > width:
                cut = para.rfind(" ", 0, width)
                cut = cut if cut > width // 2 else width
                lines.append(para[:cut]); para = para[cut:].lstrip()
            lines.append(para)
        for ln in lines:
            if self.y < 60:
                self.new_page()
            self.cur.append(b"BT %.3f %.3f %.3f rg /%s %d Tf %.1f %.1f Td (" % (color[0], color[1], color[2], b"F2" if bold else b"F1", size, x, self.y)
                            + self._esc(ln) + b") Tj ET")
            self.y -= size * gap

    def space(self, h=8):
        self.y -= h

    def line(self):
        self.cur.append(b"0.75 0.75 0.75 RG 0.6 w 50 %.1f m %.1f %.1f l S" % (self.y + 4, self.W - 50, self.y + 4)); self.y -= 8

    def image(self, jpg, w, h, max_w=495.0, max_h=250.0, caption=""):
        k = min(max_w / w, max_h / h, 1.0 if w > max_w else max_w / w)
        dw, dh = w * k, h * k
        if self.y - dh - (14 if caption else 0) < 50:
            self.new_page()
        if caption:
            self.text(caption, 9, color=(0.35, 0.35, 0.35))
        self.images.append((jpg, w, h)); n = len(self.images)
        self.cur.append(b"q %.1f 0 0 %.1f 50 %.1f cm /Im%d Do Q" % (dw, dh, self.y - dh, n))
        self.y -= dh + 10

    def output(self):
        objs = []                                              # (number, bytes)
        def add(b):
            objs.append(b); return len(objs)
        cat = add(b""); pages_n = add(b"")
        f1 = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
        f2 = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")
        imgs = []
        for jpg, w, h in self.images:
            imgs.append(add(b"<< /Type /XObject /Subtype /Image /Width %d /Height %d /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length %d >>\nstream\n" % (w, h, len(jpg))
                            + jpg + b"\nendstream"))
        xo = b" ".join(b"/Im%d %d 0 R" % (i + 1, o) for i, o in enumerate(imgs))
        res = b"<< /Font << /F1 %d 0 R /F2 %d 0 R >> /XObject << %s >> >>" % (f1, f2, xo)
        kids = []
        for i, pg in enumerate(self.pages):
            foot = b"BT 0.5 0.5 0.5 rg /F1 8 Tf 50 30 Td (Motion Watch - %d / %d) Tj ET" % (i + 1, len(self.pages))
            body = b"\n".join(pg + [foot])
            c = add(b"<< /Length %d >>\nstream\n" % len(body) + body + b"\nendstream")
            kids.append(add(b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 595 842] /Resources %s /Contents %d 0 R >>" % (pages_n, res, c)))
        objs[cat - 1] = b"<< /Type /Catalog /Pages %d 0 R >>" % pages_n
        objs[pages_n - 1] = b"<< /Type /Pages /Kids [%s] /Count %d >>" % (b" ".join(b"%d 0 R" % k for k in kids), len(kids))
        out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"); offs = []
        for i, o in enumerate(objs):
            offs.append(len(out)); out += b"%d 0 obj\n" % (i + 1) + o + b"\nendobj\n"
        xref = len(out)
        out += b"xref\n0 %d\n0000000000 65535 f \n" % (len(objs) + 1) + b"".join(b"%010d 00000 n \n" % x for x in offs)
        out += b"trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs) + 1, cat, xref)
        return bytes(out)


def _report_jpg(img, width=900):
    h, w = img.shape[:2]
    if w > width:
        img = cv2.resize(img, (width, int(h * width / w)), interpolation=cv2.INTER_AREA)
    ok, buf = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 82])
    return (buf.tobytes(), img.shape[1], img.shape[0]) if ok else None


def _report_log(dt, minutes=10):
    """Log lines from minutes before to minutes after the event (today's log and the packed day logs)."""
    import gzip
    a, b = dt - timedelta(minutes=minutes), dt + timedelta(minutes=minutes)
    day = dt.strftime("%Y-%m-%d"); out = []
    files = [LOG_FILE] + sorted(glob.glob(os.path.join(log_dir(), f"motionwatch_{day}*.log.gz")))
    for p in files:
        try:
            op = gzip.open if p.endswith(".gz") else open
            with op(p, "rt", errors="replace") as f:
                for ln in f:
                    try:
                        t = datetime.strptime(ln[:19], "%Y-%m-%d %H:%M:%S")
                    except ValueError:
                        continue
                    if a <= t <= b:
                        out.append(ln.rstrip())
        except OSError:
            continue
    return sorted(set(out))[:120]


def rec_report_pdf(name, lang=None):
    """PDF with what is known about one recording: for the police / the insurance."""
    T = lambda x: tr(x, lang)
    p = rec_path(name)
    if not p:
        return None
    st = os.stat(p); is_video = name.lower().endswith(".mp4")
    meta = rec_meta(name, st, probe=True) if not name.startswith("timelapse/") else {}
    dt = parse_stamp(os.path.basename(name)) or datetime.fromtimestamp(st.st_mtime)
    snap = os.path.splitext(name)[0] + ".jpg" if is_video else None
    if snap and not rec_path(snap):
        snap = None
    gps = rec_gps(os.path.basename(name), meta, os.path.dirname(p), os.path.basename(snap) if snap else None)
    pdf = MiniPDF()
    pdf.text(T("Event report"), 18, bold=True); pdf.space(2)
    pdf.text(((CFG["device_name"] + " · ") if CFG["device_name"] else "") + "Motion Watch " + APP_VERSION, 10, color=(0.35, 0.35, 0.35))
    pdf.line()
    rows = [(T("Date / time"), dt.strftime("%d.%m.%Y %H:%M:%S")), (T("File"), name),
            (T("Kind"), T("Video") if is_video else T("Picture")), (T("Size"), f"{st.st_size / 1e6:.1f} MB")]
    if meta.get("duration") is not None:
        rows.append((T("Duration"), f"{meta['duration']:.0f} s"))
    if meta.get("persons"):
        rows.append((T("Persons seen"), str(meta["persons"])))
    if meta.get("source"):
        rows.append((T("Camera"), str(meta["source"])))
    if meta.get("false"):
        rows.append((T("Marked as"), T("false alarm")))
    if gps:
        rows.append((T("Place"), f"{gps[0]:.5f}, {gps[1]:.5f}"))
        rows.append(("", osm_link(gps[0], gps[1])))
    else:
        rows.append((T("Place"), T("unknown")))
    for k, v in rows:
        pdf.text((k + ": " if k else "    ") + v, 10)
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    pdf.space(4); pdf.text(T("Checksum of the original file (SHA-256) - shows that it was not changed:"), 8, color=(0.35, 0.35, 0.35))
    pdf.text(h.hexdigest(), 8, color=(0.35, 0.35, 0.35))
    pdf.line(); pdf.text(T("Pictures"), 13, bold=True); pdf.space(2)
    pics = []
    if snap or not is_video:
        img = cv2.imread(rec_path(snap) if snap else p)
        if img is not None:
            pics.append((T("Alarm picture"), img))
    if is_video:
        cap = cv2.VideoCapture(p)
        try:
            n = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0); fps = cap.get(cv2.CAP_PROP_FPS) or 0
            for frac in ((0.1, 0.5, 0.9) if n > 10 else ()):
                cap.set(cv2.CAP_PROP_POS_FRAMES, int(n * frac)); ok, fr = cap.read()
                if ok and fr is not None:
                    pics.append((T("From the video") + (f" ({int(n * frac / fps)} s)" if fps else ""), fr))
        finally:
            cap.release()
    for cap_, img in pics[:4]:
        j = _report_jpg(img)
        if j:
            pdf.image(*j, caption=cap_)
    if not pics:
        pdf.text(T("no picture"), 10)
    pdf.line(); pdf.text(T("Log around the event (10 minutes before and after)"), 13, bold=True); pdf.space(2)
    lines = _report_log(dt)
    for ln in lines or [T("no entries")]:
        pdf.text(ln, 7.5, gap=1.25)
    pdf.space(6); pdf.text(T("Created") + ": " + datetime.now().strftime("%d.%m.%Y %H:%M") + " · " + T("The original video file is on the device (recordings)."), 8, color=(0.35, 0.35, 0.35))
    return pdf.output()


def rec_path(name):
    """Absolute path of a file in the recordings folder, or None (guards against path tricks like ../).
    "timelapse/<file>" = a timelapse photo or video (shown in the recordings list too)."""
    if isinstance(name, str) and name.startswith("timelapse/"):
        return tl_path(name[10:])
    if isinstance(name, str) and LOOP_RE.match(name):
        p = os.path.join(rec_dir(), name)
        return p if os.path.isfile(p) else None
    if not isinstance(name, str) or not REC_NAME_RE.match(name) or ".." in name:
        return None
    p = os.path.join(rec_dir(), name)
    return p if os.path.isfile(p) else None


def parse_stamp(name):
    m = _STAMP_RE.search(name)
    if not m:
        return None
    try:
        return datetime.strptime(m.group(1) + m.group(2), "%Y%m%d%H%M%S")
    except ValueError:
        return None


def _read_sidecar(name):
    try:
        with open(os.path.join(rec_dir(), os.path.splitext(name)[0] + ".json")) as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def rec_meta(name, st, probe=False):
    """Info about a video: the info file, completed by looking into the file itself (codec, duration) when asked."""
    e = _REC_META.get(name)
    if e is None or e[0] != st.st_mtime or e[1] != st.st_size:
        e = _REC_META[name] = [st.st_mtime, st.st_size, _read_sidecar(name), False]
        if len(_REC_META) > 5000:                           # keep the cache small
            for k in list(_REC_META)[:1000]:
                _REC_META.pop(k, None)
    meta = e[2]
    if probe and not e[3] and not (meta.get("codec") and meta.get("duration") is not None):
        e[3] = True
        cap = None
        try:
            cap = cv2.VideoCapture(os.path.join(rec_dir(), name))
            if cap.isOpened():
                v = int(cap.get(cv2.CAP_PROP_FOURCC))
                fps = cap.get(cv2.CAP_PROP_FPS) or 0.0
                frames = cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0.0
                meta.setdefault("codec", "".join(chr((v >> (8 * i)) & 0xFF) for i in range(4)).strip().lower())
                if meta.get("duration") is None and fps > 0 and frames > 0:
                    meta["duration"] = round(frames / fps, 1)
        except Exception:
            pass
        finally:
            if cap is not None:
                cap.release()
    return meta


def _parse_day(s):
    try:
        return datetime.strptime(str(s), "%Y-%m-%d")
    except ValueError:
        return None


def list_recordings(args, watch=None):
    """Filtered, sorted, paged list of recordings. Filters: kind, from, to, schedule, source, q, sort, offset, limit."""
    d = rec_dir()
    try:
        names = os.listdir(d)
    except OSError:
        names = []
    files, total_bytes = {}, 0
    for n in names:
        if n.startswith(".") or not REC_NAME_RE.match(n):
            continue
        stem, ext = os.path.splitext(n)
        try:
            st = os.stat(os.path.join(d, n))
        except OSError:
            continue
        total_bytes += st.st_size
        kind = REC_EXTS.get(ext.lower())
        if kind:
            files.setdefault(stem, {})[kind] = (n, st)
    with LOCK:
        plans = [dict(s) for s in SCHEDULES]
    live = watch.rec_name if watch is not None else ""
    live_set = {n for n in LIVE_RECS if not n.startswith("loop/")} | ({live} if live else set())

    items = []
    for stem, kinds in files.items():
        if "video" in kinds:
            n, st = kinds["video"]; kind = "video"; snap = kinds.get("image")
        else:
            n, st = kinds["image"]; kind = "image"; snap = None
        dt = parse_stamp(n) or datetime.fromtimestamp(st.st_mtime)
        meta = rec_meta(n, st)
        items.append({"n": n, "st": st, "kind": kind, "dt": dt, "meta": meta, "snap": snap[0] if snap else None,
                      "sched": [i for i, s in enumerate(plans) if schedule_window_contains(s, dt)],
                      "gps": rec_gps(n, meta, d, snap[0] if snap else None)})
    # timelapse: the videos always, the single photos only with the filter "Timelapse"
    kind_req = args.get("kind", "")
    if kind_req in ("", "timelapse", "video"):
        try:
            tl_names = os.listdir(tl_dir())
        except OSError:
            tl_names = []
        for n in tl_names:
            is_v = bool(TL_VIDEO_RE.match(n))
            if not is_v and not (kind_req == "timelapse" and TL_PHOTO_RE.match(n)):
                continue
            try:
                st = os.stat(os.path.join(tl_dir(), n))
            except OSError:
                continue
            name = "timelapse/" + n
            dt = parse_stamp(n) or datetime.fromtimestamp(st.st_mtime)
            meta = dict(rec_meta(name, st)); meta.setdefault("source", "Timelapse")
            items.append({"n": name, "st": st, "kind": "video" if is_v else "image", "dt": dt, "meta": meta, "snap": None,
                          "sched": [], "tl": True, "gps": rec_gps(n, meta, tl_dir()) if not is_v else None})

    # filters that do not depend on the schedule
    kind_f, src_f, q = args.get("kind", ""), args.get("source", ""), (args.get("q", "") or "").strip().lower()
    d_from, d_to = _parse_day(args.get("from", "")), _parse_day(args.get("to", ""))
    sources = sorted({it["meta"].get("source") for it in items if it["meta"].get("source")})
    places = places_assign(items)
    no_place = sum(1 for it in items if not it.get("gps"))
    if kind_f in ("video", "image"):
        items = [it for it in items if it["kind"] == kind_f]
    elif kind_f == "timelapse":
        items = [it for it in items if it.get("tl")]
    if d_from:
        items = [it for it in items if it["dt"] >= d_from]
    if d_to:
        items = [it for it in items if it["dt"] < d_to.replace(hour=0) + timedelta(days=1)]
    if src_f:
        items = [it for it in items if it["meta"].get("source") == src_f]
    if q:
        items = [it for it in items if q in it["n"].lower()]
    pl_f = args.get("place", "")
    if pl_f == "none":
        items = [it for it in items if not it.get("gps")]
    elif pl_f:
        items = [it for it in items if it.get("place") == pl_f]

    if args.get("fa") == "1":
        items = [it for it in items if it["meta"].get("false")]
    if args.get("fav") == "1":
        items = [it for it in items if it["meta"].get("fav")]
    counts = {"all": len(items), "any": sum(1 for it in items if it["sched"]), "none": sum(1 for it in items if not it["sched"])}
    for i in range(len(plans)):
        counts[str(i)] = sum(1 for it in items if i in it["sched"])
    sch_f = args.get("schedule", "")
    if sch_f == "any":
        items = [it for it in items if it["sched"]]
    elif sch_f == "none":
        items = [it for it in items if not it["sched"]]
    elif sch_f.isdigit():
        items = [it for it in items if int(sch_f) in it["sched"]]

    sort = args.get("sort", "new")
    if sort == "old":
        items.sort(key=lambda it: it["dt"])
    elif sort == "size":
        items.sort(key=lambda it: it["st"].st_size, reverse=True)
    else:
        items.sort(key=lambda it: it["dt"], reverse=True)

    try:
        offset = max(0, int(args.get("offset", 0))); limit = max(1, min(200, int(args.get("limit", 48))))
    except (TypeError, ValueError):
        offset, limit = 0, 48
    page = []
    for it in items[offset:offset + limit]:
        meta = rec_meta(it["n"], it["st"], probe=True) if it["kind"] == "video" else it["meta"]
        codec = (meta.get("codec") or "").lower()
        page.append({"name": it["n"], "kind": it["kind"], "time": it["dt"].strftime("%Y-%m-%d %H:%M:%S"),
                     "size": it["st"].st_size, "duration": meta.get("duration"), "source": meta.get("source"),
                     "persons": meta.get("persons"), "schedules": [plans[i]["name"] for i in it["sched"]],
                     "playable": (codec in BROWSER_CODECS) if codec else None, "snap": it["snap"], "fav": bool(meta.get("fav")),
                     "recording": it["n"] in live_set, "timelapse": bool(it.get("tl")), "gps": it.get("gps"), "place": it.get("place"),
                     "false": it["meta"].get("false")})
    now = datetime.now()
    points = None
    if args.get("map") == "1":                      # every filtered recording with a location (for the map)
        points = [{"name": it["n"], "kind": it["kind"], "time": it["dt"].strftime("%Y-%m-%d %H:%M:%S"), "size": it["st"].st_size,
                   "lat": it["gps"][0], "lon": it["gps"][1], "place": it.get("place"), "source": it["meta"].get("source"),
                   "duration": it["meta"].get("duration"), "fav": bool(it["meta"].get("fav")), "timelapse": bool(it.get("tl")),
                   "schedules": [plans[i]["name"] for i in it["sched"]], "persons": it["meta"].get("persons"), "snap": it["snap"],
                   "recording": it["n"] in live_set}
                  for it in items if it.get("gps")][:3000]
    return {"total": len(items), "items": page, "counts": counts, "sources": sources, "recording": bool(live_set),
            "places": places, "no_place": no_place, "points": points, "map_online": bool(CFG["map_online"]),
            "schedules": [{"index": i, "name": s["name"], "enabled": s["enabled"], "days": s["days"], "start": s["start"],
                           "end": s["end"], "active_now": schedule_active(s, now), "count": counts.get(str(i), 0)}
                          for i, s in enumerate(plans)],
            "disk": {"files": len(files), "mb": int(total_bytes / 1024 ** 2), "limit_gb": CFG["record_max_gb"]},
            "ffmpeg": shutil.which("ffmpeg") is not None}


def _write_sidecar(name, meta):
    stem = os.path.splitext(name)[0]
    p = os.path.join(rec_dir(), stem + ".json")
    tmp = p + ".tmp"
    try:
        with open(tmp, "w") as f:
            json.dump(meta, f)
        os.replace(tmp, p)
    except OSError:
        return False
    for k in (stem + ".mp4", stem + ".jpg"):
        _REC_META.pop(k, None)
    return True


FA_CAUSES = ("animal", "wind", "light", "rain", "car", "other")


def rec_set_false(names, cause, watch=None):
    """Mark recordings as false alarm (cause) or as real again (cause empty)."""
    n = 0
    for name in (names if isinstance(names, list) else [])[:500]:
        if not rec_path(name) or name.lower().endswith(".json") or name.startswith("timelapse/") or _is_live(name, watch):
            continue
        meta = _read_sidecar(name)
        if cause in FA_CAUSES:
            meta["false"] = cause; meta["false_t"] = int(time.time())
        else:
            meta.pop("false", None); meta.pop("false_t", None)
        if _write_sidecar(name, meta):
            n += 1
    if n:
        log_event("rec", f"{n} recording(s) marked as " + (f"false alarm ({cause})" if cause in FA_CAUSES else "real"))
    return n


def fa_suggestions(lang=None, days=14):
    """Look at the recordings marked «was nothing» and suggest settings that would have avoided them."""
    L = norm_lang(lang) if lang else cur_lang()
    since = datetime.now() - timedelta(days=days)
    total, causes = 0, {}
    d = rec_dir()
    try:
        names = os.listdir(d)
    except OSError:
        names = []
    stems = {}
    for n in names:
        st_, ext = os.path.splitext(n)
        if ext.lower() in (".mp4", ".jpg") and REC_NAME_RE.match(n):
            stems.setdefault(st_, n if ext.lower() == ".mp4" else stems.get(st_, n))
    for st_, n in stems.items():
        dt = parse_stamp(n)
        if dt is None or dt < since:
            continue
        total += 1
        c = _read_sidecar(n).get("false")
        if c in FA_CAUSES:
            causes[c] = causes.get(c, 0) + 1
    nf = sum(causes.values())
    out = []

    def sug(sid, text, changes, n):
        ch = {k: v for k, v in changes.items() if k in CFG and CFG[k] != v}
        if ch:
            out.append({"id": sid, "text": tr(text, L), "n": n, "changes": ch})

    if causes.get("animal", 0) >= 2:
        sug("animal", "Alarm only when the AI confirms a person (animals no longer count)", {"ai_enabled": True, "ai_require": True}, causes["animal"])
    if causes.get("wind", 0) >= 2:
        if not CFG["wind_auto"]:
            sug("wind", "Switch on the automatic wind detection", {"wind_auto": True}, causes["wind"])
        else:
            sug("wind", "Ignore small movements (branches, grass): bigger minimum size", {"min_area": round(min(8000, CFG["min_area"] * 1.3))}, causes["wind"])
    if causes.get("light", 0) >= 2:
        if not CFG["shadow_filter"] or not CFG["lowlight_auto"]:
            sug("light", "Switch on the shadow filter and the low-light automatic", {"shadow_filter": True, "lowlight_auto": True}, causes["light"])
        else:
            sug("light", "Less sensitive to light changes", {"sensitivity": max(10, CFG["sensitivity"] - 10)}, causes["light"])
    if causes.get("rain", 0) >= 2:
        if not CFG["rain_auto"]:
            sug("rain", "Switch on the automatic rain detection", {"rain_auto": True}, causes["rain"])
        else:
            sug("rain", "Detect rain earlier", {"rain_threshold": round(max(0.15, CFG["rain_threshold"] - 0.05), 2)}, causes["rain"])
    if causes.get("car", 0) >= 2:
        if not CFG["car_filter"]:
            sug("car", "Switch on the vehicle filter", {"car_filter": True}, causes["car"])
        else:
            out.append({"id": "zones", "text": tr("Draw an ignore zone over the road (tab Zones)", L), "n": causes["car"], "changes": {}, "link": "/zones"})
    if nf >= 5 and nf >= 0.4 * max(1, total) and not out:
        sug("sens", "Somewhat less sensitive overall", {"sensitivity": max(10, CFG["sensitivity"] - 10)}, nf)
    return {"days": days, "total": total, "false": nf, "causes": causes, "suggestions": out}


def fa_apply(sid, lang=None):
    for x in fa_suggestions(lang)["suggestions"]:
        if x["id"] == sid and x["changes"]:
            for k, v in x["changes"].items():
                CFG[k] = v; sched_user_changed(k)
            save_settings()
            log_event("sys", "False alarms: settings taken over - " + ", ".join(f"{k}={v}" for k, v in x["changes"].items()))
            return True
    return False


def rec_set_fav(names, value, watch=None):
    """Star / un-star recordings. Starred recordings are never removed by the automatic cleanup."""
    n = 0
    for name in (names if isinstance(names, list) else [])[:500]:
        if rec_path(name) and not name.lower().endswith(".json") and _is_live(name, watch):
            def later(nm=name):                          # 2.95.34: still being written - star it when it is finished
                for _ in range(80):
                    time.sleep(15)
                    if not _is_live(nm, watch):
                        rec_set_fav([nm], value, watch); return
            threading.Thread(target=later, daemon=True).start()
            n += 1
            continue
        if not rec_path(name) or name.lower().endswith(".json"):
            continue
        meta = _read_sidecar(name)
        if value:
            meta["fav"] = True
        else:
            meta.pop("fav", None)
        if _write_sidecar(name, meta):
            n += 1
    return n


def rec_clean_tmp():
    tdir = os.path.join(rec_dir(), ".tmp")
    try:
        for f in os.listdir(tdir):
            p = os.path.join(tdir, f)
            if time.time() - os.path.getmtime(p) > 3600:
                os.remove(p)
    except OSError:
        pass


_ZIP_LOCK = threading.Lock()


def rec_zip(names, watch=None):
    """Pack recordings (video + snapshot) into one ZIP in the temp folder. Returns the path or None.
    2.95.34: one at a time, only when there is room for it (+ 500 MB), nothing left behind after an error."""
    if not _ZIP_LOCK.acquire(blocking=False):
        return None
    tmp = None
    try:
        files, seen = [], set()
        for name in (names if isinstance(names, list) else [])[:300]:
            if not rec_path(name) or _is_live(name, watch):
                continue
            stem, ext = os.path.splitext(name)
            for e in ((".mp4", ".jpg") if ext.lower() == ".mp4" else (ext.lower(),)):
                p = os.path.join(rec_dir(), stem + e)
                if os.path.isfile(p) and p not in seen:
                    seen.add(p); files.append(p)
        if not files:
            return None
        need = sum(os.path.getsize(p) for p in files) + 500 * (1 << 20)
        if shutil.disk_usage(rec_dir()).free < need:
            log_event("rec", "ZIP download refused: not enough free space on the drive")
            return None
        tdir = os.path.join(rec_dir(), ".tmp")
        os.makedirs(tdir, exist_ok=True)
        fd, tmp = tempfile.mkstemp(suffix=".zip", dir=tdir); os.close(fd)
        with zipfile.ZipFile(tmp, "w", zipfile.ZIP_STORED, allowZip64=True) as z:
            for p in files:
                z.write(p, os.path.basename(p))
        return tmp
    except Exception as e:
        log_event("rec", f"ZIP failed: {e}"[:160])
        if tmp:
            try:
                os.remove(tmp)
            except OSError:
                pass
        return None
    finally:
        _ZIP_LOCK.release()


def _scan_events():
    """[(datetime, name, kind)] - one entry per recorded event (the video if there is one, else the picture)."""
    d = rec_dir()
    try:
        names = os.listdir(d)
    except OSError:
        return []
    files = {}
    for n in names:
        if n.startswith(".") or not REC_NAME_RE.match(n):
            continue
        stem, ext = os.path.splitext(n)
        kind = REC_EXTS.get(ext.lower())
        if kind:
            files.setdefault(stem, {})[kind] = n
    out = []
    for stem, k in files.items():
        n = k.get("video") or k["image"]
        dt = parse_stamp(n)
        if dt is None:
            try:
                dt = datetime.fromtimestamp(os.path.getmtime(os.path.join(d, n)))
            except OSError:
                continue
        out.append((dt, n, "video" if "video" in k else "image"))
    return out


_STATS = {"t": 0.0, "key": None, "val": None}


def rec_stats(days=14, day=None):
    """Events per day / hour for the statistics card of the preview page + the events of one day for the timeline."""
    try:
        days = max(1, min(90, int(days)))
    except (TypeError, ValueError):
        days = 14
    key = (days, day, len(os.listdir(rec_dir())) if os.path.isdir(rec_dir()) else 0)
    if _STATS["key"] == key and time.time() - _STATS["t"] < 10:
        return _STATS["val"]
    events = _scan_events()
    today = datetime.now().date(); start = today - timedelta(days=days - 1)
    per_day, heat = {}, [[0] * 24 for _ in range(7)]
    for dt, name, kind in events:
        dd = dt.date()
        if start <= dd <= today:
            per_day.setdefault(dd, [0] * 24)[dt.hour] += 1
            heat[dt.weekday()][dt.hour] += 1
    lst = []
    for i in range(days):
        dd = start + timedelta(days=i); hrs = per_day.get(dd, [0] * 24)
        lst.append({"date": dd.isoformat(), "hours": hrs, "count": sum(hrs)})
    ev = []
    dd = _parse_day(day) if day else None
    if dd:
        ev = sorted(({"m": dt.hour * 60 + dt.minute, "t": dt.strftime("%H:%M:%S"), "name": n, "kind": k}
                     for dt, n, k in events if dt.date() == dd.date()), key=lambda e: e["m"])
    val = {"days": lst, "heat": heat, "events": ev, "day": day, "total": len(events)}
    _STATS.update(t=time.time(), key=key, val=val)
    return val


def rec_thumb(name):
    """Path of a small cached JPEG thumbnail (320 px wide) for a video or snapshot, or None."""
    path = rec_path(name)
    if not path:
        return None
    tdir = os.path.join(rec_dir(), ".thumbs")
    tp = os.path.join(tdir, name + ".jpg")
    try:
        if os.path.isfile(tp) and os.path.getmtime(tp) >= os.path.getmtime(path):
            return tp
        os.makedirs(os.path.dirname(tp), exist_ok=True)
        img = None
        if name.lower().endswith(".jpg"):
            img = cv2.imread(path)
        else:
            snap = path[:-4] + ".jpg"                          # the snapshot of the same event is the cheapest thumbnail
            if os.path.isfile(snap):
                img = cv2.imread(snap)
            if img is None:
                cap = cv2.VideoCapture(path)
                try:
                    ok, img = cap.read()
                    img = img if ok else None
                finally:
                    cap.release()
        if img is None:
            return None
        h, w = img.shape[:2]
        img = cv2.resize(img, (320, max(1, int(h * 320 / w))), interpolation=cv2.INTER_AREA)
        cv2.imwrite(tp, img, [cv2.IMWRITE_JPEG_QUALITY, 72])
        return tp
    except Exception:
        return None


def _cache_path(name):
    return os.path.join(rec_dir(), ".cache", os.path.splitext(name)[0] + ".h264.mp4")


def _transcode(name, src, dst):
    tmp = dst + ".part.mp4"
    try:
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        cmd = (["nice", "-n", "10"] if shutil.which("nice") else []) + [
            "ffmpeg", "-y", "-loglevel", "error", "-i", src, "-c:a", "aac", "-b:a", "64k", "-c:v", "libx264", "-preset", "veryfast",
            "-crf", "26", "-pix_fmt", "yuv420p", "-movflags", "+faststart", tmp]
        with _TRANSCODE_SEM:
            r = subprocess.run(cmd, capture_output=True, timeout=1800)
        if r.returncode != 0:
            raise RuntimeError(r.stderr.decode(errors="replace").strip()[-200:] or f"ffmpeg exit {r.returncode}")
        os.replace(tmp, dst)
        _TRANSCODE[name] = "done"
    except Exception as e:
        _TRANSCODE[name] = f"error: {e}"
        try:
            os.remove(tmp)
        except OSError:
            pass


def rec_play_state(name, watch=None):
    """What the browser can play for this video: ready (url) / converting / unsupported / error / missing."""
    path = rec_path(name)
    if not path or not name.lower().endswith(".mp4"):
        return {"state": "missing"}
    if _is_live(name, watch):
        return {"state": "live"}                                # still being written, the file is not complete yet
    try:
        meta = rec_meta(name, os.stat(path), probe=True)
    except OSError:
        return {"state": "missing"}
    if (meta.get("codec") or "").lower() in BROWSER_CODECS:
        return {"state": "ready", "url": "/rec/file/" + name}
    dst = _cache_path(name)
    if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(path):
        return {"state": "ready", "url": "/rec/play/" + name}
    if shutil.which("ffmpeg") is None:
        return {"state": "unsupported", "url": "/rec/file/" + name + "?dl=1"}
    with _TRANSCODE_LOCK:
        cur = _TRANSCODE.get(name, "")
        if cur == "running":
            return {"state": "converting"}
        if cur.startswith("error"):
            _TRANSCODE.pop(name, None)
            return {"state": "error", "error": cur[7:]}
        _TRANSCODE[name] = "running"
    threading.Thread(target=_transcode, args=(name, path, dst), daemon=True).start()
    return {"state": "converting"}


def rec_purge_extras(stem):
    """Remove cached thumbnails / converted copies that belong to a recording."""
    for p in (os.path.join(rec_dir(), ".thumbs", stem + ".mp4.jpg"), os.path.join(rec_dir(), ".thumbs", stem + ".jpg.jpg"),
              os.path.join(rec_dir(), ".cache", stem + ".h264.mp4"), os.path.join(rec_dir(), ".cache", stem + ".nogps.mp4"),
              os.path.join(rec_dir(), ".cache", stem + ".share.mp4"), os.path.join(rec_dir(), ".cache", stem + ".share.gps.mp4")):
        try:
            os.remove(p)
        except OSError:
            pass
    for k in (stem + ".mp4", stem + ".jpg"):
        _REC_META.pop(k, None); _TRANSCODE.pop(k, None)


def rec_delete(names, watch=None):
    """Delete recordings (video + snapshot + info file of each). Returns how many were deleted."""
    n_ok = 0
    for name in (names if isinstance(names, list) else [])[:500]:
        path = rec_path(name)
        if not path or _is_live(name, watch) or os.path.splitext(name)[1].lower() not in (".mp4", ".jpg"):
            continue
        stem = os.path.splitext(name)[0]
        for ext in ((".mp4", ".jpg", ".json") if name.lower().endswith(".mp4") else (os.path.splitext(name)[1].lower(),)):
            try:
                os.remove(os.path.join(rec_dir(), stem + ext))
            except OSError:
                pass
        rec_purge_extras(stem)
        n_ok += 1
    if n_ok:
        log_event("rec", f"{n_ok} recording(s) deleted from the preview page")
    return n_ok


# ----------------------------------------------------------------------------
# More cameras at the same time (motion recording only: no AI, no servos)
#   The first camera (the "source") does the full job. Extra cameras watch for movement, record clips (cam<n>_<time>.mp4 + snapshot)
#   and can be viewed in the grid at /cams. They follow the same switches (detection, recording) and schedules.
# ----------------------------------------------------------------------------
CAMS = []
LIVE_RECS = set()                    # file names that are being written right now (never deleted / zipped)
WATCH_REF = {"w": None}


def _is_live(name, watch=None):
    return name in LIVE_RECS or (watch is not None and bool(watch.rec_name) and watch.rec_name == name)


class ExtraCam:
    def __init__(self, idx, spec):
        self.idx, self.spec = idx, spec
        self.stop = False
        self.jpeg = None; self.seq = 0; self.viewers = 0; self._enc_t = 0.0
        self.status = "connecting…"; self.label = source_label(spec); self.res = ""; self.fps = 0.0
        self.motion = False; self.recording = False
        self.writer = None; self.rec_name = ""; self.rec_info = None; self.last_motion = 0.0; self.streak = 0
        self.boxes = []; self.times = deque(maxlen=30); self.n = 0; self.last_cleanup = 0.0
        self.thread = threading.Thread(target=self.loop, daemon=True); self.thread.start()

    def info(self):
        return {"n": self.idx, "id": self.spec, "label": self.label, "status": self.status, "res": self.res,
                "fps": round(self.fps, 1), "motion": self.motion, "recording": self.recording}

    def close(self):
        self.stop = True
        self.thread.join(4.0)
        self._stop_rec()

    def _sleep(self, sec):
        end = time.time() + sec
        while not self.stop and time.time() < end:
            time.sleep(0.2)

    def loop(self):
        while not self.stop:
            if toolmode_on():                                    # tool mode: this camera rests too
                self.status = "tool mode"; self.motion = False; self._sleep(1.0); continue
            src, sid, label, err = open_source(self.spec)
            if src is None:
                self.status = f"failed: {err}"; self._sleep(6.0); continue
            self.label = label; self.status = "connected"
            self.res = f"{src.size[0]}x{src.size[1]}" if getattr(src, "size", None) else ""
            bg = cv2.createBackgroundSubtractorMOG2(history=300, varThreshold=28, detectShadows=False)
            fails, self.n = 0, 0
            try:
                while not self.stop:
                    if toolmode_on():
                        break
                    ok, frame = src.read()
                    if not ok:
                        fails += 1
                        if fails >= 60:
                            break
                        time.sleep(0.05); continue
                    fails = 0
                    self._process(frame, bg)
            except Exception as e:
                log_event("sys", f"Camera {self.label}: {e}")
            finally:
                src.release(); self._stop_rec()
            if not self.stop and not toolmode_on():
                self.status = "connection lost - reconnecting"; self.motion = False; self._sleep(2.0)

    def _process(self, frame, bg):
        t0 = time.time()
        self.n += 1
        H, W = frame.shape[:2]
        if self.n % 2 == 0 or not self.times:                  # detection on every 2nd frame is enough
            pw = 320; ph = max(1, int(H * pw / W)); sx = W / pw; sy = H / ph
            gray = cv2.GaussianBlur(cv2.cvtColor(cv2.resize(frame, (pw, ph)), cv2.COLOR_BGR2GRAY), (5, 5), 0)
            fg = bg.apply(gray)
            fg = cv2.dilate(cv2.erode(cv2.threshold(fg, 200, 255, cv2.THRESH_BINARY)[1], None, iterations=1), None, iterations=2)
            cnts, _ = cv2.findContours(fg, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            amin = CFG["min_area"] * (1.0 - CFG["sensitivity"] / 200.0) * (320.0 / 480.0) ** 2
            self.boxes = [(int(x * sx), int(y * sy), int(w * sx), int(h * sy)) for x, y, w, h in
                          (cv2.boundingRect(c) for c in cnts if cv2.contourArea(c) >= amin)] if self.n > 30 else []
            self.motion = bool(self.boxes) and CFG["detection_on"]
            self.streak = self.streak + 1 if self.motion else 0
        now = time.time()
        if self.motion and self.streak >= 3:
            self.last_motion = now
        for x, y, w, h in self.boxes:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 255, 255), 1)
        cv2.rectangle(frame, (0, 0), (W, 26), (0, 0, 0), -1)
        cv2.putText(frame, self.label.encode("ascii", "replace").decode()[:40] + ("   MOTION" if self.motion else ""), (8, 19),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.55, (80, 160, 255) if self.motion else (230, 230, 230), 1, cv2.LINE_AA)
        want = CFG["record"] and CFG["detection_on"] and self.last_motion > 0 and now - self.last_motion < CFG["record_tail"]
        if want and self.writer is None:
            self._start_rec(frame)
        elif not want and self.writer is not None:
            self._stop_rec()
        if self.writer is not None:
            self.writer.write(frame); self.rec_info["frames"] += 1
        self.recording = self.writer is not None
        self.times.append(time.time() - t0)
        if self.n % 15 == 0:
            self.fps = 1.0 / max(1e-3, np.mean(self.times)) if self.times else 0.0
        if self.viewers > 0 and now - self._enc_t >= 0.1:        # only encode while somebody watches
            self._enc_t = now
            out = frame if W <= 640 else cv2.resize(frame, (640, int(H * 640 / W)), interpolation=cv2.INTER_AREA)
            ok, buf = cv2.imencode(".jpg", out, [cv2.IMWRITE_JPEG_QUALITY, 65])
            if ok:
                self.jpeg = buf.tobytes(); self.seq += 1

    def _start_rec(self, frame):
        if CFG.get("sim_on"):
            self.last_motion = 0.0; return                 # simulation: no recordings
        h, w = frame.shape[:2]
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        base = f"cam{self.idx}_{stamp}"
        wr, codec = open_writer(os.path.join(CFG["record_dir"], base + ".mp4"), 12.0, (w, h))
        if wr is None:
            self.last_motion = 0.0; return
        if time.time() - self.last_cleanup > 60 and WATCH_REF["w"] is not None:
            WATCH_REF["w"].cleanup_recordings(); self.last_cleanup = time.time()
        if CFG["snapshot_on_person"]:
            cv2.imwrite(os.path.join(CFG["record_dir"], base + ".jpg"), frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
            gps_tag_jpg(os.path.join(CFG["record_dir"], base + ".jpg"))
        self.writer = wr; self.rec_name = base + ".mp4"; LIVE_RECS.add(self.rec_name)
        fps = max(5.0, min(30.0, self.fps or 12.0))
        self.rec_info = {"start": time.time(), "fps": fps, "frames": 0, "codec": codec, "schedules": list(SCHED["active"])}
        log_event("rec", f"Recording started: {self.rec_name} ({self.label})")

    def _stop_rec(self):
        if self.writer is None:
            return
        wr, self.writer = self.writer, None
        wr.release()
        info, name = self.rec_info, self.rec_name
        self.rec_info = None; self.recording = False
        try:
            meta = {"start": datetime.fromtimestamp(info["start"]).isoformat(timespec="seconds"),
                    "end": datetime.now().isoformat(timespec="seconds"), "frames": info["frames"],
                    "duration": round(info["frames"] / max(1.0, info["fps"]), 1), "fps": round(info["fps"], 1), "codec": info["codec"],
                    "persons": 0, "motion": True, "source": self.label, "source_id": self.spec, "schedules": info["schedules"]}
            with open(os.path.join(CFG["record_dir"], os.path.splitext(name)[0] + ".json"), "w") as f:
                json.dump(meta, f)
        except OSError:
            pass
        LIVE_RECS.discard(name); self.rec_name = ""
        log_event("rec", f"Recording stopped: {name}")


def cams_apply():
    """Start / stop the extra camera threads so they match the settings."""
    want = list(CFG["extra_cams"])
    for c in list(CAMS):
        if c.spec not in want:
            CAMS.remove(c); threading.Thread(target=c.close, daemon=True).start()
    have = {c.spec for c in CAMS}
    used = {c.idx for c in CAMS}
    for spec in want:
        if spec not in have:
            idx = next(i for i in range(1, 99) if i not in used); used.add(idx)
            CAMS.append(ExtraCam(idx, spec))


def cams_status(watch=None):
    main = {"n": 0, "id": STATE["source_id"] or CFG["source"], "label": STATE["source_label"] or source_label(CFG["source"]),
            "status": STATE["source_status"], "res": STATE["source_res"], "fps": STATE["fps"],
            "motion": bool(STATE["persons"] or STATE["candidates"]), "recording": STATE["recording"]}
    return [main] + [c.info() for c in CAMS]


def cams_add(spec):
    if not isinstance(spec, str) or not SRC_RE.match(spec) or spec == "auto":
        return False, "unknown source"
    if spec.startswith("url:") and not find_ip_source(spec[4:]):
        return False, "unknown network camera"
    if spec in CFG["extra_cams"] or spec == STATE["source_id"]:
        return False, "this camera is already in use"
    if len(CFG["extra_cams"]) >= MAX_EXTRA:
        return False, f"maximum {MAX_EXTRA} extra cameras"
    CFG["extra_cams"] = CFG["extra_cams"] + [spec]
    save_settings(); cams_apply(); log_event("sys", f"Extra camera added: {source_label(spec)}")
    return True, ""


def cams_remove(spec):
    if spec not in CFG["extra_cams"]:
        return False, "unknown source"
    CFG["extra_cams"] = [x for x in CFG["extra_cams"] if x != spec]
    save_settings(); cams_apply(); log_event("sys", f"Extra camera removed: {source_label(spec)}")
    return True, ""


def cams_close_all():
    for c in list(CAMS):
        c.stop = True
    for c in list(CAMS):
        c.thread.join(3.0); c._stop_rec()


atexit.register(cams_close_all)


